    linked_sop_section text,
    training_module_id uuid,
    training_section_id text,
    source_document_id uuid,
    tags text[] DEFAULT '{}'::text[],
    ai_generated boolean DEFAULT false,
    ai_model_used text,
    ai_confidence_score numeric,
    ai_prompt_used text,
    version integer DEFAULT 1,
    reviewed_by uuid,
    reviewed_at timestamp with time zone,
    review_notes text,
    created_by uuid,
    created_at timestamp with time zone DEFAULT now(),
    updated_at timestamp with time zone DEFAULT now(),
    accepted_answers text[] DEFAULT '{}'::text[],
    bloom_level text,
    cognitive_domain text,
    question_bank_id uuid,
    distractor_rationales jsonb,
    rubric jsonb,
    organization_id uuid NOT NULL,
    brand_id uuid,
    hotel_id uuid,
    is_master_template boolean DEFAULT false NOT NULL,
    master_source_id uuid
);

