CREATE OR REPLACE FUNCTION public._assign_module_to_user(p_org_id uuid, p_user_id uuid, p_module_id uuid, p_due_date timestamp with time zone, p_is_mandatory boolean, p_assigned_by uuid, p_hotel_id uuid, p_department_id uuid, p_note text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_rule_id uuid;
BEGIN
  SELECT r.id INTO v_rule_id
    FROM public.training_assignment_rules r
   WHERE r.organization_id = p_org_id
     AND r.target_type = 'user' AND r.target_id = p_user_id::text
     AND r.content_type = 'module' AND r.content_id = p_module_id
     AND r.is_active AND NOT COALESCE(r.is_deleted, false)
   LIMIT 1;
  IF v_rule_id IS NOT NULL THEN
    RETURN NULL;  -- already assigned
  END IF;

  INSERT INTO public.training_assignment_rules (
    organization_id, target_type, target_id, content_type, content_id, training_module_id,
    hotel_id, department_id, scope_type, due_date, is_mandatory, priority,
    assigned_by, created_by, is_active, status, instructions
  ) VALUES (
    p_org_id, 'user', p_user_id::text, 'module', p_module_id, p_module_id,
    p_hotel_id, p_department_id, 'individual', p_due_date, COALESCE(p_is_mandatory, false),
    CASE WHEN p_is_mandatory THEN 'high' ELSE 'normal' END,
    p_assigned_by, p_assigned_by, true, 'active', p_note
  ) RETURNING id INTO v_rule_id;

  INSERT INTO public.training_progress (user_id, training_id, lp_content_type, assignment_id, organization_id, status)
  VALUES (p_user_id, p_module_id, 'module', v_rule_id, p_org_id, 'not_started'::training_status)
  ON CONFLICT (user_id, training_id) DO UPDATE
    SET assignment_id = COALESCE(public.training_progress.assignment_id, EXCLUDED.assignment_id),
        updated_at = now();

  RETURN v_rule_id;
END;
$function$
;

CREATE OR REPLACE FUNCTION public._auto_assign_new_hire_impl(new organization_memberships)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_rule record;
  v_path record;
  v_path_module record;
  v_module_id uuid;
BEGIN
  IF NEW.is_active IS NOT TRUE THEN RETURN; END IF;

  FOR v_rule IN
    SELECT tar.training_module_id, tar.content_id, tar.is_mandatory, COALESCE(tar.due_in_days, 14) AS due_in_days
      FROM public.training_assignment_rules tar
     WHERE tar.is_active AND NOT COALESCE(tar.is_deleted, false)
       AND tar.organization_id = NEW.organization_id
       AND public._is_standing_assignment_rule(tar.target_type, tar.target_user_ids)
       AND (tar.hotel_id IS NULL OR tar.hotel_id = NEW.hotel_id OR (tar.scope_type = 'hotel' AND tar.scope_id = NEW.hotel_id))
       AND (tar.department_id IS NULL OR tar.department_id = NEW.department_id OR (tar.scope_type = 'department' AND tar.scope_id = NEW.department_id))
       AND (tar.target_role IS NULL OR tar.target_role = 'all' OR tar.target_role = NEW.role::text)
  LOOP
    v_module_id := COALESCE(v_rule.training_module_id, v_rule.content_id);
    IF v_module_id IS NOT NULL THEN
      PERFORM public._assign_module_to_user(
        NEW.organization_id, NEW.user_id, v_module_id, now() + make_interval(days => v_rule.due_in_days),
        v_rule.is_mandatory, NEW.invited_by, NEW.hotel_id, NEW.department_id,
        'Auto-assigned upon new hire onboarding');
    END IF;
  END LOOP;

  FOR v_path IN
    SELECT tp.id AS path_id, tp.is_mandatory
      FROM public.training_paths tp
     WHERE tp.is_active = true
       AND tp.organization_id = NEW.organization_id
       AND (tp.target_property_id IS NULL OR tp.target_property_id = NEW.hotel_id)
       AND (tp.target_department_id IS NULL OR tp.target_department_id = NEW.department_id)
       AND (tp.target_role IS NULL OR tp.target_role::text = NEW.role::text)
  LOOP
    INSERT INTO public.user_path_enrollments (user_id, path_id, status, enrolled_at, created_at, updated_at)
    VALUES (NEW.user_id, v_path.path_id, 'enrolled', now(), now(), now())
    ON CONFLICT (user_id, path_id) DO NOTHING;

    FOR v_path_module IN SELECT tpm.module_id FROM public.training_path_modules tpm WHERE tpm.path_id = v_path.path_id
    LOOP
      IF v_path_module.module_id IS NOT NULL THEN
        PERFORM public._assign_module_to_user(
          NEW.organization_id, NEW.user_id, v_path_module.module_id, now() + interval '14 days',
          v_path.is_mandatory, NEW.invited_by, NEW.hotel_id, NEW.department_id,
          'Auto-assigned via onboarding path');
      END IF;
    END LOOP;
  END LOOP;
END;
$function$
;

CREATE OR REPLACE FUNCTION public._can_edit_training_module(p_module_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT EXISTS (
    SELECT 1 FROM public.training_modules m
     WHERE m.id = p_module_id
       AND public.org_visible(m.organization_id)
       AND (m.created_by = auth.uid() OR m.updated_by = auth.uid()
            OR public.is_tenant_content_editor(m.organization_id)));
$function$
;

CREATE OR REPLACE FUNCTION public._grade_question_answer(p_question_id uuid, p_selected_answer text, p_selected_options uuid[])
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_question record;
  v_is_correct boolean := false;
  v_correct_ids uuid[];
  v_selected_ids uuid[];
  v_has_options boolean;
  v_matching jsonb;
  v_relevant_count integer;
  v_match_ok boolean;
  v_opt record;
  v_selected_uuid uuid;
BEGIN
  SELECT question_type, correct_answer, accepted_answers
    INTO v_question
    FROM public.unified_questions
   WHERE id = p_question_id;

  IF NOT FOUND THEN
    RETURN false;
  END IF;

  v_has_options := EXISTS (SELECT 1 FROM public.unified_question_options WHERE question_id = p_question_id);

  CASE v_question.question_type::text
    WHEN 'mcq' THEN
      IF v_has_options THEN
        v_selected_uuid := public._safe_uuid(p_selected_answer);
        SELECT is_correct INTO v_is_correct
          FROM public.unified_question_options
         WHERE question_id = p_question_id AND id = v_selected_uuid;
        v_is_correct := COALESCE(v_is_correct, false);
      ELSE
        v_is_correct := lower(trim(COALESCE(p_selected_answer, ''))) = lower(trim(COALESCE(v_question.correct_answer, '')));
      END IF;

    WHEN 'scenario' THEN
      IF v_has_options THEN
        v_selected_uuid := public._safe_uuid(p_selected_answer);
        SELECT is_correct INTO v_is_correct
          FROM public.unified_question_options
         WHERE question_id = p_question_id AND id = v_selected_uuid;
        v_is_correct := COALESCE(v_is_correct, false);
      ELSE
        v_is_correct := public._normalize_free_text(p_selected_answer) <> ''
          AND public._normalize_free_text(p_selected_answer) = ANY (
            ARRAY(SELECT public._normalize_free_text(x) FROM unnest(
              array_prepend(v_question.correct_answer, COALESCE(v_question.accepted_answers, ARRAY[]::text[]))
            ) AS x)
          );
      END IF;

    WHEN 'true_false' THEN
      v_is_correct := lower(trim(COALESCE(p_selected_answer, ''))) = lower(trim(COALESCE(v_question.correct_answer, '')));

    WHEN 'fill_blank' THEN
      v_is_correct := public._normalize_free_text(p_selected_answer) <> ''
        AND public._normalize_free_text(p_selected_answer) = ANY (
          ARRAY(SELECT public._normalize_free_text(x) FROM unnest(
            array_prepend(v_question.correct_answer, COALESCE(v_question.accepted_answers, ARRAY[]::text[]))
          ) AS x)
        );

    WHEN 'mcq_multi' THEN
      SELECT array_agg(id ORDER BY id) INTO v_correct_ids
        FROM public.unified_question_options
       WHERE question_id = p_question_id AND is_correct = true;
      SELECT array_agg(DISTINCT x ORDER BY x) INTO v_selected_ids
        FROM unnest(COALESCE(p_selected_options, ARRAY[]::uuid[])) AS x;
      v_is_correct := v_correct_ids IS NOT NULL AND v_selected_ids IS NOT NULL AND v_correct_ids = v_selected_ids;

    WHEN 'ordering' THEN
      SELECT array_agg(id ORDER BY display_order) INTO v_correct_ids
        FROM public.unified_question_options
       WHERE question_id = p_question_id;
      v_is_correct := v_correct_ids IS NOT NULL
        AND p_selected_options IS NOT NULL
        AND p_selected_options = v_correct_ids;

    WHEN 'matching' THEN
      BEGIN
        v_matching := NULLIF(p_selected_answer, '')::jsonb;
      EXCEPTION WHEN others THEN
        v_matching := NULL;
      END;
      v_matching := COALESCE(v_matching, '{}'::jsonb);

      SELECT count(*) INTO v_relevant_count
        FROM public.unified_question_options
       WHERE question_id = p_question_id AND match_value IS NOT NULL;

      v_match_ok := v_relevant_count > 0
        AND (SELECT count(*) FROM jsonb_object_keys(v_matching)) = v_relevant_count;

      IF v_match_ok THEN
        FOR v_opt IN
          SELECT id, match_value FROM public.unified_question_options
           WHERE question_id = p_question_id AND match_value IS NOT NULL
        LOOP
          IF trim(COALESCE(v_matching ->> v_opt.id::text, chr(1))) IS DISTINCT FROM trim(v_opt.match_value) THEN
            v_match_ok := false;
          END IF;
        END LOOP;
      END IF;

      v_is_correct := v_match_ok;

    ELSE
      v_is_correct := false;
  END CASE;

  RETURN COALESCE(v_is_correct, false);
END;
$function$
;

CREATE OR REPLACE FUNCTION public._is_standing_assignment_rule(p_target_type text, p_target_user_ids uuid[])
 RETURNS boolean
 LANGUAGE sql
 IMMUTABLE
AS $function$
  SELECT COALESCE(p_target_type, '') NOT IN ('user', 'individual')
     AND (p_target_user_ids IS NULL OR cardinality(p_target_user_ids) = 0);
$function$
;

CREATE OR REPLACE FUNCTION public._issue_recertification_assignment(p_org_id uuid, p_user_id uuid, p_module_id uuid, p_module_title text, p_progress_id uuid, p_due_date timestamp with time zone, p_actor uuid, p_message text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_rule_id uuid;
BEGIN
  INSERT INTO public.training_assignment_rules (
    organization_id, target_type, target_id, content_type, content_id, training_module_id,
    due_date, priority, is_active, instructions, created_by, assigned_by, created_at
  ) VALUES (
    p_org_id, 'user', p_user_id::text, 'module', p_module_id, p_module_id,
    p_due_date, 'high', true, p_message, p_actor, p_actor, now()
  ) RETURNING id INTO v_rule_id;

  IF p_progress_id IS NOT NULL THEN
    UPDATE public.training_progress SET assignment_id = v_rule_id, updated_at = now()
     WHERE id = p_progress_id;
  ELSE
    INSERT INTO public.training_progress (user_id, assignment_id, training_id, lp_content_type, status)
    VALUES (p_user_id, v_rule_id, p_module_id, 'module', 'not_started'::training_status)
    ON CONFLICT (user_id, training_id) DO UPDATE SET assignment_id = EXCLUDED.assignment_id, updated_at = now();
  END IF;

  INSERT INTO public.notifications (user_id, organization_id, type, title, message, link, entity_type, entity_id)
  VALUES (p_user_id, p_org_id, 'training_recertification', 'Recertification required', p_message,
          '/training/hub/' || p_module_id, 'training_module', p_module_id);

  RETURN v_rule_id;
END;
$function$
;

CREATE OR REPLACE FUNCTION public._job_org(p_created_by uuid, p_org uuid)
 RETURNS uuid
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT COALESCE(
    p_org,
    (SELECT organization_id FROM public.organization_memberships
     WHERE user_id = p_created_by AND is_active = true
     ORDER BY is_primary DESC LIMIT 1)
  );
$function$
;

CREATE OR REPLACE FUNCTION public._learner_matches_filters(p_user_id uuid, p_org_id uuid, p_department_id uuid, p_property_id uuid, p_my_team_only boolean)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT (p_department_id IS NULL OR EXISTS (
            SELECT 1 FROM public.organization_memberships m
             WHERE m.user_id = p_user_id AND m.organization_id = p_org_id AND m.is_active
               AND m.department_id = p_department_id))
     AND (p_property_id IS NULL OR EXISTS (
            SELECT 1 FROM public.organization_memberships m
             WHERE m.user_id = p_user_id AND m.organization_id = p_org_id AND m.is_active
               AND m.hotel_id = p_property_id))
     AND (NOT COALESCE(p_my_team_only, false) OR EXISTS (
            SELECT 1 FROM public.organization_memberships m
              JOIN public.departments d ON d.id = m.department_id
             WHERE m.user_id = p_user_id AND m.organization_id = p_org_id AND m.is_active
               AND d.manager_id = auth.uid()));
$function$
;

CREATE OR REPLACE FUNCTION public._legacy_platform_fallback(_user_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT (SELECT legacy_role_fallback_enabled FROM public.platform_config WHERE id)
     AND EXISTS (
       SELECT 1 FROM public.user_roles
       WHERE user_id = _user_id AND role IN ('super_admin','corporate_admin','administrator')
     );
$function$
;

CREATE OR REPLACE FUNCTION public._module_assignment_targets(p_org_ids uuid[])
 RETURNS TABLE(user_id uuid, training_id uuid, due_date timestamp with time zone, organization_id uuid, rule_created_at timestamp with time zone)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  WITH rules AS (
    SELECT r.target_type, r.target_id, r.target_user_ids, r.target_role,
           r.hotel_id, r.department_id, r.brand_id,
           COALESCE(r.training_module_id, r.content_id) AS content_id,
           r.due_date, r.organization_id, r.created_at
      FROM public.training_assignment_rules r
     WHERE r.is_active AND NOT COALESCE(r.is_deleted, false)
       AND r.content_type = 'module'
       AND r.organization_id = ANY (p_org_ids)
  )
  SELECT m.user_id, r.content_id, r.due_date, r.organization_id, r.created_at
    FROM rules r
    JOIN public.organization_memberships m ON m.organization_id = r.organization_id AND m.is_active
    LEFT JOIN public.hotels h ON h.id = m.hotel_id
   WHERE CASE
     WHEN r.target_user_ids IS NOT NULL AND cardinality(r.target_user_ids) > 0
       THEN m.user_id = ANY (r.target_user_ids)
     WHEN r.target_type IN ('user', 'individual')
       THEN m.user_id = public._safe_uuid(r.target_id)
     WHEN r.target_type IN ('everyone', 'organization')
       THEN (r.target_role IS NULL OR r.target_role = 'all' OR m.role::text = r.target_role)
     WHEN r.target_type = 'brand'
       THEN (m.brand_id = COALESCE(r.brand_id, public._safe_uuid(r.target_id)) OR h.brand_id = COALESCE(r.brand_id, public._safe_uuid(r.target_id)))
     WHEN r.target_type IN ('property', 'hotel')
       THEN m.hotel_id = COALESCE(r.hotel_id, public._safe_uuid(r.target_id))
     WHEN r.target_type = 'department'
       THEN m.department_id = COALESCE(r.department_id, public._safe_uuid(r.target_id))
     WHEN r.target_type = 'role'
       THEN m.role::text = r.target_id
     ELSE false
   END;
$function$
;

CREATE OR REPLACE FUNCTION public._normalize_free_text(p_value text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
  SELECT regexp_replace(regexp_replace(lower(trim(COALESCE(p_value, ''))), '[.,!?;:''"`]', '', 'g'), '\s+', ' ', 'g');
$function$
;

CREATE OR REPLACE FUNCTION public._p7_is_service_context()
 RETURNS boolean
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  SELECT current_user IN ('service_role', 'supabase_admin', 'postgres')
$function$
;

CREATE OR REPLACE FUNCTION public._plan_rank(_code text)
 RETURNS integer
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$ SELECT CASE _code WHEN 'starter' THEN 1 WHEN 'growth' THEN 2 WHEN 'enterprise' THEN 3 ELSE 0 END; $function$
;

CREATE OR REPLACE FUNCTION public._question_in_graded_quiz(p_question_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT EXISTS (
    SELECT 1 FROM public.unified_quiz_questions uqq
      JOIN public.learning_quizzes lq ON lq.id = uqq.quiz_id
     WHERE uqq.question_id = p_question_id
       AND NOT COALESCE(lq.is_deleted, false)
       AND lq.show_feedback_during IS FALSE);
$function$
;

CREATE OR REPLACE FUNCTION public._question_visible_to_learner(p_question_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT EXISTS (
    SELECT 1 FROM public.unified_questions q
     WHERE q.id = p_question_id
       AND q.status = 'published'
       AND (COALESCE(q.is_master_template, false) OR public.org_visible(q.organization_id)));
$function$
;

CREATE OR REPLACE FUNCTION public._reset_training_cycle(p_progress_id uuid, p_reason text, p_actor uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_tp public.training_progress%ROWTYPE;
  v_cert_id uuid;
  v_history_id uuid;
  v_block_ids uuid[];
  v_quiz_ids uuid[];
BEGIN
  SELECT * INTO v_tp FROM public.training_progress WHERE id = p_progress_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Training progress not found';
  END IF;

  SELECT c.id INTO v_cert_id
    FROM public.certificates c
   WHERE c.training_progress_id = v_tp.id AND c.certificate_type = 'training'
   ORDER BY c.created_at DESC
   LIMIT 1;

  INSERT INTO public.training_completion_history (
    organization_id, user_id, training_id, training_progress_id, certificate_id,
    cycle_started_at, completed_at, score_percentage, passed, reason, archived_by
  ) VALUES (
    v_tp.organization_id, v_tp.user_id, v_tp.training_id, v_tp.id, v_cert_id,
    v_tp.cycle_started_at, v_tp.completed_at, v_tp.score_percentage, v_tp.passed,
    p_reason, p_actor
  ) RETURNING id INTO v_history_id;

  -- A still-valid certificate is replaced by the new cycle's certificate.
  UPDATE public.certificates
     SET status = 'superseded', updated_at = now()
   WHERE training_progress_id = v_tp.id
     AND certificate_type = 'training'
     AND status = 'active';

  SELECT array_agg(b.id),
         array_agg(public._safe_uuid(b.content_data ->> 'quiz_id')) FILTER (WHERE b.type = 'quiz')
    INTO v_block_ids, v_quiz_ids
    FROM public.training_content_blocks_v b
   WHERE b.training_module_id = v_tp.training_id;

  DELETE FROM public.training_block_progress
   WHERE user_id = v_tp.user_id
     AND (training_module_id = v_tp.training_id OR block_id = ANY (COALESCE(v_block_ids, '{}')));

  UPDATE public.unified_quiz_sessions
     SET archived_at = now()
   WHERE user_id = v_tp.user_id
     AND quiz_entity_id = ANY (COALESCE(v_quiz_ids, '{}'))
     AND archived_at IS NULL;

  PERFORM set_config('app.trusted_progress_write', 'on', true);

  UPDATE public.training_progress
     SET status = 'not_started',
         progress_percentage = 0,
         score_percentage = NULL,
         quiz_score = NULL,
         passed = NULL,
         completed_at = NULL,
         last_block_id = NULL,
         last_block_index = NULL,
         cycle_started_at = now(),
         metadata = COALESCE(metadata, '{}'::jsonb) - 'completed_blocks' - 'active_block_id',
         updated_at = now()
   WHERE id = v_tp.id;

  -- The module's quiz-level progress rows restart too.
  UPDATE public.training_progress
     SET status = 'not_started',
         progress_percentage = 0,
         score_percentage = NULL,
         quiz_score = NULL,
         passed = NULL,
         completed_at = NULL,
         cycle_started_at = now(),
         updated_at = now()
   WHERE user_id = v_tp.user_id
     AND lp_content_type = 'quiz'
     AND training_id = ANY (COALESCE(v_quiz_ids, '{}'));

  PERFORM set_config('app.trusted_progress_write', 'off', true);

  RETURN v_history_id;
END;
$function$
;

CREATE OR REPLACE FUNCTION public._safe_uuid(p_value text)
 RETURNS uuid
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
BEGIN
  RETURN p_value::uuid;
EXCEPTION WHEN others THEN
  RETURN NULL;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.announce_eom_from_selection(p_selection_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE
    v_selection eom_auto_selections%ROWTYPE;
    v_eom_id UUID;
BEGIN
    SELECT * INTO v_selection
    FROM eom_auto_selections
    WHERE id = p_selection_id;
    
    IF NOT FOUND THEN
        RAISE EXCEPTION 'Selection not found';
    END IF;
    
    -- Insert into employee_of_the_month
    INSERT INTO employee_of_the_month (
        property_id, user_id, month, year,
        reason_en, reason_ar, created_by
    ) VALUES (
        v_selection.property_id,
        v_selection.user_id,
        v_selection.month,
        v_selection.year,
        v_selection.selection_reason_en,
        v_selection.selection_reason_ar,
        v_selection.reviewed_by -- Or system user
    )
    ON CONFLICT (property_id, month, year)
    DO UPDATE SET
        user_id = EXCLUDED.user_id,
        reason_en = EXCLUDED.reason_en,
        reason_ar = EXCLUDED.reason_ar,
        updated_at = now()
    RETURNING id INTO v_eom_id;
    
    -- Update selection record
    UPDATE eom_auto_selections
    SET status = 'announced',
        announced_eom_id = v_eom_id,
        announced_at = now(),
        updated_at = now()
    WHERE id = p_selection_id;
    
    RETURN v_eom_id;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.approve_pending_user(p_user_id uuid, p_approve boolean DEFAULT true)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NOT has_any_role((SELECT auth.uid()),
       ARRAY['super_admin','corporate_admin','regional_admin','regional_hr','property_hr']::app_role[]) THEN
    RAISE EXCEPTION 'Not authorized to review user approvals';
  END IF;

  UPDATE pending_user_approvals
     SET status = CASE WHEN p_approve THEN 'approved' ELSE 'rejected' END,
         reviewed_by = (SELECT auth.uid()),
         reviewed_at = now()
   WHERE user_id = p_user_id;

  IF p_approve THEN
    UPDATE profiles SET account_status = 'active', is_active = true WHERE id = p_user_id;
  ELSE
    UPDATE profiles SET is_active = false WHERE id = p_user_id;
  END IF;

  RETURN json_build_object('success', true, 'user_id', p_user_id, 'approved', p_approve);
END;
$function$
;

CREATE OR REPLACE FUNCTION public.approve_training_module(p_module_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_org uuid;
    v_title text;
    v_author uuid;
    v_block record;
    v_quiz_id uuid;
    v_question_count integer;
BEGIN
    SELECT organization_id INTO v_org FROM public.training_modules WHERE id = p_module_id;
    IF v_org IS NULL OR NOT public.can_review_training_module(v_org) THEN
        RAISE EXCEPTION 'Not authorized to approve training modules';
    END IF;

    FOR v_block IN
        SELECT id, content_data, is_mandatory
          FROM public.training_content_blocks_v
         WHERE training_module_id = p_module_id AND is_deleted = false AND type = 'quiz'
    LOOP
        IF v_block.is_mandatory IS FALSE THEN
            CONTINUE;
        END IF;

        v_quiz_id := public._safe_uuid(v_block.content_data ->> 'quiz_id');
        IF v_quiz_id IS NULL THEN
            RAISE EXCEPTION 'Cannot publish: a required quiz block is not linked to a quiz';
        END IF;

        SELECT count(*) INTO v_question_count
          FROM public.unified_quiz_questions uq
          JOIN public.unified_questions q ON q.id = uq.question_id
         WHERE uq.quiz_id = v_quiz_id AND q.status = 'published';

        IF v_question_count = 0 THEN
            RAISE EXCEPTION 'Cannot publish: a required quiz has no published questions';
        END IF;
    END LOOP;

    UPDATE public.training_modules
       SET status = 'published', updated_at = now(), updated_by = auth.uid()
     WHERE id = p_module_id AND status = 'pending_review'
    RETURNING title, created_by INTO v_title, v_author;

    IF v_title IS NULL THEN
        RAISE EXCEPTION 'Module not found or not pending review';
    END IF;

    PERFORM public.snapshot_training_module_version(p_module_id);

    IF v_author IS NOT NULL THEN
        INSERT INTO public.notifications (user_id, organization_id, type, title, message, link, entity_type, entity_id)
        VALUES (
            v_author, v_org,
            'training_review_approved',
            'Training module approved',
            '"' || v_title || '" was approved and is now published.',
            '/training/hub/' || p_module_id,
            'training_module',
            p_module_id
        );
    END IF;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.archive_expired_documents()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_count INTEGER;
BEGIN
    UPDATE documents 
    SET is_archived = TRUE, updated_at = NOW()
    WHERE expires_at IS NOT NULL
    AND expires_at < NOW()
    AND is_archived = FALSE;
    
    GET DIAGNOSTICS v_count = ROW_COUNT;
    RETURN v_count;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.assign_platform_role(p_user_id uuid, p_role text, p_scope_type text DEFAULT 'global'::text, p_scope_org_ids uuid[] DEFAULT '{}'::uuid[])
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_id uuid;
BEGIN
  IF NOT (public.platform_operator_has_role('platform_admin') OR public.platform_operator_has_role('system_owner')) THEN
    RAISE EXCEPTION 'Only platform admins may assign platform roles' USING ERRCODE = '42501';
  END IF;
  IF p_role = 'system_owner' AND NOT public.platform_operator_has_role('system_owner') THEN
    RAISE EXCEPTION 'Only a system owner may grant system_owner' USING ERRCODE = '42501';
  END IF;
  INSERT INTO public.platform_users (user_id, created_by) VALUES (p_user_id, auth.uid())
  ON CONFLICT (user_id) DO UPDATE SET is_active = true, deactivated_at = NULL;
  UPDATE public.platform_role_assignments SET revoked_at = now(), revoked_by = auth.uid()
   WHERE platform_user_id = p_user_id AND platform_role = p_role::public.platform_role AND revoked_at IS NULL;
  INSERT INTO public.platform_role_assignments (platform_user_id, platform_role, scope_type, scope_org_ids, granted_by)
  VALUES (p_user_id, p_role::public.platform_role, p_scope_type, COALESCE(p_scope_org_ids,'{}'), auth.uid())
  RETURNING id INTO v_id;
  INSERT INTO public.platform_audit_logs (actor_id, action, resource_type, resource_id, metadata)
  VALUES (auth.uid(), 'assign_platform_role', 'platform_role_assignment', v_id::text,
          jsonb_build_object('target_user', p_user_id, 'role', p_role, 'scope_type', p_scope_type));
  RETURN v_id;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.auto_reactivate_suspended_accounts()
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  UPDATE public.profiles
  SET account_status = 'active',
      is_active = true,
      suspended_at = NULL,
      suspended_by = NULL,
      suspend_reason = NULL,
      suspended_until = NULL,
      updated_at = now()
  WHERE account_status = 'suspended'
    AND suspended_until IS NOT NULL
    AND suspended_until <= now();
END;
$function$
;

CREATE OR REPLACE FUNCTION public.award_module_skills(p_user_id uuid, p_module_id uuid)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_org uuid;
    v_rows_affected integer := 0;
BEGIN
    IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Authentication required'; END IF;

    SELECT organization_id INTO v_org FROM public.training_modules WHERE id = p_module_id;
    IF v_org IS NULL THEN RETURN 0; END IF;

    IF p_user_id <> auth.uid() AND NOT (v_org = ANY (public.learning_manager_org_ids())) THEN
        RAISE EXCEPTION 'Not authorized to award skills for this user';
    END IF;

    IF NOT EXISTS (SELECT 1 FROM public.training_progress tp
        WHERE tp.user_id = p_user_id AND tp.training_id = p_module_id AND tp.status = 'completed'
          AND COALESCE(tp.is_deleted, false) = false) THEN
        RETURN 0;
    END IF;

    INSERT INTO public.user_skills (user_id, organization_id, skill_id, proficiency_level, verified)
    SELECT p_user_id, v_org, ms.skill_id, LEAST(GREATEST(COALESCE(ms.points_awarded, 1), 1), 5), false
      FROM public.module_skills ms WHERE ms.module_id = p_module_id
    ON CONFLICT (user_id, skill_id) DO UPDATE
      SET proficiency_level = GREATEST(public.user_skills.proficiency_level, EXCLUDED.proficiency_level),
          verified = public.user_skills.verified
      WHERE public.user_skills.proficiency_level < EXCLUDED.proficiency_level;
    GET DIAGNOSTICS v_rows_affected = ROW_COUNT;
    RETURN v_rows_affected;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.base32_decode(input text)
 RETURNS bytea
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  alphabet text := 'ABCDEFGHIJKLMNOPQRSTUVWXYZ234567';
  clean text;
  bits bigint := 0;
  bit_count integer := 0;
  result bytea := ''::bytea;
  c char;
  val integer;
  byte_val integer;
  i integer;
BEGIN
  clean := upper(regexp_replace(coalesce(input, ''), '[^A-Za-z2-7]', '', 'g'));
  FOR i IN 1..length(clean) LOOP
    c := substr(clean, i, 1);
    val := position(c in alphabet) - 1;
    IF val < 0 THEN CONTINUE; END IF;
    bits := (bits << 5) | val;
    bit_count := bit_count + 5;
    IF bit_count >= 8 THEN
      byte_val := (bits >> (bit_count - 8)) & 255;
      result := result || set_byte('\x00'::bytea, 0, byte_val);
      bit_count := bit_count - 8;
    END IF;
  END LOOP;
  RETURN result;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.calculate_next_cron_run(cron_expr text, from_time timestamp with time zone DEFAULT now())
 RETURNS timestamp with time zone
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE
    next_run TIMESTAMPTZ;
BEGIN
    -- Simple implementation for common patterns
    -- For production, you'd want a proper cron parser
    CASE cron_expr
        WHEN '0 0 * * *' THEN -- Daily at midnight
            next_run := DATE_TRUNC('day', from_time) + INTERVAL '1 day';
        WHEN '0 9 * * *' THEN -- Daily at 9 AM
            next_run := DATE_TRUNC('day', from_time) + INTERVAL '9 hours';
            IF next_run <= from_time THEN
                next_run := next_run + INTERVAL '1 day';
            END IF;
        WHEN '0 * * * *' THEN -- Every hour
            next_run := DATE_TRUNC('hour', from_time) + INTERVAL '1 hour';
        WHEN '*/15 * * * *' THEN -- Every 15 minutes
            next_run := DATE_TRUNC('hour', from_time) + 
                       (FLOOR(EXTRACT(MINUTE FROM from_time) / 15) + 1) * INTERVAL '15 minutes';
        WHEN '0 0 * * 1' THEN -- Weekly on Monday
            next_run := DATE_TRUNC('week', from_time) + INTERVAL '1 week';
        ELSE
            -- Default to 1 hour from now
            next_run := from_time + INTERVAL '1 hour';
    END CASE;
    
    RETURN next_run;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.calculate_next_task_run(recurrence text, last_run timestamp with time zone)
 RETURNS timestamp with time zone
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
  SELECT CASE lower(coalesce(recurrence,'daily'))
    WHEN 'daily'      THEN last_run + interval '1 day'
    WHEN 'weekly'     THEN last_run + interval '1 week'
    WHEN 'biweekly'   THEN last_run + interval '2 weeks'
    WHEN 'monthly'    THEN last_run + interval '1 month'
    WHEN 'quarterly'  THEN last_run + interval '3 months'
    WHEN 'yearly'     THEN last_run + interval '1 year'
    WHEN 'annually'   THEN last_run + interval '1 year'
    ELSE last_run + interval '1 day'
  END;
$function$
;

CREATE OR REPLACE FUNCTION public.can_author_question(p_org_id uuid, p_created_by uuid, p_is_master boolean)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT public.is_platform_super_admin()
    OR p_created_by = auth.uid()
    OR (p_org_id IS NOT NULL AND public.org_visible(p_org_id) AND public.is_tenant_content_editor(p_org_id))
    OR (COALESCE(p_is_master, false) AND EXISTS (
          SELECT 1 FROM public.organization_memberships m
           WHERE m.user_id = auth.uid()
             AND m.is_active
             AND m.role IN ('organization_owner', 'organization_admin', 'brand_admin', 'hotel_admin',
                            'department_manager', 'training_manager', 'knowledge_manager', 'author', 'instructor')
             AND public.org_is_operational(m.organization_id)));
$function$
;

CREATE OR REPLACE FUNCTION public.can_manage_learning_assignment(p_org_id uuid, p_hotel_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT public.is_platform_operator(auth.uid())
    OR (p_org_id = ANY (public.current_user_organization_ids())
        AND public.org_is_operational(p_org_id)
        AND (public.is_tenant_admin(p_org_id)
             OR EXISTS (
               SELECT 1 FROM public.organization_memberships om
                WHERE om.user_id = auth.uid()
                  AND om.organization_id = p_org_id
                  AND om.is_active
                  AND om.role IN ('organization_owner', 'organization_admin', 'hotel_admin',
                                  'department_manager', 'training_manager')
                  AND (om.hotel_id IS NULL OR om.hotel_id = p_hotel_id))));
$function$
;

