 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT public.is_platform_super_admin()
    OR (public.org_visible(p_org_id)
        AND (public.is_tenant_admin(p_org_id)
             OR EXISTS (
