CREATE OR REPLACE FUNCTION public.can_send_tenant_email(p_user_id uuid, p_org_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
  -- If no specific org is requested or caller is a platform operator, allow
  IF p_org_id IS NULL OR public.is_platform_operator(p_user_id) THEN
    RETURN true;
  END IF;

  -- Otherwise, caller must be an active member of that tenant with operational status
  RETURN EXISTS (
    SELECT 1 FROM public.organization_memberships om
    WHERE om.user_id = p_user_id
      AND om.organization_id = p_org_id
      AND om.is_active = true
      AND public.org_is_operational(p_org_id)
  );
END;
$function$
;

CREATE OR REPLACE FUNCTION public.can_view_document(document_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE d record;
BEGIN
  IF (SELECT auth.uid()) IS NULL THEN RETURN false; END IF;

  SELECT id, organization_id, is_master_template, status, is_deleted, created_by, content_type
    INTO d FROM public.documents WHERE id = document_id LIMIT 1;
  IF d IS NULL OR d.is_deleted IS TRUE THEN RETURN false; END IF;

  -- platform operators (incl. inside an audited session) always
  IF public.is_platform_super_admin() THEN RETURN true; END IF;
  -- platform master reference content is readable to all tenants
  IF d.is_master_template IS TRUE THEN RETURN true; END IF;
  -- author of the file
  IF d.created_by = (SELECT auth.uid()) THEN RETURN true; END IF;

  -- STRICT tenant gate: the document's org must be visible to the caller
  IF NOT public.org_visible(d.organization_id) THEN RETURN false; END IF;

  -- content editors of the org see drafts too; everyone else needs PUBLISHED
  IF public.is_tenant_content_editor(d.organization_id) THEN RETURN true; END IF;
  RETURN d.status = 'PUBLISHED'::public.document_status;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.can_view_employee_public_profile(p_target_user_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_roles public.app_role[];
  v_property_ids uuid[];
  v_department_ids uuid[];
BEGIN
  IF v_uid IS NULL OR p_target_user_id IS NULL THEN
    RETURN false;
  END IF;

  IF v_uid = p_target_user_id THEN
    RETURN true;
  END IF;

  SELECT COALESCE(array_agg(ur.role), ARRAY[]::public.app_role[])
  INTO v_roles
  FROM public.user_roles ur
  WHERE ur.user_id = v_uid;

  IF (
    'corporate_admin'::public.app_role = ANY(v_roles) OR
    'regional_admin'::public.app_role = ANY(v_roles) OR
    'regional_hr'::public.app_role = ANY(v_roles)
  ) THEN
    RETURN true;
  END IF;

  SELECT COALESCE(array_agg(om.hotel_id), ARRAY[]::uuid[])
  INTO v_property_ids
  FROM public.organization_memberships om
  WHERE om.user_id = v_uid AND om.is_active = true AND om.hotel_id IS NOT NULL;

  SELECT COALESCE(array_agg(om.department_id), ARRAY[]::uuid[])
  INTO v_department_ids
  FROM public.organization_memberships om
  WHERE om.user_id = v_uid AND om.is_active = true AND om.department_id IS NOT NULL;

  IF 'department_head'::public.app_role = ANY(v_roles) THEN
    RETURN EXISTS (
      SELECT 1
      FROM public.organization_memberships om
      WHERE om.user_id = p_target_user_id AND om.is_active = true
        AND om.department_id = ANY(v_department_ids)
    );
  END IF;

  RETURN EXISTS (
    SELECT 1
    FROM public.organization_memberships om
    WHERE om.user_id = p_target_user_id AND om.is_active = true
      AND om.hotel_id = ANY(v_property_ids)
  );
END;
$function$
;

