CREATE OR REPLACE FUNCTION public.cleanup_orphaned_media_files()
 RETURNS TABLE(deleted_count integer, errors text[])
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_deleted INTEGER := 0;
  v_errors TEXT[] := ARRAY[]::TEXT[];
  v_record RECORD;
BEGIN
  -- Only allow admins to run this
  IF NOT (
    public.has_role_optimized('corporate_admin'::public.app_role)
    OR public.has_role_optimized('regional_admin'::public.app_role)
  ) THEN
    RAISE EXCEPTION 'Only administrators can run cleanup';
  END IF;

  -- Find storage objects without corresponding media_assets records
  FOR v_record IN 
    SELECT so.name, so.bucket_id
    FROM storage.objects so
    WHERE so.bucket_id = 'media'
    AND NOT EXISTS (
      SELECT 1 FROM media_assets ma 
      WHERE ma.storage_path = so.name
    )
    AND so.created_at < now() - interval '24 hours' -- Safety buffer
  LOOP
    BEGIN
      DELETE FROM storage.objects 
      WHERE name = v_record.name 
      AND bucket_id = v_record.bucket_id;
      
      v_deleted := v_deleted + 1;
    EXCEPTION WHEN OTHERS THEN
      v_errors := array_append(v_errors, 
        format('Failed to delete %s: %s', v_record.name, SQLERRM)
      );
    END;
  END LOOP;

  RETURN QUERY SELECT v_deleted, v_errors;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.cleanup_transient_records()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_ev int; v_wh int; v_pe_days int; v_wh_days int;
BEGIN
  SELECT retention_days INTO v_pe_days FROM public.data_retention_policies WHERE data_class = 'platform_events' AND is_active;
  SELECT retention_days INTO v_wh_days FROM public.data_retention_policies WHERE data_class = 'webhook_deliveries' AND is_active;
  DELETE FROM public.platform_events WHERE created_at < now() - (COALESCE(v_pe_days,90) || ' days')::interval;
  GET DIAGNOSTICS v_ev = ROW_COUNT;
  DELETE FROM public.webhook_deliveries
   WHERE status IN ('delivered','abandoned') AND created_at < now() - (COALESCE(v_wh_days,30) || ' days')::interval;
  GET DIAGNOSTICS v_wh = ROW_COUNT;
  RETURN jsonb_build_object('platform_events_deleted', v_ev, 'webhook_deliveries_deleted', v_wh);
END;
$function$
;

CREATE OR REPLACE FUNCTION public.clear_failed_login_attempts(p_email text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_profile_id uuid;
  v_caller_email text;
BEGIN
  SELECT email INTO v_caller_email FROM public.profiles WHERE id = auth.uid();

  IF v_caller_email IS NULL OR lower(v_caller_email) != lower(p_email) THEN
    RETURN; -- silently no-op for mismatched/anon callers, matches prior best-effort error handling
  END IF;

  DELETE FROM public.failed_login_attempts
  WHERE email = lower(p_email);

  SELECT id INTO v_profile_id
  FROM public.profiles
  WHERE email = lower(p_email);

  IF FOUND THEN
    UPDATE public.profiles
    SET failed_login_attempts = 0,
        locked_until = NULL,
        account_status = CASE
          WHEN account_status = 'locked' THEN 'active'
          ELSE account_status
        END,
        last_login_at = now()
    WHERE id = v_profile_id;
  END IF;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.clear_org_feature_override(p_org_id uuid, p_key text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NOT (public.is_platform_operator() AND public.platform_operator_can('tenant.manage')) THEN
    RAISE EXCEPTION 'tenant.manage required' USING ERRCODE = '42501';
  END IF;
  DELETE FROM public.organization_feature_overrides WHERE organization_id = p_org_id AND key = p_key;
  INSERT INTO public.platform_audit_logs (actor_id, target_organization_id, action, resource_type, resource_id, metadata)
  VALUES (auth.uid(), p_org_id, 'clear_org_feature_override', 'feature_flag', p_key, '{}'::jsonb);
END;
$function$
;

CREATE OR REPLACE FUNCTION public.complete_password_reset()
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth'
AS $function$
DECLARE
    current_uid uuid;
BEGIN
    current_uid := auth.uid();

    IF current_uid IS NULL THEN
        RAISE EXCEPTION 'Not authenticated';
    END IF;

    -- Update profile
    UPDATE public.profiles
    SET 
        is_temp_password = false,
        password_initialized = true,
        force_password_reset = false,
        password_last_changed_at = now(),
        updated_at = now()
    WHERE id = current_uid;

    -- Prune history to keep only last 10 records
    DELETE FROM public.password_history
    WHERE id IN (
        SELECT id
        FROM public.password_history
        WHERE user_id = current_uid
        ORDER BY created_at DESC
        OFFSET 10
    );
END;
$function$
;

CREATE OR REPLACE FUNCTION public.complete_training_module(p_module_id uuid, p_assignment_id uuid DEFAULT NULL::uuid, p_completed_block_ids uuid[] DEFAULT ARRAY[]::uuid[], p_last_block_id uuid DEFAULT NULL::uuid, p_last_block_index integer DEFAULT 0, p_time_spent_seconds integer DEFAULT 0)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_user_id uuid := auth.uid();
  v_module public.training_modules%ROWTYPE;
  v_block record;
  v_quiz_id uuid;
  v_quiz_title text;
  v_require_pass boolean;
  v_require_approval boolean;
  v_session record;
  v_quiz_progress public.training_progress%ROWTYPE;
  v_assignment_sub record;
  v_found boolean;
  v_block_score numeric;
  v_score_sum numeric := 0;
  v_score_n integer := 0;
  v_gate_sum numeric := 0;
  v_gate_n integer := 0;
  v_final_score numeric;
  v_gate_score numeric;
  v_passing_score numeric;
  v_existing public.training_progress%ROWTYPE;
  v_cycle_start timestamptz;
  v_metadata jsonb;
BEGIN
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Authentication required';
  END IF;

  SELECT * INTO v_module FROM public.training_modules WHERE id = p_module_id AND is_deleted = false;
  IF NOT FOUND OR NOT (public.org_visible(v_module.organization_id) OR public.is_platform_super_admin()) THEN
    RAISE EXCEPTION 'Training module not found';
  END IF;

  SELECT * INTO v_existing FROM public.training_progress
   WHERE user_id = v_user_id AND training_id = p_module_id;
  v_cycle_start := COALESCE(v_existing.cycle_started_at, '-infinity'::timestamptz);

  FOR v_block IN
    SELECT id, type, title, content_data, is_mandatory
      FROM public.training_content_blocks_v
     WHERE training_module_id = p_module_id AND is_deleted = false
  LOOP
    v_block_score := NULL;

    -- 1. Quiz blocks
    IF v_block.type = 'quiz' THEN
      v_quiz_id := public._safe_uuid(v_block.content_data ->> 'quiz_id');
      IF v_quiz_id IS NULL THEN
        CONTINUE;
      END IF;

      SELECT title INTO v_quiz_title FROM public.learning_quizzes WHERE id = v_quiz_id;
      v_quiz_title := COALESCE(v_block.content_data ->> 'title', v_block.title, v_quiz_title, 'Knowledge Check');

      v_require_pass := COALESCE(v_block.content_data ->> 'completion_requirement', '') <> 'submitted'
        AND COALESCE((v_block.content_data ->> 'require_passing')::boolean, true);

      -- Best submitted attempt of the current cycle (archived sessions belong
      -- to earlier cycles and never count).
      SELECT * INTO v_session
        FROM public.unified_quiz_sessions
       WHERE user_id = v_user_id
         AND quiz_type = 'learning_quiz'
         AND quiz_entity_id = v_quiz_id
         AND completed_at IS NOT NULL
         AND archived_at IS NULL
       ORDER BY passed DESC NULLS LAST, score_percentage DESC NULLS LAST, completed_at DESC
       LIMIT 1;
      v_found := FOUND;

      IF v_found THEN
        v_block_score := v_session.score_percentage;
        IF v_require_pass AND v_session.passed IS NOT TRUE AND v_block.is_mandatory IS NOT FALSE THEN
          RAISE EXCEPTION 'Quiz "%" has not been passed yet', v_quiz_title;
        END IF;
      ELSE
        -- Legacy results recorded only as quiz-level progress (same cycle).
        SELECT * INTO v_quiz_progress
          FROM public.training_progress
         WHERE user_id = v_user_id
           AND training_id = v_quiz_id
           AND lp_content_type = 'quiz'
           AND status = 'completed'
           AND completed_at >= v_cycle_start;
        IF FOUND THEN
          v_found := true;
          v_block_score := v_quiz_progress.score_percentage;
          IF v_require_pass AND v_quiz_progress.passed IS NOT TRUE AND v_block.is_mandatory IS NOT FALSE THEN
            RAISE EXCEPTION 'Quiz "%" has not been passed yet', v_quiz_title;
          END IF;
        END IF;
      END IF;

      IF NOT v_found AND v_block.is_mandatory IS NOT FALSE THEN
        RAISE EXCEPTION 'Quiz "%" has not been submitted yet', v_quiz_title;
      END IF;

      IF v_block_score IS NOT NULL THEN
        v_score_sum := v_score_sum + v_block_score;
        v_score_n := v_score_n + 1;
        -- The module passing score applies to its mandatory graded quizzes.
        IF v_block.is_mandatory IS NOT FALSE AND v_require_pass THEN
          v_gate_sum := v_gate_sum + v_block_score;
          v_gate_n := v_gate_n + 1;
        END IF;
      END IF;

    -- 2. Assignment / practical blocks (approval is their gate)
    ELSIF v_block.type = 'assignment' OR v_block.type = 'practical'
          OR COALESCE((v_block.content_data ->> 'is_assignment')::boolean, false)
          OR COALESCE((v_block.content_data ->> 'requires_submission')::boolean, false) THEN

      v_require_approval := COALESCE((v_block.content_data ->> 'requires_instructor_approval')::boolean, true);

      SELECT * INTO v_assignment_sub
        FROM public.training_assignment_submissions
       WHERE user_id = v_user_id
         AND training_module_id = p_module_id
         AND block_id = v_block.id::text
         AND is_deleted = false
         AND created_at >= v_cycle_start
       ORDER BY attempt_number DESC, created_at DESC
       LIMIT 1;
      v_found := FOUND;

      IF v_block.is_mandatory IS NOT FALSE THEN
        IF NOT v_found OR v_assignment_sub.status = 'draft' THEN
          RAISE EXCEPTION 'Assignment "%" has not been submitted yet', COALESCE(v_block.title, 'Assignment');
        END IF;

        IF v_require_approval THEN
          IF v_assignment_sub.status IN ('submitted', 'under_review') THEN
            RAISE EXCEPTION 'Assignment "%" is awaiting instructor review', COALESCE(v_block.title, 'Assignment');
          ELSIF v_assignment_sub.status IN ('revision_required', 'rejected') THEN
            RAISE EXCEPTION 'Assignment "%" requires revisions before module completion', COALESCE(v_block.title, 'Assignment');
          ELSIF v_assignment_sub.status <> 'approved' THEN
            RAISE EXCEPTION 'Assignment "%" has not been approved yet', COALESCE(v_block.title, 'Assignment');
          END IF;
        END IF;
      END IF;

      IF v_found AND v_assignment_sub.score IS NOT NULL THEN
        v_score_sum := v_score_sum + v_assignment_sub.score;
        v_score_n := v_score_n + 1;
      END IF;

    -- 3. Standard content blocks
    ELSIF v_block.is_mandatory IS NOT FALSE THEN
      IF NOT EXISTS (
        SELECT 1 FROM public.training_block_progress tbp
         WHERE tbp.user_id = v_user_id
           AND tbp.block_id = v_block.id
           AND tbp.completed_at IS NOT NULL
           AND tbp.completed_at >= v_cycle_start
      ) THEN
        RAISE EXCEPTION 'Required content "%" has not been completed yet', COALESCE(v_block.content_data ->> 'title', v_block.title, 'required content');
      END IF;
    END IF;
  END LOOP;

  v_final_score := CASE WHEN v_score_n > 0 THEN round(v_score_sum / v_score_n) ELSE NULL END;
  v_gate_score := CASE WHEN v_gate_n > 0 THEN round(v_gate_sum / v_gate_n) ELSE NULL END;
  v_passing_score := COALESCE(v_module.passing_score_percentage, 80);

  IF v_gate_score IS NOT NULL AND v_gate_score < v_passing_score THEN
    RAISE EXCEPTION 'Module passing score not met (% of % required) - retake the quizzes to improve your score',
      v_gate_score || '%', v_passing_score || '%';
  END IF;

  v_metadata := COALESCE(v_existing.metadata, '{}'::jsonb) || jsonb_build_object(
    'completed_blocks', to_jsonb(COALESCE(p_completed_block_ids, ARRAY[]::uuid[])),
    'active_block_id', p_last_block_id
  );

  PERFORM set_config('app.trusted_progress_write', 'on', true);

  INSERT INTO public.training_progress (
    user_id, training_id, lp_content_type, assignment_id, status,
    progress_percentage, score_percentage, quiz_score, passed, completed_at,
    last_accessed_at, last_activity_at, last_block_id, last_block_index,
    time_spent_seconds, metadata, updated_at
  ) VALUES (
    v_user_id, p_module_id, 'module', p_assignment_id, 'completed',
    100, v_final_score, round(v_final_score)::integer, true, now(),
    now(), now(), p_last_block_id, p_last_block_index,
    p_time_spent_seconds, v_metadata, now()
  )
  ON CONFLICT (user_id, training_id) DO UPDATE SET
    lp_content_type = 'module',
    assignment_id = COALESCE(public.training_progress.assignment_id, EXCLUDED.assignment_id),
    status = 'completed',
    progress_percentage = 100,
    score_percentage = COALESCE(EXCLUDED.score_percentage, public.training_progress.score_percentage),
    quiz_score = COALESCE(EXCLUDED.quiz_score, public.training_progress.quiz_score),
    passed = true,
    completed_at = COALESCE(public.training_progress.completed_at, EXCLUDED.completed_at),
    last_accessed_at = EXCLUDED.last_accessed_at,
    last_activity_at = EXCLUDED.last_activity_at,
    last_block_id = EXCLUDED.last_block_id,
    last_block_index = EXCLUDED.last_block_index,
    time_spent_seconds = GREATEST(COALESCE(public.training_progress.time_spent_seconds, 0), COALESCE(EXCLUDED.time_spent_seconds, 0)),
    metadata = EXCLUDED.metadata,
    updated_at = EXCLUDED.updated_at
  RETURNING * INTO v_existing;

  PERFORM set_config('app.trusted_progress_write', 'off', true);

  RETURN jsonb_build_object(
    'training_progress_id', v_existing.id,
    'score_percentage', v_existing.score_percentage,
    'passed', v_existing.passed,
    'status', v_existing.status,
    'completed_at', v_existing.completed_at
  );
END;
$function$
;

CREATE OR REPLACE FUNCTION public.consume_ai_credit(p_org_id uuid, p_credits integer DEFAULT 1, p_tokens bigint DEFAULT 0, p_cost numeric DEFAULT 0)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF p_org_id IS NULL THEN RETURN; END IF;
  IF NOT (public._p7_is_service_context() OR public.is_platform_super_admin() OR public.is_tenant_admin(p_org_id)) THEN
    RAISE EXCEPTION 'not authorized for organization %', p_org_id USING ERRCODE = '42501';
  END IF;
  UPDATE public.organizations
     SET ai_credits_used_this_month = COALESCE(ai_credits_used_this_month,0) + GREATEST(p_credits,0),
         updated_at = now()
   WHERE id = p_org_id;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.content_editor_org_ids()
 RETURNS uuid[]
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT CASE
    WHEN auth.uid() IS NULL THEN '{}'::uuid[]
    WHEN public.is_platform_super_admin() THEN
      ARRAY(SELECT o.id FROM public.organizations o WHERE NOT COALESCE(o.is_deleted, false))
    ELSE ARRAY(
      SELECT o.id FROM public.organizations o
       WHERE o.id = ANY (public.current_user_organization_ids())
         AND public.is_tenant_content_editor(o.id))
  END;
$function$
;

CREATE OR REPLACE FUNCTION public.course_generation_jobs_default_org()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NEW.created_by IS NULL THEN NEW.created_by := auth.uid(); END IF;
  IF NEW.organization_id IS NULL THEN
    NEW.organization_id := (public.current_user_organization_ids())[1];
  END IF;
  RETURN NEW;
END; $function$
;

CREATE OR REPLACE FUNCTION public.create_hr_notification()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_new jsonb := to_jsonb(new);
begin
  if tg_table_name = 'performance_reviews' then
    insert into public.notifications (user_id, title, message, type, link)
    values (
      nullif(v_new->>'employee_id', '')::uuid,
      'New Performance Review',
      'Your performance review for ' || coalesce(v_new->>'review_period', 'this period') || ' is ready.',
      'system'::public.notification_type,
      '/hr/performance'
    );
  elsif tg_table_name = 'goals' and coalesce(v_new->>'status', '') = 'completed' then
    insert into public.notifications (user_id, title, message, type, link)
    values (
      nullif(v_new->>'employee_id', '')::uuid,
      'Goal Completed',
      'Congratulations on achieving your goal: ' || coalesce(v_new->>'title', 'Goal'),
      'system'::public.notification_type,
      '/hr/goals'
    );
  elsif tg_table_name = 'certificates' then
    insert into public.notifications (user_id, title, message, type, link)
    values (
      nullif(v_new->>'user_id', '')::uuid,
      'Certificate Issued',
      'A new certificate has been issued for: ' || coalesce(v_new->>'title', 'training'),
      'system'::public.notification_type,
      '/profile'
    );
  end if;
  return new;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.create_notification(p_user_id uuid, p_type text, p_title text, p_body text, p_metadata jsonb DEFAULT NULL::jsonb, p_action_url text DEFAULT NULL::text, p_related_entity_type text DEFAULT NULL::text, p_related_entity_id uuid DEFAULT NULL::uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_new_id uuid;
  v_action_url text;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  IF NOT (
    p_user_id = auth.uid()
    OR public._p7_is_service_context()
    OR public.is_platform_super_admin()
    OR EXISTS (
      SELECT 1 FROM public.organization_memberships m
      WHERE m.user_id = p_user_id
        AND m.organization_id = ANY (public.current_user_organization_ids())
    )
  ) THEN
    RAISE EXCEPTION 'not authorized to notify user %', p_user_id USING ERRCODE = '42501';
  END IF;

  v_action_url := CASE WHEN p_action_url IS NOT NULL AND p_action_url LIKE '/%' THEN p_action_url ELSE NULL END;

  INSERT INTO public.notifications (
    user_id, type, title, message, link, metadata, entity_type, entity_id
  )
  VALUES (
    p_user_id, p_type, p_title, p_body, v_action_url,
    COALESCE(p_metadata, '{}'::jsonb), p_related_entity_type, p_related_entity_id
  )
  RETURNING id INTO v_new_id;

  RETURN v_new_id;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.create_notification_batch(p_job_type text, p_user_ids uuid[], p_notification_type text, p_notification_data jsonb, p_created_by uuid DEFAULT NULL::uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_batch_id UUID;
  v_user_id UUID;
BEGIN
  IF coalesce(auth.role(), '') <> 'service_role' THEN
    RAISE EXCEPTION 'Unauthorized: notification batches may only be created by the service role';
  END IF;

  INSERT INTO notification_batches (job_type, total_count, metadata, created_by)
  VALUES (p_job_type, array_length(p_user_ids, 1), p_notification_data, p_created_by)
  RETURNING id INTO v_batch_id;

  FOREACH v_user_id IN ARRAY p_user_ids LOOP
    INSERT INTO notification_queue (batch_id, user_id, notification_type, notification_data)
    VALUES (v_batch_id, v_user_id, p_notification_type, p_notification_data);
  END LOOP;

  RETURN v_batch_id;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.create_sample_questions(sop_id uuid, created_by_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE
    q1_id UUID;
    q2_id UUID;
    q3_id UUID;
BEGIN
    -- Sample MCQ
    INSERT INTO knowledge_questions (
        question_text, question_type, difficulty_level,
        explanation, hint, linked_sop_id, status, created_by
    ) VALUES (
        'What is the first step when entering a guest room for cleaning?',
        'mcq', 'easy',
        'Always knock and announce before entering to respect guest privacy.',
        'Think about guest privacy...',
        sop_id, 'published', created_by_id
    ) RETURNING id INTO q1_id;
    
    INSERT INTO knowledge_question_options (question_id, option_text, is_correct, display_order, feedback) VALUES
        (q1_id, 'Start vacuuming immediately', false, 1, 'Incorrect. You must announce yourself first.'),
        (q1_id, 'Knock and announce "Housekeeping"', true, 2, 'Correct! Always announce before entering.'),
        (q1_id, 'Check the minibar', false, 3, 'Incorrect. Minibar check comes later in the process.'),
        (q1_id, 'Open all windows', false, 4, 'Incorrect. Entry protocol comes first.');
    
    -- Sample True/False
    INSERT INTO knowledge_questions (
        question_text, question_type, difficulty_level,
        correct_answer, explanation, linked_sop_id, status, created_by
    ) VALUES (
        'Guests can request late checkout directly at the front desk.',
        'true_false', 'easy',
        'true',
        'Yes, late checkout requests are handled at the front desk based on availability.',
        sop_id, 'published', created_by_id
    ) RETURNING id INTO q2_id;
    
    -- Sample Fill in Blank
    INSERT INTO knowledge_questions (
        question_text, question_type, difficulty_level,
        correct_answer, explanation, hint, linked_sop_id, status, created_by
    ) VALUES (
        'The standard checkout time is _____ AM.',
        'fill_blank', 'easy',
        '11',
        'Standard checkout is 11 AM unless late checkout is arranged.',
        'Think about late morning...',
        sop_id, 'published', created_by_id
    ) RETURNING id INTO q3_id;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.create_scoped_training_assignment(p_course_id uuid, p_scope_type text, p_organization_id uuid, p_brand_id uuid DEFAULT NULL::uuid, p_hotel_id uuid DEFAULT NULL::uuid, p_department_id uuid DEFAULT NULL::uuid, p_target_role text DEFAULT NULL::text, p_target_user_ids uuid[] DEFAULT NULL::uuid[], p_due_date timestamp with time zone DEFAULT NULL::timestamp with time zone, p_priority text DEFAULT 'normal'::text, p_instructions text DEFAULT NULL::text, p_requires_acknowledgement boolean DEFAULT false, p_notify_on_due boolean DEFAULT true, p_reminder_days_before integer[] DEFAULT '{7,3,1}'::integer[])
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_caller_id uuid := auth.uid();
  v_scopes jsonb; v_can_org boolean;
  v_auth_hotels uuid[]; v_auth_depts uuid[]; v_auth_brands uuid[];
  v_rule_id uuid; v_eligible_users uuid[] := '{}'; v_user_id uuid;
  v_course_title text;
  v_module_org uuid;
BEGIN
  IF v_caller_id IS NULL THEN RAISE EXCEPTION 'Authentication required to assign training.'; END IF;

  SELECT title, organization_id INTO v_course_title, v_module_org
    FROM public.training_modules WHERE id = p_course_id AND is_deleted IS NOT TRUE;
  IF v_course_title IS NULL THEN RAISE EXCEPTION 'Selected training module does not exist or has been deleted.'; END IF;
  IF v_module_org IS DISTINCT FROM p_organization_id THEN
    RAISE EXCEPTION 'Training module belongs to a different organization; deploy it to this organization first.';
  END IF;

  v_scopes := public.get_caller_assignment_scopes(p_organization_id);
  v_can_org := (v_scopes->>'can_assign_org')::boolean IS TRUE OR (v_scopes->>'is_platform_admin')::boolean IS TRUE;

  IF NOT v_can_org THEN
    IF v_scopes->'authorized_hotel_ids' IS NOT NULL AND jsonb_array_length(v_scopes->'authorized_hotel_ids') > 0 THEN
      SELECT ARRAY(SELECT jsonb_array_elements_text(v_scopes->'authorized_hotel_ids')::uuid) INTO v_auth_hotels; END IF;
    IF v_scopes->'authorized_dept_ids' IS NOT NULL AND jsonb_array_length(v_scopes->'authorized_dept_ids') > 0 THEN
      SELECT ARRAY(SELECT jsonb_array_elements_text(v_scopes->'authorized_dept_ids')::uuid) INTO v_auth_depts; END IF;
    IF v_scopes->'authorized_brand_ids' IS NOT NULL AND jsonb_array_length(v_scopes->'authorized_brand_ids') > 0 THEN
      SELECT ARRAY(SELECT jsonb_array_elements_text(v_scopes->'authorized_brand_ids')::uuid) INTO v_auth_brands; END IF;
    IF NOT ((v_scopes->>'can_assign_role')::boolean IS TRUE) THEN
      RAISE EXCEPTION 'Access denied: you cannot assign training in this organization.';
    ELSIF p_scope_type = 'organization' THEN RAISE EXCEPTION 'Access denied: You do not have organization-wide assignment authority.';
    ELSIF p_scope_type = 'brand' AND (v_auth_brands IS NULL OR NOT (p_brand_id = ANY(v_auth_brands))) THEN RAISE EXCEPTION 'Access denied: not authorized for this brand.';
    ELSIF p_scope_type = 'hotel' AND (v_auth_hotels IS NULL OR NOT (p_hotel_id = ANY(v_auth_hotels))) THEN RAISE EXCEPTION 'Access denied: not authorized for this hotel.';
    ELSIF p_scope_type = 'department' AND (v_auth_depts IS NULL OR NOT (p_department_id = ANY(v_auth_depts))) THEN RAISE EXCEPTION 'Access denied: not authorized for this department.';
    END IF;
  END IF;

  IF p_scope_type = 'individual' AND p_target_user_ids IS NOT NULL THEN
    SELECT ARRAY(SELECT DISTINCT om.user_id FROM public.organization_memberships om
      WHERE om.organization_id = p_organization_id AND om.is_active = true AND om.user_id = ANY(p_target_user_ids)
        AND (v_can_org OR v_auth_hotels IS NULL OR om.hotel_id = ANY(v_auth_hotels))
        AND (v_can_org OR v_auth_depts IS NULL OR om.department_id = ANY(v_auth_depts))) INTO v_eligible_users;
  ELSE
    SELECT ARRAY(SELECT DISTINCT om.user_id FROM public.organization_memberships om
      LEFT JOIN public.hotels h ON h.id = om.hotel_id
      WHERE om.organization_id = p_organization_id AND om.is_active = true
        AND (v_can_org OR v_auth_hotels IS NULL OR om.hotel_id = ANY(v_auth_hotels))
        AND (v_can_org OR v_auth_depts IS NULL OR om.department_id = ANY(v_auth_depts))
        AND (v_can_org OR v_auth_brands IS NULL OR om.brand_id = ANY(v_auth_brands) OR h.brand_id = ANY(v_auth_brands))
        AND (p_brand_id IS NULL OR om.brand_id = p_brand_id OR h.brand_id = p_brand_id)
        AND (p_hotel_id IS NULL OR om.hotel_id = p_hotel_id)
        AND (p_department_id IS NULL OR om.department_id = p_department_id)
        AND (p_target_role IS NULL OR p_target_role = 'all' OR om.role::text = p_target_role)) INTO v_eligible_users;
  END IF;

  IF array_length(v_eligible_users, 1) IS NULL OR array_length(v_eligible_users, 1) = 0 THEN
    RAISE EXCEPTION 'No eligible active learners found in the selected assignment scope.';
  END IF;

  INSERT INTO public.training_assignment_rules (
    training_module_id, content_id, content_type, organization_id, brand_id, hotel_id, department_id,
    target_role, target_type, target_id, scope_type, scope_id, target_user_ids, recipient_count,
    due_date, priority, instructions, requires_acknowledgement, notify_on_due, reminder_days_before,
    assigned_by, created_by, is_active, status
  ) VALUES (
    p_course_id, p_course_id, 'module', p_organization_id, p_brand_id, p_hotel_id, p_department_id,
    p_target_role, p_scope_type,
    COALESCE(p_hotel_id::text, p_department_id::text, p_brand_id::text, p_organization_id::text),
    p_scope_type, COALESCE(p_hotel_id, p_department_id, p_brand_id, p_organization_id),
    v_eligible_users, array_length(v_eligible_users, 1), p_due_date, p_priority, p_instructions,
    p_requires_acknowledgement, p_notify_on_due, p_reminder_days_before, v_caller_id, v_caller_id, true, 'active'
  ) RETURNING id INTO v_rule_id;

  FOREACH v_user_id IN ARRAY v_eligible_users LOOP
    INSERT INTO public.training_progress (user_id, training_id, assignment_id, organization_id, lp_content_type, status, created_at, updated_at)
    VALUES (v_user_id, p_course_id, v_rule_id, p_organization_id, 'module', 'not_started'::training_status, now(), now())
    ON CONFLICT (user_id, training_id) DO UPDATE SET assignment_id = EXCLUDED.assignment_id, organization_id = EXCLUDED.organization_id, updated_at = now();

    INSERT INTO public.notifications (user_id, organization_id, title, message, type, link, created_at)
    VALUES (v_user_id, p_organization_id, 'New Training Assigned: ' || v_course_title,
      COALESCE(p_instructions, 'You have been assigned to complete "' || v_course_title || '".'),
      'training_assigned', '/training/player/' || p_course_id, now());
  END LOOP;

  IF (v_scopes->>'is_platform_admin')::boolean IS TRUE THEN
    INSERT INTO public.platform_audit_logs (actor_id, action, resource_type, resource_id, target_organization_id, metadata)
    VALUES (v_caller_id, 'create_training_assignment', 'training_assignment_rules', v_rule_id, p_organization_id,
      jsonb_build_object('course_id', p_course_id, 'course_title', v_course_title, 'scope_type', p_scope_type,
                         'recipient_count', array_length(v_eligible_users, 1), 'due_date', p_due_date));
  END IF;

  RETURN jsonb_build_object('success', true, 'rule_id', v_rule_id, 'course_id', p_course_id,
                            'recipient_count', array_length(v_eligible_users, 1), 'scope_type', p_scope_type);
END;
$function$
;

CREATE OR REPLACE FUNCTION public.create_task_atomic(task_data jsonb, notification_payload jsonb DEFAULT NULL::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
  v_task tasks%rowtype;
  v_created_by uuid;
  v_assigned_to uuid;
  v_status text;
  v_priority text;
begin
  v_created_by := nullif(task_data->>'created_by_id', '')::uuid;
  v_assigned_to := nullif(task_data->>'assigned_to_id', '')::uuid;
  v_status := lower(coalesce(task_data->>'status', 'pending'));
  v_priority := lower(coalesce(task_data->>'priority', 'medium'));

  if auth.uid() is not null and v_created_by is distinct from auth.uid() then
    raise exception 'Unauthorized: Creator ID mismatch';
  end if;

  if v_status not in ('pending', 'in_progress', 'completed', 'cancelled', 'on_hold') then
    v_status := 'pending';
  end if;

  if v_priority not in ('low', 'medium', 'high', 'urgent') then
    v_priority := 'medium';
  end if;

  insert into public.tasks (
    title,
    description,
    status,
    priority,
    assigned_to_id,
    created_by_id,
    property_id,
    department_id,
    due_date
  )
  values (
    nullif(task_data->>'title', ''),
    coalesce(task_data->>'description', ''),
    v_status::public.entity_status,
    v_priority::public.task_priority,
    v_assigned_to,
    v_created_by,
    nullif(task_data->>'property_id', '')::uuid,
    nullif(task_data->>'department_id', '')::uuid,
    nullif(task_data->>'due_date', '')::timestamptz
  )
  returning * into v_task;

  if notification_payload is not null then
    insert into public.notifications (user_id, type, title, message, link, metadata)
    values (
      nullif(notification_payload->>'user_id', '')::uuid,
      public.safe_notification_type(notification_payload->>'type', 'task_assigned'::public.notification_type),
      coalesce(notification_payload->>'title', 'Task Assigned'),
      coalesce(notification_payload->>'message', 'A task was assigned to you.'),
      nullif(notification_payload->>'link', ''),
      coalesce(notification_payload->'metadata', notification_payload->'data', '{}'::jsonb)
    );
  end if;

  return to_jsonb(v_task);
end;
$function$
;

CREATE OR REPLACE FUNCTION public.create_workflow_notification_batch(p_job_type text, p_user_ids uuid[], p_notification_type text, p_notification_data jsonb DEFAULT '{}'::jsonb, p_business_domain text DEFAULT 'system'::text, p_template_key text DEFAULT NULL::text, p_channels text[] DEFAULT ARRAY['in_app'::text, 'email'::text], p_created_by uuid DEFAULT NULL::uuid, p_priority text DEFAULT 'normal'::text, p_scheduled_for timestamp with time zone DEFAULT NULL::timestamp with time zone)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_batch_id UUID;
  v_user_id UUID;
  v_domain TEXT;
  v_channels TEXT[];
BEGIN
  IF coalesce(auth.role(), '') <> 'service_role' THEN
    RAISE EXCEPTION 'Unauthorized: workflow notification batches may only be created by the service role';
  END IF;

  IF p_user_ids IS NULL OR array_length(p_user_ids, 1) IS NULL THEN
    RAISE EXCEPTION 'p_user_ids must contain at least one recipient';
  END IF;

  v_domain := lower(coalesce(p_business_domain, 'system'));
  IF v_domain NOT IN ('system', 'user_management', 'operations', 'hr', 'finance', 'sales', 'management') THEN
    v_domain := 'system';
  END IF;

  v_channels := coalesce(p_channels, ARRAY['in_app']::TEXT[]);

  INSERT INTO public.notification_batches (job_type, total_count, metadata, created_by)
  VALUES (p_job_type, array_length(p_user_ids, 1), coalesce(p_notification_data, '{}'::JSONB), p_created_by)
  RETURNING id INTO v_batch_id;

  FOREACH v_user_id IN ARRAY p_user_ids
  LOOP
    INSERT INTO public.notification_queue (
      batch_id, user_id, notification_type, notification_data, channels,
      template_key, business_domain, email_payload, send_email, priority, scheduled_for
    )
    VALUES (
      v_batch_id, v_user_id, p_notification_type, coalesce(p_notification_data, '{}'::JSONB), v_channels,
      p_template_key, v_domain, coalesce(p_notification_data, '{}'::JSONB), ('email' = ANY(v_channels)),
      CASE WHEN p_priority IN ('low', 'normal', 'high', 'critical') THEN p_priority ELSE 'normal' END,
      p_scheduled_for
    );
  END LOOP;

  RETURN v_batch_id;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.current_user_organization_ids()
 RETURNS uuid[]
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT COALESCE(
    ARRAY(
      SELECT organization_id 
      FROM public.organization_memberships 
      WHERE user_id = auth.uid() 
        AND is_active = true
    ),
    '{}'::uuid[]
  );
$function$
;

CREATE OR REPLACE FUNCTION public.deploy_master_content(p_master_id uuid, p_content_type text, p_org_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_new_id uuid := gen_random_uuid();
  v_quiz record;
  v_question record;
  v_new_quiz_id uuid;
  v_new_question_id uuid;
  v_quiz_map jsonb := '{}'::jsonb;
BEGIN
  IF NOT (public.is_platform_operator() AND public.platform_operator_can('tenant.manage')) THEN
    RAISE EXCEPTION 'Permission denied: caller must be a platform operator with tenant.manage capability'
      USING ERRCODE = '42501';
  END IF;

  IF NOT EXISTS (SELECT 1 FROM public.organizations WHERE id = p_org_id AND is_active = true) THEN
    RAISE EXCEPTION 'Target organization % does not exist or is inactive', p_org_id;
  END IF;

  IF p_content_type IN ('course', 'training_module') THEN
    IF NOT EXISTS (SELECT 1 FROM public.training_modules WHERE id = p_master_id AND is_master_template = true) THEN
      RAISE EXCEPTION 'Master training module % not found', p_master_id;
    END IF;

    INSERT INTO public.training_modules (
      id, title, description, category, difficulty_level, estimated_duration_minutes, validity_period_days,
      certificate_enabled, passing_score_percentage, allow_retake, max_attempts, auto_advance, show_feedback,
      randomize_questions, show_answers, time_limit_minutes, audience, content_language, template_id, status,
      organization_id, scope_type, is_master_template, master_source_id, blueprint, created_by, created_at, updated_at, is_deleted
    )
    SELECT
      v_new_id, title, description, category, difficulty_level, estimated_duration_minutes, validity_period_days,
      certificate_enabled, passing_score_percentage, allow_retake, max_attempts, auto_advance, show_feedback,
      randomize_questions, show_answers, time_limit_minutes, audience, content_language, template_id, status,
      p_org_id, 'organization', false, p_master_id, blueprint, auth.uid(), now(), now(), false
    FROM public.training_modules WHERE id = p_master_id;

    FOR v_quiz IN
      SELECT DISTINCT q.*
        FROM public.documents d
        JOIN public.learning_quizzes q ON q.id = public._safe_uuid(d.content_data ->> 'quiz_id')
       WHERE d.content_type = 'training_block' AND d.training_module_id = p_master_id
         AND d.block_type = 'quiz' AND NOT COALESCE(d.is_deleted, false)
    LOOP
      v_new_quiz_id := gen_random_uuid();
      INSERT INTO public.learning_quizzes
      SELECT (jsonb_populate_record(NULL::public.learning_quizzes,
               to_jsonb(v_quiz) || jsonb_build_object(
                 'id', v_new_quiz_id, 'organization_id', p_org_id, 'training_module_id', v_new_id,
                 'category_id', NULL, 'linked_sop_id', NULL, 'source_document_id', NULL,
                 'created_by', auth.uid(), 'owner_id', NULL, 'created_at', now(), 'updated_at', now()))).*;

      FOR v_question IN
        SELECT uqq.display_order, uqq.points_override, q.*
          FROM public.unified_quiz_questions uqq
          JOIN public.unified_questions q ON q.id = uqq.question_id
         WHERE uqq.quiz_id = v_quiz.id
      LOOP
        v_new_question_id := gen_random_uuid();
        INSERT INTO public.unified_questions
        SELECT (jsonb_populate_record(NULL::public.unified_questions,
                 to_jsonb(v_question) || jsonb_build_object(
                   'id', v_new_question_id, 'organization_id', p_org_id, 'is_master_template', false,
                   'master_source_id', v_question.id, 'training_module_id', v_new_id,
                   'question_bank_id', NULL, 'linked_sop_id', NULL, 'source_document_id', NULL,
                   'reviewed_by', NULL, 'created_by', auth.uid(), 'created_at', now(), 'updated_at', now()))).*;

        INSERT INTO public.unified_question_options
        SELECT (jsonb_populate_record(NULL::public.unified_question_options,
                 to_jsonb(o) || jsonb_build_object(
                   'id', gen_random_uuid(), 'question_id', v_new_question_id,
                   'organization_id', p_org_id, 'created_at', now()))).*
          FROM public.unified_question_options o
         WHERE o.question_id = v_question.id;

        INSERT INTO public.unified_quiz_questions (quiz_id, question_id, display_order, points_override, organization_id)
        VALUES (v_new_quiz_id, v_new_question_id, v_question.display_order, v_question.points_override, p_org_id);
      END LOOP;

      v_quiz_map := v_quiz_map || jsonb_build_object(v_quiz.id::text, v_new_quiz_id::text);
    END LOOP;

    INSERT INTO public.documents (
      id, training_module_id, content_type, block_type, block_order, title, content, content_ar, content_url,
      content_data, is_mandatory, duration_seconds, points, organization_id, scope_type, is_master_template,
      master_source_id, created_by, created_at, updated_at, is_deleted
    )
    SELECT
      gen_random_uuid(), v_new_id, 'training_block', block_type, block_order, title, content, content_ar, content_url,
      CASE WHEN block_type = 'quiz' AND v_quiz_map ? (content_data ->> 'quiz_id')
           THEN jsonb_set(content_data, '{quiz_id}', to_jsonb(v_quiz_map ->> (content_data ->> 'quiz_id')))
           ELSE content_data END,
      is_mandatory, duration_seconds, points, p_org_id, 'organization', false,
      id, auth.uid(), now(), now(), false
    FROM public.documents
    WHERE content_type = 'training_block' AND training_module_id = p_master_id AND COALESCE(is_deleted, false) = false;

  ELSIF p_content_type = 'document' THEN
    IF NOT EXISTS (SELECT 1 FROM public.documents WHERE id = p_master_id AND is_master_template = true) THEN
      RAISE EXCEPTION 'Master document % not found', p_master_id;
    END IF;

    INSERT INTO public.documents (
      id, title, description, file_url, visibility, role, status, requires_acknowledgment,
      created_by, current_version, created_at, updated_at, summary, summary_ar, is_deleted,
      file_size, category_id, content, content_type, checklist_items, faq_items, video_url,
      images, featured, estimated_read_time, title_ar, description_ar, content_ar,
      confidentiality_level, file_extension, watermark_text, file_type, sop_code,
      review_frequency_months, requires_quiz, passing_score, quiz_enabled, priority,
      compliance_level, lifecycle_status, organization_id, scope_type, is_master_template, master_source_id
    )
    SELECT
      v_new_id, title, description, file_url, visibility, role, status, requires_acknowledgment,
      auth.uid(), current_version, now(), now(), summary, summary_ar, false,
      file_size, category_id, content, content_type, checklist_items, faq_items, video_url,
      images, featured, estimated_read_time, title_ar, description_ar, content_ar,
      confidentiality_level, file_extension, watermark_text, file_type, sop_code,
      review_frequency_months, requires_quiz, passing_score, quiz_enabled, priority,
      compliance_level, lifecycle_status, p_org_id, 'organization', false, p_master_id
    FROM public.documents WHERE id = p_master_id;

  ELSIF p_content_type = 'question_bank' THEN
    IF NOT EXISTS (SELECT 1 FROM public.question_banks WHERE id = p_master_id AND is_master_template = true) THEN
      RAISE EXCEPTION 'Master question bank % not found', p_master_id;
    END IF;

    INSERT INTO public.question_banks (
      id, name, name_ar, description, tags, is_active, created_by, created_at, updated_at,
      organization_id, is_master_template, master_source_id
    )
    SELECT
      v_new_id, name, name_ar, description, tags, is_active, auth.uid(), now(), now(),
      p_org_id, false, p_master_id
    FROM public.question_banks WHERE id = p_master_id;

  ELSE
    RAISE EXCEPTION 'Unsupported content type %', p_content_type;
  END IF;

  INSERT INTO public.master_content_deployments (
    content_type, master_content_id, target_organization_id, target_content_id,
    deployed_version, current_master_version, has_update_available, deployed_by, deployed_at, last_synced_at
  ) VALUES (
    p_content_type, p_master_id, p_org_id, v_new_id,
    1, 1, false, auth.uid(), now(), now()
  )
  ON CONFLICT (content_type, master_content_id, target_organization_id)
  DO UPDATE SET
    target_content_id = EXCLUDED.target_content_id,
    deployed_version = EXCLUDED.deployed_version,
    current_master_version = EXCLUDED.current_master_version,
    has_update_available = false,
    deployed_by = EXCLUDED.deployed_by,
    deployed_at = now(),
    last_synced_at = now();

  INSERT INTO public.platform_audit_logs (
    actor_id, target_organization_id, action, resource_type, resource_id, metadata, created_at
  ) VALUES (
    auth.uid(), p_org_id, 'master_content.deployed', p_content_type, v_new_id::text,
    jsonb_build_object('master_content_id', p_master_id, 'target_content_id', v_new_id,
                       'content_type', p_content_type, 'cloned_quizzes', v_quiz_map),
    now()
  );

  RETURN v_new_id;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.disable_mfa(p_user_id uuid, p_password text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public, extensions'
AS $function$
DECLARE v_user_record auth.users%ROWTYPE;
BEGIN
    IF auth.uid() IS DISTINCT FROM p_user_id THEN RETURN false; END IF;
    SELECT * INTO v_user_record FROM auth.users WHERE id = p_user_id;
    IF NOT FOUND THEN RETURN false; END IF;
    IF v_user_record.encrypted_password IS NULL
       OR extensions.crypt(p_password, v_user_record.encrypted_password) IS DISTINCT FROM v_user_record.encrypted_password THEN
        RETURN false;
    END IF;
    DELETE FROM public.mfa_secrets WHERE user_id = p_user_id;
    INSERT INTO public.system_events (event_type, actor_id, entity_type, entity_id, metadata)
    VALUES ('security', p_user_id, 'mfa', p_user_id,
        jsonb_build_object('security_event_type', 'mfa.disabled', 'severity', 'warning'));
    RETURN true;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.dismiss_contextual_tip(p_tip_id text, p_org_id uuid DEFAULT NULL::uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_user_id UUID := auth.uid();
BEGIN
  IF v_user_id IS NULL THEN
    RETURN false;
  END IF;

  UPDATE public.wizard_user_progress
  SET
    dismissed_contextual_tips = CASE 
      WHEN NOT dismissed_contextual_tips ? p_tip_id 
      THEN dismissed_contextual_tips || to_jsonb(p_tip_id)
      ELSE dismissed_contextual_tips
    END,
    last_activity_at = now(),
    updated_at = now()
  WHERE user_id = v_user_id
    AND ((p_org_id IS NULL AND organization_id IS NULL) OR organization_id = p_org_id);

  RETURN true;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.duplicate_training_module(p_module_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_new_module_id uuid;
    v_source public.training_modules%ROWTYPE;
BEGIN
    IF NOT public._can_edit_training_module(p_module_id) THEN
        RAISE EXCEPTION 'Not authorized to duplicate this module';
    END IF;

    SELECT * INTO v_source FROM public.training_modules WHERE id = p_module_id;
    IF v_source.id IS NULL THEN
        RAISE EXCEPTION 'Module not found';
    END IF;

    INSERT INTO public.training_modules (
        organization_id, title, description, estimated_duration_minutes, property_id, department_id,
        validity_period_days, allow_retake, max_attempts, auto_advance, show_feedback,
        randomize_questions, show_answers, time_limit_minutes, audience, content_language,
        template_id, passing_score_percentage, status, category, difficulty_level,
        certificate_enabled, created_by
    )
    VALUES (
        v_source.organization_id, v_source.title || ' (Copy)', v_source.description, v_source.estimated_duration_minutes,
        v_source.property_id, v_source.department_id, v_source.validity_period_days,
        v_source.allow_retake, v_source.max_attempts, v_source.auto_advance, v_source.show_feedback,
        v_source.randomize_questions, v_source.show_answers, v_source.time_limit_minutes,
        v_source.audience, v_source.content_language, v_source.template_id,
        v_source.passing_score_percentage, 'draft', v_source.category, v_source.difficulty_level,
        v_source.certificate_enabled, auth.uid()
    )
    RETURNING id INTO v_new_module_id;

    INSERT INTO public.documents (
        organization_id, title, status, created_by, content, content_type, training_module_id,
        block_type, block_order, content_data, is_mandatory, duration_seconds, points,
        content_url, ai_generated, ai_source_content, visibility
    )
    SELECT
        v_source.organization_id, d.title, d.status, auth.uid(), d.content, 'training_block', v_new_module_id,
        d.block_type, d.block_order, d.content_data, d.is_mandatory, d.duration_seconds, d.points,
        d.content_url, d.ai_generated, d.ai_source_content, d.visibility
      FROM public.documents d
     WHERE d.training_module_id = p_module_id
       AND d.content_type = 'training_block'
       AND d.is_deleted = false;

    RETURN v_new_module_id;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.effective_entitlements(p_org_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_org public.organizations; v_plan public.subscription_plans;
BEGIN
  SELECT * INTO v_org FROM public.organizations WHERE id = p_org_id;
  IF NOT FOUND THEN RETURN '{}'::jsonb; END IF;
  SELECT sp.* INTO v_plan FROM public.subscriptions s JOIN public.subscription_plans sp ON sp.id = s.plan_id
  WHERE s.organization_id = p_org_id AND s.status = 'active'
  ORDER BY s.current_period_end DESC NULLS LAST LIMIT 1;
  RETURN jsonb_build_object(
    'plan', COALESCE(v_plan.name, 'None'), 'plan_code', v_plan.code,
    'max_hotels', COALESCE(v_org.max_hotels, v_plan.max_hotels, 10),
    'max_learners', COALESCE(v_org.max_learners, v_plan.max_users, 100),
    'max_storage_gb', COALESCE(v_org.max_storage_gb, v_plan.max_storage_gb, 50),
    'ai_credits_monthly', COALESCE(v_org.max_ai_credits_monthly, 0),
    'ai_credits_used', COALESCE(v_org.ai_credits_used_this_month, 0),
    'plan_features', COALESCE(v_plan.features, '{}'::jsonb),
    'usage', jsonb_build_object(
      'hotels', (SELECT count(*) FROM public.hotels WHERE organization_id = p_org_id AND is_deleted = false),
      'learners', (SELECT count(*) FROM public.organization_memberships WHERE organization_id = p_org_id AND is_active = true)
    )
  );
END;
$function$
;

CREATE OR REPLACE FUNCTION public.emit_platform_event(p_event_type text, p_organization_id uuid, p_resource_type text DEFAULT NULL::text, p_resource_id text DEFAULT NULL::text, p_payload jsonb DEFAULT '{}'::jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_id uuid;
BEGIN
  IF NOT (public._p7_is_service_context() OR public.is_platform_super_admin()
          OR (p_organization_id IS NOT NULL AND public.org_visible(p_organization_id))) THEN
    RAISE EXCEPTION 'not authorized for organization %', p_organization_id USING ERRCODE = '42501';
  END IF;
  INSERT INTO public.platform_events (event_type, organization_id, actor_id, resource_type, resource_id, payload)
  VALUES (p_event_type, p_organization_id, auth.uid(), p_resource_type, p_resource_id, COALESCE(p_payload,'{}'::jsonb))
  RETURNING id INTO v_id;
  RETURN v_id;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.enable_mfa(p_user_id uuid, p_verification_code text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_secret public.mfa_secrets%ROWTYPE;
BEGIN
    IF auth.uid() IS DISTINCT FROM p_user_id THEN RETURN false; END IF;
    SELECT * INTO v_secret FROM public.mfa_secrets WHERE user_id = p_user_id;
    IF NOT FOUND THEN RETURN false; END IF;
    IF p_verification_code IS NULL OR length(p_verification_code) != 6 THEN RETURN false; END IF;
    UPDATE public.mfa_secrets SET enabled = true, verified_at = now(), updated_at = now() WHERE user_id = p_user_id;
    INSERT INTO public.system_events (event_type, actor_id, entity_type, entity_id, metadata)
    VALUES ('security', p_user_id, 'mfa', p_user_id,
        jsonb_build_object('security_event_type', 'mfa.enabled', 'severity', 'info'));
    RETURN true;
END; $function$
;

CREATE OR REPLACE FUNCTION public.end_platform_session(p_session_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_row public.platform_access_sessions;
BEGIN
  SELECT * INTO v_row FROM public.platform_access_sessions WHERE id = p_session_id;
  IF NOT FOUND THEN RETURN; END IF;
  IF v_row.admin_user_id <> auth.uid() AND NOT public.is_platform_operator() THEN
    RAISE EXCEPTION 'Not your session' USING ERRCODE = '42501';
  END IF;
  UPDATE public.platform_access_sessions SET is_active = false, ended_at = now() WHERE id = p_session_id;
  INSERT INTO public.platform_audit_logs (actor_id, target_organization_id, session_id, action, resource_type, resource_id, metadata)
  VALUES (auth.uid(), v_row.target_organization_id, p_session_id, 'exit_tenant', 'platform_access_session', p_session_id::text,
          jsonb_build_object('duration_seconds', EXTRACT(EPOCH FROM (now() - v_row.started_at))::int));
END;
$function$
;

CREATE OR REPLACE FUNCTION public.enforce_ai_credit()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_org uuid;
BEGIN
  IF public.is_platform_operator() THEN RETURN NEW; END IF;
  v_org := public._job_org(NEW.created_by, NEW.organization_id);
  NEW.organization_id := v_org;
  IF v_org IS NOT NULL AND NOT public.check_ai_credit(v_org) THEN
    RAISE EXCEPTION 'Monthly AI credit limit reached for this subscription plan (%). Contact your platform administrator.',
      (SELECT max_ai_credits_monthly FROM public.organizations WHERE id = v_org)
      USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.enforce_hotel_entitlement()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  -- platform operators (incl. inside an audited session) bypass tenant quotas
  IF public.is_platform_operator() THEN RETURN NEW; END IF;
  IF NEW.organization_id IS NOT NULL AND NOT public.check_entitlement(NEW.organization_id, 'hotel') THEN
    RAISE EXCEPTION 'Hotel limit reached for this subscription plan (%).',
      (public.effective_entitlements(NEW.organization_id)->>'max_hotels')
      USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END; $function$
;

CREATE OR REPLACE FUNCTION public.enforce_membership_entitlement()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  -- platform operators (incl. inside an audited session) bypass tenant quotas
  IF public.is_platform_operator() THEN RETURN NEW; END IF;
  IF NEW.organization_id IS NOT NULL AND NEW.is_active = true AND NOT public.check_entitlement(NEW.organization_id, 'learner') THEN
    RAISE EXCEPTION 'User seat limit reached for this subscription plan (%).',
      (public.effective_entitlements(NEW.organization_id)->>'max_learners')
      USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END; $function$
;

CREATE OR REPLACE FUNCTION public.enforce_session_limit(p_user_id uuid, p_max_sessions integer DEFAULT 5)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_count integer;
BEGIN
    IF coalesce(auth.role(), '') <> 'service_role' AND auth.uid() IS DISTINCT FROM p_user_id THEN
      RAISE EXCEPTION 'Users can only manage their own sessions';
    END IF;

    SELECT COUNT(*) INTO v_count FROM public.user_sessions
    WHERE user_id = p_user_id AND revoked_at IS NULL AND expires_at > now();
    IF v_count > p_max_sessions THEN
        UPDATE public.user_sessions SET revoked_at = now(), revoked_reason = 'session_limit_exceeded'
        WHERE id IN (
            SELECT id FROM public.user_sessions
            WHERE user_id = p_user_id AND revoked_at IS NULL AND expires_at > now() AND is_current = false
            ORDER BY last_active_at ASC LIMIT v_count - p_max_sessions + 1);
        INSERT INTO public.system_events (event_type, actor_id, entity_type, entity_id, metadata)
        VALUES ('security', p_user_id, 'user', p_user_id,
            jsonb_build_object('security_event_type', 'session.limit_enforced', 'severity', 'warning',
                'previous_count', v_count, 'max_sessions', p_max_sessions));
    END IF;
    RETURN true;
END; $function$
;

CREATE OR REPLACE FUNCTION public.enforce_training_module_publish_integrity()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  PERFORM public.validate_module_quiz_integrity(NEW.id);
  RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.enforce_training_progress_integrity()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF current_setting('app.trusted_progress_write', true) = 'on' THEN
    RETURN NEW;
  END IF;

  IF TG_OP = 'UPDATE' THEN
    NEW.passed := OLD.passed;
    NEW.score_percentage := OLD.score_percentage;
    NEW.quiz_score := OLD.quiz_score;
    NEW.cycle_started_at := OLD.cycle_started_at;
    -- Neither promote to completed nor demote away from it via an untrusted
    -- write - only the trusted RPCs (which set the bypass flag above) may
    -- change completion state.
    IF OLD.status = 'completed' THEN
      NEW.status := 'completed';
    ELSIF NEW.status = 'completed' THEN
      NEW.status := OLD.status;
    END IF;
    IF OLD.completed_at IS NOT NULL THEN
      NEW.completed_at := OLD.completed_at;
    ELSE
      NEW.completed_at := NULL;
    END IF;
  ELSE
    NEW.passed := NULL;
    NEW.score_percentage := NULL;
    NEW.quiz_score := NULL;
    NEW.completed_at := NULL;
    NEW.cycle_started_at := NULL;
    IF NEW.status = 'completed' THEN
      NEW.status := 'in_progress';
    END IF;
  END IF;

  RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.evaluate_organization_quotas(p_org_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_org public.organizations;
  v_plan public.subscription_plans;
  v_billing_period text := to_char(now(), 'YYYY-MM');

  v_hotels_used bigint := 0;
  v_hotels_max bigint := 10;
  v_hotels_pct integer := 0;

  v_learners_used bigint := 0;
  v_learners_max bigint := 100;
  v_learners_pct integer := 0;

  v_storage_used_bytes bigint := 0;
  v_storage_max_gb bigint := 50;
  v_storage_max_bytes bigint := 53687091200; -- 50 * 1024^3
  v_storage_pct integer := 0;

  v_ai_credits_used bigint := 0;
  v_ai_credits_max bigint := 1000;
  v_ai_credits_pct integer := 0;

  v_warnings_triggered jsonb := '[]'::jsonb;
  v_thresholds integer[] := ARRAY[80, 90, 100];
  v_threshold integer;

  v_admin_recipients uuid[];
  v_admin_id uuid;
  v_already_logged boolean;
  v_notif_title text;
  v_notif_msg text;

  v_quota_type text;
  v_used bigint;
  v_max bigint;
  v_pct integer;
  v_items jsonb;
  v_item jsonb;
BEGIN
  IF NOT (public._p7_is_service_context() OR public.is_platform_super_admin() OR public.is_tenant_admin(p_org_id)) THEN
    RAISE EXCEPTION 'not authorized for organization %', p_org_id USING ERRCODE = '42501';
  END IF;

  -- 1. Fetch organization
  SELECT * INTO v_org FROM public.organizations WHERE id = p_org_id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('error', 'Organization not found', 'org_id', p_org_id);
  END IF;

  -- 2. Fetch active subscription plan (if any)
  SELECT sp.* INTO v_plan
  FROM public.subscriptions s
  JOIN public.subscription_plans sp ON sp.id = s.plan_id
  WHERE s.organization_id = p_org_id AND s.status = 'active'
  ORDER BY s.current_period_end DESC NULLS LAST
  LIMIT 1;

  -- 3. Calculate usage & max
  -- Hotels
  SELECT COUNT(*) INTO v_hotels_used
  FROM public.hotels
  WHERE organization_id = p_org_id AND is_deleted = false;
  v_hotels_max := COALESCE(v_org.max_hotels, v_plan.max_hotels, 10);
  IF v_hotels_max > 0 THEN
    v_hotels_pct := LEAST(100, ROUND((v_hotels_used::numeric / v_hotels_max::numeric) * 100));
  ELSE
    v_hotels_pct := 0;
  END IF;

  -- Learners
  SELECT COUNT(*) INTO v_learners_used
  FROM public.organization_memberships
  WHERE organization_id = p_org_id AND is_active = true;
  v_learners_max := COALESCE(v_org.max_learners, v_plan.max_users, 100);
  IF v_learners_max > 0 THEN
    v_learners_pct := LEAST(100, ROUND((v_learners_used::numeric / v_learners_max::numeric) * 100));
  ELSE
    v_learners_pct := 0;
  END IF;

  -- Storage
  v_storage_used_bytes := COALESCE(v_org.storage_used_bytes, 0);
  IF v_storage_used_bytes = 0 THEN
    SELECT COALESCE(SUM(file_size), 0) INTO v_storage_used_bytes
    FROM public.documents
    WHERE organization_id = p_org_id AND is_deleted = false;
  END IF;
  v_storage_max_gb := COALESCE(v_org.max_storage_gb, v_plan.max_storage_gb, 50);
  v_storage_max_bytes := v_storage_max_gb * 1024 * 1024 * 1024;
  IF v_storage_max_bytes > 0 THEN
    v_storage_pct := LEAST(100, ROUND((v_storage_used_bytes::numeric / v_storage_max_bytes::numeric) * 100));
  ELSE
    v_storage_pct := 0;
  END IF;

  -- AI Credits
  v_ai_credits_used := COALESCE(v_org.ai_credits_used_this_month, 0);
  v_ai_credits_max := COALESCE(v_org.max_ai_credits_monthly, 0);
  IF v_ai_credits_max > 0 THEN
    v_ai_credits_pct := LEAST(100, ROUND((v_ai_credits_used::numeric / v_ai_credits_max::numeric) * 100));
  ELSE
    v_ai_credits_pct := 0;
  END IF;

  -- 4. Prepare evaluation items
  v_items := jsonb_build_array(
    jsonb_build_object('quota_type', 'hotels', 'used', v_hotels_used, 'max', v_hotels_max, 'pct', v_hotels_pct),
    jsonb_build_object('quota_type', 'learners', 'used', v_learners_used, 'max', v_learners_max, 'pct', v_learners_pct),
    jsonb_build_object('quota_type', 'storage', 'used', v_storage_used_bytes, 'max', v_storage_max_bytes, 'pct', v_storage_pct),
    jsonb_build_object('quota_type', 'ai_credits', 'used', v_ai_credits_used, 'max', v_ai_credits_max, 'pct', v_ai_credits_pct)
  );

  -- 5. Iterate through quotas & thresholds
  FOR v_item IN SELECT * FROM jsonb_array_elements(v_items) LOOP
    v_quota_type := v_item->>'quota_type';
    v_used := (v_item->>'used')::bigint;
    v_max := (v_item->>'max')::bigint;
    v_pct := (v_item->>'pct')::integer;

    IF v_max > 0 THEN
      FOREACH v_threshold IN ARRAY v_thresholds LOOP
        IF v_pct >= v_threshold THEN
          -- Check if already logged for this billing period & threshold
          SELECT EXISTS (
            SELECT 1 FROM public.quota_warning_logs
            WHERE organization_id = p_org_id
              AND quota_type = v_quota_type
              AND threshold_pct = v_threshold
              AND billing_period = v_billing_period
          ) INTO v_already_logged;

          IF NOT v_already_logged THEN
            -- 1. Insert into quota_warning_logs
            INSERT INTO public.quota_warning_logs (
              organization_id, quota_type, threshold_pct, billing_period, metadata
            ) VALUES (
              p_org_id, v_quota_type, v_threshold, v_billing_period,
              jsonb_build_object('used', v_used, 'max', v_max, 'pct', v_pct)
            )
            ON CONFLICT (organization_id, quota_type, threshold_pct, billing_period) DO NOTHING;

            -- 2. Fetch admin user recipients
            SELECT ARRAY_AGG(DISTINCT user_id) INTO v_admin_recipients
            FROM public.organization_memberships
            WHERE organization_id = p_org_id
              AND is_active = true
              AND role IN ('organization_owner', 'organization_admin');

            v_notif_title := 'Quota Warning: ' || v_quota_type || ' at ' || v_threshold || '%';
            v_notif_msg := 'Your organization has reached ' || v_pct || '% of allocated ' || v_quota_type || ' capacity. Upgrade plan to prevent service disruption.';

            -- 3. Insert notification for each admin
            IF v_admin_recipients IS NOT NULL AND array_length(v_admin_recipients, 1) > 0 THEN
              FOREACH v_admin_id IN ARRAY v_admin_recipients LOOP
                INSERT INTO public.notifications (
                  user_id, type, title, message, link, is_read, metadata, created_at, updated_at
                ) VALUES (
                  v_admin_id,
                  'quota_warning',
                  v_notif_title,
                  v_notif_msg,
                  '/admin/settings?tab=subscription',
                  false,
                  jsonb_build_object(
                    'organization_id', p_org_id,
                    'quota_type', v_quota_type,
                    'threshold_pct', v_threshold,
                    'current_pct', v_pct,
                    'billing_period', v_billing_period
                  ),
                  now(),
                  now()
                );
              END LOOP;
            END IF;

            -- 4. Append to warnings_triggered output
            v_warnings_triggered := v_warnings_triggered || jsonb_build_object(
              'quota_type', v_quota_type,
              'threshold_pct', v_threshold,
              'current_pct', v_pct,
              'recipients_count', COALESCE(array_length(v_admin_recipients, 1), 0)
            );
          END IF;
        END IF;
      END LOOP;
    END IF;
  END LOOP;

  -- 6. Return response jsonb
  RETURN jsonb_build_object(
    'org_id', p_org_id,
    'billing_period', v_billing_period,
    'utilization', jsonb_build_object(
      'hotels', jsonb_build_object('used', v_hotels_used, 'max', v_hotels_max, 'pct', v_hotels_pct),
      'learners', jsonb_build_object('used', v_learners_used, 'max', v_learners_max, 'pct', v_learners_pct),
      'storage', jsonb_build_object('used', v_storage_used_bytes, 'max', v_storage_max_bytes, 'pct', v_storage_pct, 'used_gb', ROUND((v_storage_used_bytes::numeric / (1024*1024*1024)::numeric), 2), 'max_gb', v_storage_max_gb),
      'ai_credits', jsonb_build_object('used', v_ai_credits_used, 'max', v_ai_credits_max, 'pct', v_ai_credits_pct)
    ),
    'warnings_triggered', v_warnings_triggered
  );
END;
$function$
;

CREATE OR REPLACE FUNCTION public.export_organization_archive(p_org_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_result jsonb;
BEGIN
  IF NOT (public.is_platform_operator() OR public.is_tenant_admin(p_org_id)) THEN
    RAISE EXCEPTION 'Access Denied: Tenant admin privileges required to export organization archive.'
      USING ERRCODE = '42501';
  END IF;

  SELECT jsonb_build_object(
    'exported_at', now(),
    'organization', (SELECT row_to_json(o) FROM public.organizations o WHERE o.id = p_org_id),
    'hotels', (SELECT jsonb_agg(row_to_json(h)) FROM public.hotels h WHERE h.organization_id = p_org_id AND h.is_deleted = false),
    'departments', (SELECT jsonb_agg(row_to_json(d)) FROM public.departments d WHERE d.organization_id = p_org_id AND d.is_active = true),
    'memberships', (SELECT jsonb_agg(row_to_json(om)) FROM public.organization_memberships om WHERE om.organization_id = p_org_id AND om.is_active = true),
    'training_modules', (SELECT jsonb_agg(row_to_json(m)) FROM public.training_modules m WHERE m.organization_id = p_org_id AND m.is_deleted = false),
    'quizzes', (SELECT jsonb_agg(row_to_json(q)) FROM public.learning_quizzes q WHERE q.organization_id = p_org_id AND NOT COALESCE(q.is_deleted, false)),
    'assignments', (SELECT jsonb_agg(row_to_json(r)) FROM public.training_assignment_rules r WHERE r.organization_id = p_org_id AND NOT COALESCE(r.is_deleted, false)),
    'training_progress', (SELECT jsonb_agg(row_to_json(tp)) FROM public.training_progress tp WHERE tp.organization_id = p_org_id AND tp.is_deleted = false),
    'completion_history', (SELECT jsonb_agg(row_to_json(h)) FROM public.training_completion_history h WHERE h.organization_id = p_org_id),
    'certificates', (SELECT jsonb_agg(row_to_json(cert)) FROM public.certificates cert WHERE cert.organization_id = p_org_id),
    'documents', (SELECT jsonb_agg(row_to_json(doc)) FROM public.documents doc WHERE doc.organization_id = p_org_id AND doc.status = 'PUBLISHED')
  ) INTO v_result;

  RETURN v_result;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.feature_enabled(p_org_id uuid, p_key text)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_flag public.platform_feature_flags;
  v_override boolean;
  v_plan_code text;
BEGIN
  SELECT * INTO v_flag FROM public.platform_feature_flags WHERE key = p_key;
  IF NOT FOUND THEN RETURN false; END IF;
  SELECT enabled INTO v_override FROM public.organization_feature_overrides
   WHERE organization_id = p_org_id AND key = p_key;
  IF v_override IS NOT NULL THEN RETURN v_override; END IF;
  IF v_flag.min_plan_code IS NOT NULL THEN
    SELECT sp.code INTO v_plan_code
    FROM public.subscriptions s JOIN public.subscription_plans sp ON sp.id = s.plan_id
    WHERE s.organization_id = p_org_id AND s.status = 'active'
    ORDER BY s.current_period_end DESC NULLS LAST LIMIT 1;
    IF public._plan_rank(COALESCE(v_plan_code, '')) < public._plan_rank(v_flag.min_plan_code) THEN
      RETURN false;
    END IF;
  END IF;
  RETURN v_flag.default_enabled;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.generate_audit_export_hash(p_export_id uuid, p_data jsonb)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_hash text;
    v_salt text;
BEGIN
    -- Generate unique salt based on export metadata
    v_salt := encode(
        digest(
            p_export_id::text || current_setting('app.settings.jwt_secret', true) || now()::text,
            'sha256'
        ),
        'hex'
    );
    
    -- Generate hash of data + salt
    v_hash := encode(
        digest(
            v_salt || p_data::text || v_salt,
            'sha256'
        ),
        'hex'
    );
    
    RETURN v_hash;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.generate_certificate_number()
 RETURNS character varying
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE
  prefix VARCHAR(4);
  year_code VARCHAR(2);
  seq_num INTEGER;
  cert_number VARCHAR(20);
BEGIN
  prefix := 'PHC-'; -- Prime Hotels Certificate
  year_code := TO_CHAR(NOW(), 'YY');
  
  -- Get next sequence number for current year
  SELECT COALESCE(MAX(CAST(SUBSTRING(certificate_number FROM 8 FOR 6) AS INTEGER)), 0) + 1
  INTO seq_num
  FROM certificates
  WHERE certificate_number LIKE prefix || year_code || '-%';
  
  cert_number := prefix || year_code || '-' || LPAD(seq_num::TEXT, 6, '0');
  RETURN cert_number;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.generate_eom_auto_selection(p_property_id uuid, p_month integer, p_year integer)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE
    v_winner RECORD;
    v_config eom_automation_config%ROWTYPE;
    v_selection_id UUID;
    v_reason_en TEXT;
    v_reason_ar TEXT;
BEGIN
    -- Ensure calculation is done
    PERFORM run_eom_calculation(p_property_id, p_month, p_year);
    
    -- Get the winner (rank 1, eligible)
    SELECT esh.*, p.full_name, p.job_title
    INTO v_winner
    FROM eom_scoring_history esh
    JOIN profiles p ON p.id = esh.user_id
    WHERE esh.property_id = p_property_id
    AND esh.month = p_month
    AND esh.year = p_year
    AND esh.is_eligible = true
    AND esh.rank = 1
    ORDER BY esh.total_score DESC
    LIMIT 1;
    
    IF NOT FOUND THEN
        RAISE EXCEPTION 'No eligible employee found for Employee of the Month';
    END IF;
    
    -- Get config for auto-announce setting
    SELECT * INTO v_config
    FROM eom_automation_config
    WHERE property_id = p_property_id;
    
    -- Generate reasons
    v_reason_en := format(
        'Selected based on outstanding performance: %s%% task completion, %s%% training completion, %s%% SOP compliance, and %s%% attendance rate. Total score: %s/100.',
        v_winner.task_completion_rate,
        v_winner.training_completion_rate,
        v_winner.sop_compliance_rate,
        v_winner.attendance_rate,
        v_winner.total_score
    );
    
    v_reason_ar := format(
        'تم الاختيار بناءً على الأداء المتميز: %s%% إنجاز المهام، %s%% إنجاز التدريب، %s%% الالتزام بإجراءات التشغيل القياسية، و%s%% معدل الحضور. النتيجة الإجمالية: %s/100.',
        v_winner.task_completion_rate,
        v_winner.training_completion_rate,
        v_winner.sop_compliance_rate,
        v_winner.attendance_rate,
        v_winner.total_score
    );
    
    -- Insert or update auto-selection
    INSERT INTO eom_auto_selections (
        property_id, user_id, month, year,
        total_score, selection_reason_en, selection_reason_ar,
        status, scoring_history_id
    ) VALUES (
        p_property_id, v_winner.user_id, p_month, p_year,
        v_winner.total_score, v_reason_en, v_reason_ar,
        CASE WHEN v_config.auto_announce THEN 'announced' ELSE 'pending' END,
        v_winner.id
    )
    ON CONFLICT (property_id, month, year) 
    DO UPDATE SET
        user_id = EXCLUDED.user_id,
        total_score = EXCLUDED.total_score,
        selection_reason_en = EXCLUDED.selection_reason_en,
        selection_reason_ar = EXCLUDED.selection_reason_ar,
        status = CASE WHEN v_config.auto_announce THEN 'announced' ELSE 'pending' END,
        scoring_history_id = EXCLUDED.scoring_history_id,
        updated_at = now()
    RETURNING id INTO v_selection_id;
    
    -- If auto-announce is enabled, create the actual EOM record
    IF v_config.auto_announce THEN
        PERFORM announce_eom_from_selection(v_selection_id);
    END IF;
    
    RETURN v_selection_id;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.generate_mfa_secret(p_user_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_secret text;
  v_backup_codes text[];
  v_qr_code_url text;
  v_secret_alphabet constant text := 'ABCDEFGHIJKLMNOPQRSTUVWXYZ234567';
BEGIN
  IF auth.uid() IS DISTINCT FROM p_user_id THEN
    RAISE EXCEPTION 'Users can only generate MFA secrets for themselves';
  END IF;

  -- Check if user already has MFA enabled
  IF EXISTS (SELECT 1 FROM public.mfa_secrets WHERE user_id = p_user_id AND enabled = true) THEN
    RETURN jsonb_build_object('error', 'MFA already enabled');
  END IF;
  
  -- Generate a 32-character base32-compatible secret for authenticator apps
  SELECT string_agg(
    substr(v_secret_alphabet, (get_byte(extensions.gen_random_bytes(1), 0) % 32) + 1, 1),
    ''
  )
  INTO v_secret
  FROM generate_series(1, 32);
  
  -- Generate backup codes
  v_backup_codes := ARRAY(
    SELECT substring(encode(extensions.gen_random_bytes(4), 'hex'), 1, 8)
    FROM generate_series(1, 8)
  );
  
  -- Generate QR code URL (in production, this would be a proper otpauth URL)
  v_qr_code_url := 'https://api.qrserver.com/v1/create-qr-code/?size=200x200&data=otpauth://totp/PHG:' || p_user_id || '?secret=' || v_secret || '&issuer=PHG%20Connect';
  
  -- Insert or update MFA secret
  INSERT INTO public.mfa_secrets (user_id, secret, backup_codes, enabled)
  VALUES (p_user_id, v_secret, v_backup_codes, false)
  ON CONFLICT (user_id) 
  DO UPDATE SET 
    secret = EXCLUDED.secret,
    backup_codes = EXCLUDED.backup_codes,
    enabled = false,
    updated_at = now();
  
  RETURN jsonb_build_object(
    'secret', v_secret,
    'backupCodes', v_backup_codes,
    'qrCodeUrl', v_qr_code_url
  );
END;
$function$
;

CREATE OR REPLACE FUNCTION public.generate_totp(p_secret_base32 text, p_at_time bigint DEFAULT (EXTRACT(epoch FROM now()))::bigint, p_time_step integer DEFAULT 30, p_digits integer DEFAULT 6)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
DECLARE
  key_bytes bytea;
  counter bigint;
  counter_bytes bytea := '\x0000000000000000'::bytea;
  hmac_result bytea;
  offset_val integer;
  bin_code bigint;
  otp bigint;
  i integer;
  byte_val integer;
BEGIN
  key_bytes := public.base32_decode(p_secret_base32);
  counter := p_at_time / p_time_step;

  FOR i IN 0..7 LOOP
    byte_val := (counter >> ((7 - i) * 8)) & 255;
    counter_bytes := set_byte(counter_bytes, i, byte_val);
  END LOOP;

  hmac_result := extensions.hmac(counter_bytes, key_bytes, 'sha1');

  offset_val := get_byte(hmac_result, length(hmac_result) - 1) & 15;

  bin_code := ((get_byte(hmac_result, offset_val) & 127) << 24)
            | ((get_byte(hmac_result, offset_val + 1) & 255) << 16)
            | ((get_byte(hmac_result, offset_val + 2) & 255) << 8)
            | (get_byte(hmac_result, offset_val + 3) & 255);

  otp := bin_code % (10 ^ p_digits)::bigint;

  RETURN lpad(otp::text, p_digits, '0');
END;
$function$
;

CREATE OR REPLACE FUNCTION public.generate_verification_code()
 RETURNS character varying
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
begin
  return upper(encode(extensions.gen_random_bytes(16), 'hex'));
end;
$function$
;

CREATE OR REPLACE FUNCTION public.get_ai_agent_policies()
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  SELECT coalesce(jsonb_agg(to_jsonb(p) ORDER BY p.agent_role), '[]'::jsonb)
  FROM public.ai_agent_policies p;
$function$
;

CREATE OR REPLACE FUNCTION public.get_ai_daily_spend_usd()
 RETURNS numeric
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  select coalesce(sum(estimated_cost_usd), 0)::numeric
  from public.ai_usage_log
  where created_at >= date_trunc('day', now() at time zone 'utc')
    and coalesce(success, true) = true;
$function$
;

CREATE OR REPLACE FUNCTION public.get_ai_model_registry()
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  SELECT jsonb_build_object(
    'providers', coalesce((SELECT jsonb_agg(to_jsonb(p) ORDER BY p.priority) FROM public.ai_providers p), '[]'::jsonb),
    'models',    coalesce((SELECT jsonb_agg(to_jsonb(m) ORDER BY m.quality_score DESC) FROM public.ai_models m WHERE m.enabled), '[]'::jsonb),
    'generated_at', now()
  );
$function$
;

CREATE OR REPLACE FUNCTION public.get_ai_model_verification_status()
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  SELECT jsonb_build_object(
    'models', coalesce((
      SELECT jsonb_agg(jsonb_build_object(
        'id', m.id, 'provider', m.provider, 'provider_model_id', m.provider_model_id,
        'display_name', m.display_name, 'modality', m.modality, 'cost_tier', m.cost_tier,
        'is_free', m.is_free, 'supports_json_object', m.supports_json_object,
        'image_generation', m.image_generation, 'availability', m.availability, 'enabled', m.enabled,
        'quality_score', m.quality_score, 'speed_score', m.speed_score,
        'verified_at', m.verified_at, 'last_probe_ok', m.last_probe_ok,
        'last_probe_at', m.last_probe_at, 'capability_checked_at', m.capability_checked_at
      ) ORDER BY m.provider, m.availability, m.id)
      FROM public.ai_models m
    ), '[]'::jsonb),
    'recent_probes', coalesce((
      SELECT jsonb_agg(jsonb_build_object(
        'id', p.id, 'model_id', p.model_id, 'probed_at', p.probed_at, 'ok', p.ok,
        'latency_ms', p.latency_ms, 'http_status', p.http_status, 'detail', p.detail, 'probe_type', p.probe_type
      ) ORDER BY p.probed_at DESC)
      FROM (SELECT * FROM public.ai_model_probes ORDER BY probed_at DESC LIMIT 100) p
    ), '[]'::jsonb),
    'generated_at', now()
  );
$function$
;

CREATE OR REPLACE FUNCTION public.get_ai_routing_plan(p_capability text, p_free_only boolean DEFAULT false, p_allow_premium boolean DEFAULT false, p_limit integer DEFAULT 8, p_agent_role text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  cfg              record;
  pol              record;
  v_modality       text := CASE WHEN p_capability = 'image' THEN 'image'
                                WHEN p_capability = 'embedding' THEN 'embedding'
                                ELSE 'text' END;
  v_free_only      boolean;
  v_allow_premium  boolean;
  v_routing_mode   text;
  v_agent_disabled text[] := ARRAY[]::text[];
  v_agent_force    text := NULL;
  v_agent_enabled  boolean := true;
  v_result         jsonb;
BEGIN
  SELECT free_only_mode, enabled_providers, disabled_model_ids, force_enabled_model_ids, routing_mode, allow_premium_images
    INTO cfg
  FROM public.ai_platform_config WHERE id = true;

  IF p_agent_role IS NOT NULL THEN
    SELECT enabled, routing_mode_override, force_model_id, disabled_model_ids
      INTO pol
    FROM public.ai_agent_policies WHERE agent_role = p_agent_role;
    IF FOUND THEN
      v_agent_enabled  := coalesce(pol.enabled, true);
      v_agent_disabled := coalesce(pol.disabled_model_ids, ARRAY[]::text[]);
      v_agent_force    := pol.force_model_id;
    END IF;
  END IF;

  v_free_only     := p_free_only OR coalesce(cfg.free_only_mode, false);
  v_allow_premium := p_allow_premium OR CASE WHEN v_modality = 'image' THEN coalesce(cfg.allow_premium_images, false) ELSE true END;
  v_routing_mode  := coalesce(
                       (SELECT routing_mode_override FROM public.ai_agent_policies WHERE agent_role = p_agent_role),
                       cfg.routing_mode
                     );

  IF NOT v_agent_enabled THEN
    RETURN jsonb_build_object(
      'capability', p_capability, 'modality', v_modality, 'free_only', v_free_only,
      'routing_mode', v_routing_mode, 'agent_role', p_agent_role, 'agent_disabled', true,
      'models', '[]'::jsonb
    );
  END IF;

  SELECT jsonb_agg(row_to_json(t) ORDER BY t.rank)
    INTO v_result
  FROM (
    SELECT
      m.id, m.provider, m.provider_model_id, m.modality, m.cost_tier, m.is_free,
      m.supports_json_object, m.supports_json_schema, m.image_generation, m.image_editing,
      m.quality_score, m.speed_score,
      row_number() OVER (ORDER BY
        (v_agent_force IS NOT NULL AND m.id = v_agent_force) DESC,
        (m.id = ANY (coalesce(cfg.force_enabled_model_ids, ARRAY[]::text[]))) DESC,
        CASE WHEN v_routing_mode IN ('free_first','balanced') THEN m.is_free ELSE true END DESC,
        CASE p_capability
          WHEN 'structured_json' THEN (m.supports_json_schema::int * 1000 + m.supports_json_object::int * 500 + m.quality_score)
          WHEN 'reasoning'       THEN (('deep_reasoning' = ANY (m.capabilities))::int * 1000 + m.quality_score)
          WHEN 'fast'            THEN m.speed_score
          WHEN 'compliance'      THEN (('arabic_native' = ANY (m.capabilities))::int * 300 + m.supports_json_object::int * 200 + m.quality_score)
          WHEN 'image'           THEN m.quality_score
          ELSE m.quality_score
        END DESC,
        m.speed_score DESC
      ) AS rank
    FROM public.ai_models m
    JOIN public.ai_providers pr ON pr.id = m.provider
    WHERE m.enabled
      AND m.availability = 'verified'
      AND m.modality = v_modality
      AND m.id <> ALL (coalesce(cfg.disabled_model_ids, ARRAY[]::text[]))
      AND m.id <> ALL (v_agent_disabled)
      AND (m.provider = ANY (coalesce(cfg.enabled_providers, ARRAY['gemini','groq','openrouter','huggingface','cloudflare','recraft'])))
      AND pr.enabled
      AND (pr.health_status NOT IN ('auth_failed','quota_exhausted','disabled','unavailable'))
      AND (pr.key_status NOT IN ('invalid','missing'))
      AND (pr.cooldown_until IS NULL OR pr.cooldown_until < now())
      AND (NOT v_free_only OR m.is_free)
      AND (v_allow_premium OR m.cost_tier <> 'premium')
      AND (p_capability <> 'structured_json' OR m.supports_json_object OR m.provider = 'recraft')
      AND (p_capability <> 'reasoning' OR 'deep_reasoning' = ANY (m.capabilities))
  ) t
  WHERE t.rank <= p_limit;

  RETURN jsonb_build_object(
    'capability', p_capability, 'modality', v_modality, 'free_only', v_free_only,
    'routing_mode', v_routing_mode, 'agent_role', p_agent_role, 'agent_disabled', false,
    'models', coalesce(v_result, '[]'::jsonb)
  );
END;
$function$
;

CREATE OR REPLACE FUNCTION public.get_analytics_summary()
 RETURNS json
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_orgs uuid[] := public.learning_manager_org_ids();
BEGIN
  IF cardinality(v_orgs) = 0 THEN
    RETURN json_build_object('active_now', 0, 'active_today', 0, 'sessions_today', 0);
  END IF;
  RETURN json_build_object(
    'active_now', (SELECT count(DISTINCT user_id) FROM public.user_sessions
                   WHERE organization_id = ANY (v_orgs)
                     AND last_active_at > now() - interval '5 minutes'
                     AND revoked_at IS NULL AND expires_at > now()),
    'active_today', (SELECT count(DISTINCT user_id) FROM public.analytics_events
                     WHERE organization_id = ANY (v_orgs)
                       AND "timestamp" >= date_trunc('day', now())),
    'sessions_today', (SELECT count(*) FROM public.user_sessions
                       WHERE organization_id = ANY (v_orgs)
                         AND created_at >= date_trunc('day', now()))
  );
END;
$function$
;

CREATE OR REPLACE FUNCTION public.get_announcement_compliance_breakdown(p_announcement_id uuid)
 RETURNS TABLE(scope_type text, scope_id uuid, scope_name text, total_users bigint, read_users bigint, acknowledged_users bigint)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NOT has_any_role((SELECT auth.uid()),
       ARRAY['super_admin','corporate_admin','regional_admin','regional_hr','property_manager','property_hr','department_head']::app_role[]) THEN
    RETURN;
  END IF;

  RETURN QUERY
  SELECT 'property'::text, h.id, h.name,
    (SELECT count(*) FROM organization_memberships om WHERE om.is_active = true AND om.hotel_id = h.id),
    (SELECT count(DISTINCT ar.user_id) FROM announcement_reads ar
       JOIN organization_memberships om ON om.user_id = ar.user_id AND om.is_active = true
       WHERE ar.announcement_id = p_announcement_id AND om.hotel_id = h.id),
    (SELECT count(DISTINCT aa.user_id) FROM announcement_acknowledgments aa
       JOIN organization_memberships om ON om.user_id = aa.user_id AND om.is_active = true
       WHERE aa.announcement_id = p_announcement_id AND om.hotel_id = h.id)
  FROM announcement_targets t
  JOIN hotels h ON h.id = ANY(t.target_properties)
  WHERE t.announcement_id = p_announcement_id

  UNION ALL
  SELECT 'department'::text, d.id, d.name,
    (SELECT count(*) FROM organization_memberships om WHERE om.is_active = true AND om.department_id = d.id),
    (SELECT count(DISTINCT ar.user_id) FROM announcement_reads ar
       JOIN organization_memberships om ON om.user_id = ar.user_id AND om.is_active = true
       WHERE ar.announcement_id = p_announcement_id AND om.department_id = d.id),
    (SELECT count(DISTINCT aa.user_id) FROM announcement_acknowledgments aa
       JOIN organization_memberships om ON om.user_id = aa.user_id AND om.is_active = true
       WHERE aa.announcement_id = p_announcement_id AND om.department_id = d.id)
  FROM announcement_targets t
  JOIN departments d ON d.id = ANY(t.target_departments)
  WHERE t.announcement_id = p_announcement_id;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.get_assessment_analytics_pass_rates(p_days integer DEFAULT 90)
 RETURNS TABLE(quiz_type text, quiz_entity_id uuid, quiz_title text, completed_sessions bigint, distinct_learners bigint, passed bigint, failed bigint, pass_rate numeric, avg_score numeric)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
    SELECT
        s.quiz_type,
        s.quiz_entity_id,
        coalesce(tm.title, lq.title, '(unnamed quiz)') AS quiz_title,
        count(*)                                       AS completed_sessions,
        count(DISTINCT s.user_id)                      AS distinct_learners,
        count(*) FILTER (WHERE s.passed IS TRUE)       AS passed,
        count(*) FILTER (WHERE s.passed IS NOT TRUE)   AS failed,
        round(100.0 * count(*) FILTER (WHERE s.passed IS TRUE) / nullif(count(*), 0), 1) AS pass_rate,
        round(avg(s.score_percentage)::numeric, 1)     AS avg_score
      FROM public.unified_quiz_sessions s
      LEFT JOIN public.training_modules tm ON tm.id = s.quiz_entity_id
      LEFT JOIN public.learning_quizzes lq ON lq.id = s.quiz_entity_id
     WHERE s.organization_id = ANY (public.learning_manager_org_ids())
       AND s.completed_at IS NOT NULL
       AND s.completed_at >= now() - make_interval(days => greatest(p_days, 1))
     GROUP BY s.quiz_type, s.quiz_entity_id, tm.title, lq.title
     ORDER BY completed_sessions DESC;
$function$
;

CREATE OR REPLACE FUNCTION public.get_assessment_analytics_questions(p_module_id uuid DEFAULT NULL::uuid, p_min_attempts integer DEFAULT 1)
 RETURNS TABLE(question_id uuid, question_text text, question_type text, difficulty text, training_module_id uuid, module_title text, attempts bigint, distinct_learners bigint, pct_correct numeric, discrimination numeric, avg_time_seconds numeric, hint_used_rate numeric)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
    WITH scope AS (SELECT public.learning_manager_org_ids() AS orgs),
    joined AS (
        SELECT
            a.question_id,
            a.user_id,
            a.is_correct,
            a.hint_used,
            a.time_spent_seconds,
            s.score_percentage AS session_score
          FROM public.unified_question_attempts a
          CROSS JOIN scope
          LEFT JOIN public.unified_quiz_sessions s ON s.id = a.session_id
         WHERE a.organization_id = ANY (scope.orgs)
    )
    SELECT
        q.id,
        q.question_text,
        (q.question_type)::text,
        (q.difficulty)::text,
        q.training_module_id,
        tm.title,
        count(*)                                              AS attempts,
        count(DISTINCT j.user_id)                               AS distinct_learners,
        round(100.0 * count(*) FILTER (WHERE j.is_correct) / nullif(count(*), 0), 1) AS pct_correct,
        round(corr((j.is_correct)::int::numeric, j.session_score)::numeric, 3)         AS discrimination,
        round(avg(nullif(j.time_spent_seconds, 0))::numeric, 1) AS avg_time_seconds,
        round(100.0 * count(*) FILTER (WHERE j.hint_used) / nullif(count(*), 0), 1)  AS hint_used_rate
      FROM public.unified_questions q
      JOIN joined j ON j.question_id = q.id
      LEFT JOIN public.training_modules tm ON tm.id = q.training_module_id
     WHERE (p_module_id IS NULL OR q.training_module_id = p_module_id)
     GROUP BY q.id, q.question_text, q.question_type, q.difficulty, q.training_module_id, tm.title
    HAVING count(*) >= greatest(p_min_attempts, 1)
     ORDER BY pct_correct ASC NULLS LAST;
$function$
;

CREATE OR REPLACE FUNCTION public.get_assessment_analytics_wrong_answers(p_question_id uuid)
 RETURNS TABLE(answer_value text, answer_label text, is_correct boolean, times_chosen bigint, pct_of_attempts numeric)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
    WITH picks AS (
        SELECT
            coalesce(a.selected_answer, '(no answer)') AS answer_value,
            a.is_correct,
            count(*) AS times_chosen
          FROM public.unified_question_attempts a
         WHERE a.question_id = p_question_id
           AND a.organization_id = ANY (public.learning_manager_org_ids())
         GROUP BY coalesce(a.selected_answer, '(no answer)'), a.is_correct
    ),
    total AS (SELECT sum(times_chosen) AS n FROM picks)
    SELECT
        p.answer_value,
        coalesce(o.option_text, p.answer_value) AS answer_label,
        p.is_correct,
        p.times_chosen,
        round(100.0 * p.times_chosen / nullif((SELECT n FROM total), 0), 1) AS pct_of_attempts
      FROM picks p
      LEFT JOIN public.unified_question_options o
        ON (o.id::text = p.answer_value OR o.option_text = p.answer_value)
       AND o.question_id = p_question_id
     ORDER BY p.times_chosen DESC;
$function$
;

CREATE OR REPLACE FUNCTION public.get_assignable_learners(p_org_id uuid, p_brand_id uuid DEFAULT NULL::uuid, p_hotel_id uuid DEFAULT NULL::uuid, p_dept_id uuid DEFAULT NULL::uuid, p_role text DEFAULT NULL::text, p_search text DEFAULT NULL::text, p_limit integer DEFAULT 50, p_offset integer DEFAULT 0)
 RETURNS TABLE(id uuid, full_name text, email text, avatar_url text, hotel_id uuid, hotel_name text, brand_id uuid, brand_name text, department_id uuid, department_name text, role text, job_title text)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_scopes jsonb;
  v_can_org boolean;
  v_auth_hotels uuid[];
  v_auth_depts uuid[];
  v_auth_brands uuid[];
  v_search_pattern text := NULL;
BEGIN
  v_scopes := public.get_caller_assignment_scopes(p_org_id);
  
  IF (v_scopes->>'is_platform_admin')::boolean IS NOT TRUE 
     AND (v_scopes->>'can_assign_individual')::boolean IS NOT TRUE THEN
    RETURN;
  END IF;

  v_can_org := (v_scopes->>'can_assign_org')::boolean IS TRUE OR (v_scopes->>'is_platform_admin')::boolean IS TRUE;
  
  IF NOT v_can_org THEN
    IF v_scopes->'authorized_hotel_ids' IS NOT NULL AND jsonb_array_length(v_scopes->'authorized_hotel_ids') > 0 THEN
      SELECT ARRAY(SELECT jsonb_array_elements_text(v_scopes->'authorized_hotel_ids')::uuid) INTO v_auth_hotels;
    END IF;
    IF v_scopes->'authorized_dept_ids' IS NOT NULL AND jsonb_array_length(v_scopes->'authorized_dept_ids') > 0 THEN
      SELECT ARRAY(SELECT jsonb_array_elements_text(v_scopes->'authorized_dept_ids')::uuid) INTO v_auth_depts;
    END IF;
    IF v_scopes->'authorized_brand_ids' IS NOT NULL AND jsonb_array_length(v_scopes->'authorized_brand_ids') > 0 THEN
      SELECT ARRAY(SELECT jsonb_array_elements_text(v_scopes->'authorized_brand_ids')::uuid) INTO v_auth_brands;
    END IF;
  END IF;

  IF p_search IS NOT NULL AND trim(p_search) <> '' THEN
    v_search_pattern := '%' || trim(p_search) || '%';
  END IF;

  RETURN QUERY
  SELECT DISTINCT
    p.id,
    COALESCE(p.full_name, 'Learner') AS full_name,
    p.email,
    p.avatar_url,
    h.id AS hotel_id,
    h.name AS hotel_name,
    b.id AS brand_id,
    b.name AS brand_name,
    d.id AS department_id,
    d.name AS department_name,
    om.role::text AS role,
    p.job_title
  FROM public.organization_memberships om
  JOIN public.profiles p ON p.id = om.user_id
  LEFT JOIN public.hotels h ON h.id = om.hotel_id
  LEFT JOIN public.brands b ON b.id = COALESCE(om.brand_id, h.brand_id)
  LEFT JOIN public.departments d ON d.id = om.department_id
  WHERE om.organization_id = p_org_id
    AND om.is_active = true
    AND (v_can_org OR v_auth_hotels IS NULL OR om.hotel_id = ANY(v_auth_hotels))
    AND (v_can_org OR v_auth_depts IS NULL OR om.department_id = ANY(v_auth_depts))
    AND (v_can_org OR v_auth_brands IS NULL OR om.brand_id = ANY(v_auth_brands) OR h.brand_id = ANY(v_auth_brands))
    -- Requested filters
    AND (p_brand_id IS NULL OR b.id = p_brand_id OR om.brand_id = p_brand_id)
    AND (p_hotel_id IS NULL OR om.hotel_id = p_hotel_id)
    AND (p_dept_id IS NULL OR om.department_id = p_dept_id)
    AND (p_role IS NULL OR p_role = 'all' OR om.role::text = p_role)
    -- Search filter
    AND (
      v_search_pattern IS NULL
      OR p.full_name ILIKE v_search_pattern
      OR p.email ILIKE v_search_pattern
      OR p.job_title ILIKE v_search_pattern
    )
  ORDER BY full_name ASC
  LIMIT p_limit OFFSET p_offset;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.get_assignable_recipients_count(p_org_id uuid, p_brand_id uuid DEFAULT NULL::uuid, p_hotel_id uuid DEFAULT NULL::uuid, p_dept_id uuid DEFAULT NULL::uuid, p_role text DEFAULT NULL::text, p_search text DEFAULT NULL::text, p_individual_user_ids uuid[] DEFAULT NULL::uuid[], p_scope_type text DEFAULT 'organization'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_scopes jsonb;
  v_can_org boolean;
  v_auth_hotels uuid[];
  v_auth_depts uuid[];
  v_auth_brands uuid[];
  v_total_count integer := 0;
  v_hotel_count integer := 0;
  v_dept_count integer := 0;
BEGIN
  v_scopes := public.get_caller_assignment_scopes(p_org_id);
  
  IF (v_scopes->>'is_platform_admin')::boolean IS NOT TRUE 
     AND (v_scopes->>'can_assign_individual')::boolean IS NOT TRUE THEN
    RETURN jsonb_build_object('recipient_count', 0, 'hotel_count', 0, 'dept_count', 0);
  END IF;

  v_can_org := (v_scopes->>'can_assign_org')::boolean IS TRUE OR (v_scopes->>'is_platform_admin')::boolean IS TRUE;
  
  IF NOT v_can_org THEN
    IF v_scopes->'authorized_hotel_ids' IS NOT NULL AND jsonb_array_length(v_scopes->'authorized_hotel_ids') > 0 THEN
      SELECT ARRAY(SELECT jsonb_array_elements_text(v_scopes->'authorized_hotel_ids')::uuid) INTO v_auth_hotels;
    END IF;
    IF v_scopes->'authorized_dept_ids' IS NOT NULL AND jsonb_array_length(v_scopes->'authorized_dept_ids') > 0 THEN
      SELECT ARRAY(SELECT jsonb_array_elements_text(v_scopes->'authorized_dept_ids')::uuid) INTO v_auth_depts;
    END IF;
    IF v_scopes->'authorized_brand_ids' IS NOT NULL AND jsonb_array_length(v_scopes->'authorized_brand_ids') > 0 THEN
      SELECT ARRAY(SELECT jsonb_array_elements_text(v_scopes->'authorized_brand_ids')::uuid) INTO v_auth_brands;
    END IF;
  END IF;

  IF p_scope_type = 'individual' AND p_individual_user_ids IS NOT NULL THEN
    SELECT 
      COUNT(DISTINCT om.user_id),
      COUNT(DISTINCT om.hotel_id),
      COUNT(DISTINCT om.department_id)
    INTO v_total_count, v_hotel_count, v_dept_count
    FROM public.organization_memberships om
    WHERE om.organization_id = p_org_id
      AND om.is_active = true
      AND om.user_id = ANY(p_individual_user_ids)
      AND (v_can_org OR v_auth_hotels IS NULL OR om.hotel_id = ANY(v_auth_hotels))
      AND (v_can_org OR v_auth_depts IS NULL OR om.department_id = ANY(v_auth_depts));
  ELSE
    SELECT 
      COUNT(DISTINCT om.user_id),
      COUNT(DISTINCT om.hotel_id),
      COUNT(DISTINCT om.department_id)
    INTO v_total_count, v_hotel_count, v_dept_count
    FROM public.organization_memberships om
    LEFT JOIN public.hotels h ON h.id = om.hotel_id
    WHERE om.organization_id = p_org_id
      AND om.is_active = true
      AND (v_can_org OR v_auth_hotels IS NULL OR om.hotel_id = ANY(v_auth_hotels))
      AND (v_can_org OR v_auth_depts IS NULL OR om.department_id = ANY(v_auth_depts))
      AND (v_can_org OR v_auth_brands IS NULL OR om.brand_id = ANY(v_auth_brands) OR h.brand_id = ANY(v_auth_brands))
      AND (p_brand_id IS NULL OR om.brand_id = p_brand_id OR h.brand_id = p_brand_id)
      AND (p_hotel_id IS NULL OR om.hotel_id = p_hotel_id)
      AND (p_dept_id IS NULL OR om.department_id = p_dept_id)
      AND (p_role IS NULL OR p_role = 'all' OR om.role::text = p_role);
  END IF;

  RETURN jsonb_build_object(
    'recipient_count', COALESCE(v_total_count, 0),
    'hotel_count', COALESCE(v_hotel_count, 0),
    'dept_count', COALESCE(v_dept_count, 0)
  );
END;
$function$
;

CREATE OR REPLACE FUNCTION public.get_audit_data_for_export(p_scope jsonb, p_batch_size integer DEFAULT 1000, p_batch_offset integer DEFAULT 0)
 RETURNS TABLE(log_id uuid, entity_type text, entity_id text, action text, user_id uuid, user_name text, user_email text, created_at timestamp with time zone, details jsonb, ip_address text, property_id text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
    IF NOT public.is_platform_super_admin() THEN
        RAISE EXCEPTION 'Only platform operators may export audit data' USING ERRCODE = '42501';
    END IF;
    RETURN QUERY
    SELECT se.id, se.entity_type, se.entity_id::text, (se.metadata->>'action')::text,
           se.actor_id, p.full_name, u.email, se.created_at, (se.metadata->'details'),
           se.ip_address::text, (se.metadata->>'property_id')
    FROM public.system_events se
    LEFT JOIN public.profiles p ON p.id = se.actor_id
    LEFT JOIN auth.users u ON u.id = se.actor_id
    WHERE se.event_type = 'audit'
      AND (p_scope->>'date_from' IS NULL OR se.created_at >= (p_scope->>'date_from')::timestamptz)
      AND (p_scope->>'date_to' IS NULL OR se.created_at <= (p_scope->>'date_to')::timestamptz)
      AND (p_scope->'entity_types' IS NULL OR se.entity_type = ANY(ARRAY(SELECT jsonb_array_elements_text(p_scope->'entity_types'))))
      AND (p_scope->'actions' IS NULL OR (se.metadata->>'action') = ANY(ARRAY(SELECT jsonb_array_elements_text(p_scope->'actions'))))
    ORDER BY se.created_at DESC
    LIMIT p_batch_size OFFSET p_batch_offset;
END; $function$
;

CREATE OR REPLACE FUNCTION public.get_caller_assignment_scopes(p_org_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_user_id uuid := auth.uid();
  v_is_platform boolean := false;
  v_effective_org_id uuid := p_org_id;
  v_user_memberships record;
  v_can_org boolean := false;
  v_can_brand boolean := false;
  v_can_hotel boolean := false;
  v_can_dept boolean := false;
  v_brand_ids uuid[] := '{}';
  v_hotel_ids uuid[] := '{}';
  v_dept_ids uuid[] := '{}';
  v_primary_role text := 'learner';
  v_primary_hotel_id uuid := NULL;
  v_primary_dept_id uuid := NULL;
BEGIN
  IF v_user_id IS NULL THEN
    RETURN jsonb_build_object('error', 'Unauthenticated');
  END IF;

  v_is_platform := public.is_platform_super_admin() OR public.is_platform_user(v_user_id);

  IF v_effective_org_id IS NULL THEN
    v_effective_org_id := public.get_operator_impersonated_org();
    IF v_effective_org_id IS NULL THEN
      SELECT organization_id INTO v_effective_org_id
        FROM public.organization_memberships
       WHERE user_id = v_user_id AND is_active = true
       ORDER BY is_primary DESC, created_at ASC
       LIMIT 1;
    END IF;
  END IF;

  IF v_is_platform THEN
    RETURN jsonb_build_object(
      'is_platform_admin', true,
      'effective_org_id', v_effective_org_id,
      'can_assign_org', true,
      'can_assign_brand', true,
      'can_assign_hotel', true,
      'can_assign_dept', true,
      'can_assign_role', true,
      'can_assign_individual', true,
      'authorized_brand_ids', NULL,
      'authorized_hotel_ids', NULL,
      'authorized_dept_ids', NULL,
      'primary_role', 'platform_admin'
    );
  END IF;

  FOR v_user_memberships IN
    SELECT role, brand_id, hotel_id, department_id, is_primary
      FROM public.organization_memberships
     WHERE user_id = v_user_id
       AND (organization_id = v_effective_org_id OR v_effective_org_id IS NULL)
       AND is_active = true
  LOOP
    IF v_user_memberships.role IN ('organization_owner', 'organization_admin', 'training_manager') AND v_user_memberships.hotel_id IS NULL THEN
      v_can_org := true;
      v_can_brand := true;
      v_can_hotel := true;
      v_can_dept := true;
      v_primary_role := v_user_memberships.role::text;
    ELSIF v_user_memberships.role IN ('brand_admin') AND v_user_memberships.brand_id IS NOT NULL THEN
      v_can_brand := true;
      v_can_hotel := true;
      v_can_dept := true;
      IF NOT (v_user_memberships.brand_id = ANY(v_brand_ids)) THEN
        v_brand_ids := array_append(v_brand_ids, v_user_memberships.brand_id);
      END IF;
      v_primary_role := 'brand_admin';
    ELSIF v_user_memberships.role IN ('hotel_admin', 'training_manager', 'instructor') AND v_user_memberships.hotel_id IS NOT NULL THEN
      v_can_hotel := true;
      v_can_dept := true;
      IF NOT (v_user_memberships.hotel_id = ANY(v_hotel_ids)) THEN
        v_hotel_ids := array_append(v_hotel_ids, v_user_memberships.hotel_id);
      END IF;
      IF v_primary_hotel_id IS NULL THEN
        v_primary_hotel_id := v_user_memberships.hotel_id;
      END IF;
      v_primary_role := v_user_memberships.role::text;
    ELSIF v_user_memberships.role = 'department_manager' AND v_user_memberships.department_id IS NOT NULL THEN
      v_can_dept := true;
      IF NOT (v_user_memberships.department_id = ANY(v_dept_ids)) THEN
        v_dept_ids := array_append(v_dept_ids, v_user_memberships.department_id);
      END IF;
      IF v_primary_dept_id IS NULL THEN
        v_primary_dept_id := v_user_memberships.department_id;
      END IF;
      IF v_user_memberships.hotel_id IS NOT NULL AND NOT (v_user_memberships.hotel_id = ANY(v_hotel_ids)) THEN
        v_hotel_ids := array_append(v_hotel_ids, v_user_memberships.hotel_id);
      END IF;
      v_primary_role := 'department_manager';
    END IF;
  END LOOP;

  RETURN jsonb_build_object(
    'is_platform_admin', false,
    'effective_org_id', v_effective_org_id,
    'can_assign_org', v_can_org,
    'can_assign_brand', v_can_brand,
    'can_assign_hotel', v_can_hotel,
    'can_assign_dept', v_can_dept,
    'can_assign_role', (v_can_org OR v_can_brand OR v_can_hotel OR v_can_dept),
    'can_assign_individual', (v_can_org OR v_can_brand OR v_can_hotel OR v_can_dept),
    'authorized_brand_ids', CASE WHEN v_can_org THEN NULL ELSE v_brand_ids END,
    'authorized_hotel_ids', CASE WHEN v_can_org THEN NULL ELSE v_hotel_ids END,
    'authorized_dept_ids', CASE WHEN v_can_org THEN NULL ELSE v_dept_ids END,
    'primary_role', v_primary_role,
    'primary_hotel_id', v_primary_hotel_id,
    'primary_department_id', v_primary_dept_id
  );
END;
$function$
;

CREATE OR REPLACE FUNCTION public.get_comment_replies(p_parent_id uuid)
 RETURNS TABLE(id uuid, document_id uuid, parent_id uuid, user_id uuid, user_name text, user_avatar text, content text, is_resolved boolean, created_at timestamp with time zone, updated_at timestamp with time zone)
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
    RETURN QUERY
    SELECT
        c.id,
        c.document_id,
        c.parent_id,
        c.user_id,
        p.full_name AS user_name,
        p.avatar_url AS user_avatar,
        c.content,
        c.is_resolved,
        c.created_at,
        c.updated_at
    FROM document_comments c
    JOIN profiles p ON c.user_id = p.id
    WHERE c.parent_id = p_parent_id
    ORDER BY c.created_at ASC;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.get_course_analytics()
 RETURNS TABLE(module_id uuid, title text, status text, category text, enrolled_count bigint, completed_count bigint, in_progress_count bigint, completion_rate numeric, avg_progress numeric, avg_time_seconds numeric, avg_score numeric, quiz_pass_rate numeric, last_activity_at timestamp with time zone)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
    WITH scope AS (SELECT public.learning_manager_org_ids() AS orgs),
    prog AS (
        SELECT
            p.training_id AS module_id,
            count(*)                                                   AS enrolled_count,
            count(*) FILTER (WHERE p.status = 'completed')             AS completed_count,
            count(*) FILTER (WHERE p.status = 'in_progress')           AS in_progress_count,
            round(100.0 * count(*) FILTER (WHERE p.status = 'completed') / nullif(count(*), 0), 1) AS completion_rate,
            round(avg(coalesce(p.progress_percentage, 0))::numeric, 1) AS avg_progress,
            round(avg(nullif(p.time_spent_seconds, 0))::numeric, 0)    AS avg_time_seconds,
            round(avg(coalesce(p.score_percentage, p.quiz_score))::numeric, 1) AS avg_score,
            max(coalesce(p.last_activity_at, p.last_accessed_at, p.completed_at)) AS last_activity_at
          FROM public.training_progress p, scope
         WHERE p.is_deleted = false
           AND p.organization_id = ANY (scope.orgs)
           AND coalesce(p.lp_content_type, 'module') = 'module'
         GROUP BY p.training_id
    ),
    -- Quiz sessions are recorded per quiz; attribute them to the module whose
    -- quiz block links that quiz.
    quiz AS (
        SELECT
            b.training_module_id AS module_id,
            round(100.0 * count(*) FILTER (WHERE s.passed IS TRUE)
                  / nullif(count(*) FILTER (WHERE s.completed_at IS NOT NULL), 0), 1) AS quiz_pass_rate
          FROM public.unified_quiz_sessions s
          JOIN public.training_content_blocks_v b
            ON b.type = 'quiz' AND NOT b.is_deleted
           AND public._safe_uuid(b.content_data ->> 'quiz_id') = s.quiz_entity_id
          CROSS JOIN scope
         WHERE s.quiz_type = 'learning_quiz'
           AND s.organization_id = ANY (scope.orgs)
         GROUP BY b.training_module_id
    )
    SELECT
        tm.id,
        tm.title,
        tm.status,
        tm.category,
        coalesce(prog.enrolled_count, 0),
        coalesce(prog.completed_count, 0),
        coalesce(prog.in_progress_count, 0),
        coalesce(prog.completion_rate, 0),
        coalesce(prog.avg_progress, 0),
        prog.avg_time_seconds,
        prog.avg_score,
        quiz.quiz_pass_rate,
        prog.last_activity_at
      FROM public.training_modules tm
      CROSS JOIN scope
      LEFT JOIN prog ON prog.module_id = tm.id
      LEFT JOIN quiz ON quiz.module_id = tm.id
     WHERE tm.is_deleted = false
       AND tm.organization_id = ANY (scope.orgs)
     ORDER BY coalesce(prog.enrolled_count, 0) DESC, tm.title;
$function$
;

CREATE OR REPLACE FUNCTION public.get_course_source_documents(p_training_module_id uuid)
 RETURNS TABLE(id uuid, document_id uuid, relationship text, is_primary boolean, original_filename text, file_type text, file_size bigint, attached_by uuid, attached_at timestamp with time zone, doc_title text, doc_visibility text, doc_file_url text, doc_content_type text, caller_can_access boolean)
 LANGUAGE sql
 STABLE
 SET search_path TO ''
AS $function$
  SELECT csd.id, csd.document_id, csd.relationship, csd.is_primary,
    csd.original_filename, csd.file_type, csd.file_size, csd.attached_by, csd.attached_at,
    d.title, d.visibility::text, d.file_url, d.content_type, (d.id IS NOT NULL) AS caller_can_access
  FROM public.course_source_documents csd
  LEFT JOIN public.documents d ON d.id = csd.document_id
  WHERE csd.training_module_id = p_training_module_id
  ORDER BY csd.is_primary DESC, csd.attached_at ASC;
$function$
;

CREATE OR REPLACE FUNCTION public.get_daily_active_users(days_ago integer DEFAULT 30)
 RETURNS TABLE(date date, active_users bigint)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_orgs uuid[] := public.learning_manager_org_ids();
BEGIN
  IF cardinality(v_orgs) = 0 THEN RETURN; END IF;
  RETURN QUERY
  SELECT g::date AS date,
         count(DISTINCT ae.user_id) AS active_users
    FROM generate_series(current_date - GREATEST(days_ago - 1, 0), current_date, interval '1 day') g
    LEFT JOIN public.analytics_events ae
      ON ae."timestamp"::date = g::date AND ae.organization_id = ANY (v_orgs)
   GROUP BY g::date
   ORDER BY g::date;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.get_daily_challenge_question_ids(p_count integer DEFAULT 3)
 RETURNS TABLE(id uuid)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
    WITH my_attempts AS (
        SELECT
            question_id,
            bool_or(is_correct) AS ever_correct,
            max(created_at) AS last_attempt_at
        FROM public.unified_question_attempts
        WHERE user_id = auth.uid()
        GROUP BY question_id
    )
    SELECT q.id
    FROM public.unified_questions q
    LEFT JOIN my_attempts a ON a.question_id = q.id
    WHERE auth.uid() IS NOT NULL
      AND q.status = 'published'
      AND q.question_type NOT IN ('ordering', 'matching')
      AND (COALESCE(q.is_master_template, false) OR public.org_visible(q.organization_id))
      AND NOT EXISTS (
          SELECT 1 FROM public.unified_quiz_questions uqq
            JOIN public.learning_quizzes lq ON lq.id = uqq.quiz_id
           WHERE uqq.question_id = q.id AND NOT COALESCE(lq.is_deleted, false))
    ORDER BY
        CASE
            WHEN a.question_id IS NULL THEN 0
            WHEN a.ever_correct IS NOT TRUE THEN 1
            WHEN a.last_attempt_at < now() - interval '14 days' THEN 2
            ELSE 3
        END,
        md5(q.id::text || COALESCE(auth.uid()::text, '') || to_char(now(), 'YYYY-MM-DD')),
        q.id
    LIMIT LEAST(GREATEST(COALESCE(p_count, 3), 1), 20);
$function$
;

CREATE OR REPLACE FUNCTION public.get_department_skill_matrix(p_department_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_org uuid; v jsonb;
BEGIN
  SELECT organization_id INTO v_org FROM public.departments WHERE id = p_department_id;
  IF v_org IS NULL OR NOT (public.org_visible(v_org) AND public.is_tenant_content_editor(v_org)) THEN
    RAISE EXCEPTION 'Not authorized' USING ERRCODE = '42501';
  END IF;

  SELECT jsonb_build_object(
    'department_id', p_department_id,
    'competencies', COALESCE((
      SELECT jsonb_agg(DISTINCT jsonb_build_object('id', c.id, 'name', c.name, 'required_level', r.required_level))
      FROM public.role_competency_requirements r
      JOIN public.competencies c ON c.id = r.competency_id
      WHERE r.organization_id = v_org
        AND (r.department_id = p_department_id OR r.department_id IS NULL)
    ), '[]'::jsonb),
    'members', COALESCE((
      SELECT jsonb_agg(jsonb_build_object(
        'user_id', m.user_id, 'name', p.full_name, 'role', m.role::text,
        'levels', (
          SELECT COALESCE(jsonb_object_agg(uc.competency_id, uc.current_level), '{}'::jsonb)
          FROM public.user_competencies uc WHERE uc.user_id = m.user_id
        )
      ))
      FROM public.organization_memberships m
      JOIN public.profiles p ON p.id = m.user_id
      WHERE m.department_id = p_department_id AND m.is_active = true
    ), '[]'::jsonb)
  ) INTO v;
  RETURN v;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.get_direct_reports(p_manager_id uuid)
 RETURNS TABLE(id uuid, full_name text, job_title text, email text)
 LANGUAGE sql
 STABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
  SELECT p.id, p.full_name, p.job_title, p.email
  FROM profiles p
  WHERE p.reporting_to = p_manager_id
    AND p.is_active = true
  ORDER BY p.full_name;
$function$
;

CREATE OR REPLACE FUNCTION public.get_document_comments_thread(p_document_id uuid)
 RETURNS TABLE(id uuid, document_id uuid, parent_id uuid, user_id uuid, user_name text, user_avatar text, content text, is_resolved boolean, is_pinned boolean, created_at timestamp with time zone, updated_at timestamp with time zone, reply_count bigint)
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
    RETURN QUERY
    SELECT
        c.id,
        c.document_id,
        c.parent_id,
        c.user_id,
        p.full_name AS user_name,
        p.avatar_url AS user_avatar,
        c.content,
        c.is_resolved,
        c.is_pinned,
        c.created_at,
        c.updated_at,
        (SELECT COUNT(*) FROM document_comments replies WHERE replies.parent_id = c.id) AS reply_count
    FROM document_comments c
    JOIN profiles p ON c.user_id = p.id
    WHERE c.document_id = p_document_id
    AND c.parent_id IS NULL
    ORDER BY
        c.is_pinned DESC,
        c.created_at DESC;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.get_document_viewers_by_department(p_document_id uuid)
 RETURNS TABLE(department_name text, count bigint)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT COALESCE(d.name,'Unknown'), COUNT(DISTINCT se.actor_id)
  FROM public.system_events se
  LEFT JOIN public.organization_memberships ud ON ud.user_id = se.actor_id AND ud.is_active = true
  LEFT JOIN public.departments d ON d.id = ud.department_id
  WHERE se.event_type = 'doc_view'
    AND se.entity_id = p_document_id
    AND EXISTS (
      SELECT 1 FROM public.documents doc
      WHERE doc.id = p_document_id
        AND (
          doc.created_by = (select auth.uid())
          OR doc.owner_id = (select auth.uid())
          OR public.is_hr_or_admin((select auth.uid()))
        )
    )
  GROUP BY d.name
  ORDER BY count DESC
  LIMIT 20;
$function$
;

CREATE OR REPLACE FUNCTION public.get_email_runtime_config()
 RETURNS jsonb
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public', 'vault'
AS $function$
  SELECT jsonb_build_object(
    'resend_api_key', (
      SELECT decrypted_secret
      FROM vault.decrypted_secrets
      WHERE name = 'RESEND_API_KEY'
      LIMIT 1
    ),
    'app_base_url', (
      SELECT decrypted_secret
      FROM vault.decrypted_secrets
      WHERE name = 'APP_BASE_URL'
      LIMIT 1
    ),
    'email_from_name', (
      SELECT decrypted_secret
      FROM vault.decrypted_secrets
      WHERE name = 'EMAIL_FROM_NAME'
      LIMIT 1
    ),
    'email_from_address', (
      SELECT decrypted_secret
      FROM vault.decrypted_secrets
      WHERE name = 'EMAIL_FROM_ADDRESS'
      LIMIT 1
    )
  );
$function$
;

CREATE OR REPLACE FUNCTION public.get_employee_directory(p_search text DEFAULT NULL::text, p_property_id uuid DEFAULT NULL::uuid, p_department_id uuid DEFAULT NULL::uuid, p_role app_role DEFAULT NULL::app_role, p_management_level text DEFAULT 'all'::text, p_sort text DEFAULT 'name_asc'::text, p_include_inactive boolean DEFAULT false)
 RETURNS TABLE(id uuid, full_name text, avatar_url text, job_title text, work_email text, phone_extension text, bio text, joining_date date, is_active boolean, staff_id text, manager_id uuid, manager_name text, manager_title text, primary_property_id uuid, primary_property_name text, primary_department_id uuid, primary_department_name text, property_ids uuid[], property_names text[], department_ids uuid[], department_names text[], roles app_role[], management_level text, updated_at timestamp with time zone)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
WITH scoped_profiles AS (
  SELECT
    p.id, p.full_name, p.avatar_url, p.job_title, p.email, p.phone_extension, p.bio,
    p.hire_date, p.is_active, p.staff_id, p.reporting_to, p.updated_at
  FROM public.profiles p
  WHERE COALESCE(p.is_deleted, false) = false
    AND public.can_view_employee_public_profile(p.id)
    AND (p_include_inactive OR p.is_active = true)
    AND (
      p_search IS NULL OR btrim(p_search) = '' OR
      p.full_name ILIKE '%' || p_search || '%' OR
      p.email ILIKE '%' || p_search || '%' OR
      COALESCE(p.job_title, '') ILIKE '%' || p_search || '%' OR
      COALESCE(p.staff_id, '') ILIKE '%' || p_search || '%'
    )
),
scope_data AS (
  SELECT
    sp.*,
    COALESCE(prop.property_ids, ARRAY[]::uuid[]) AS property_ids,
    COALESCE(prop.property_names, ARRAY[]::text[]) AS property_names,
    prop.primary_property_id,
    prop.primary_property_name,
    COALESCE(dept.department_ids, ARRAY[]::uuid[]) AS department_ids,
    COALESCE(dept.department_names, ARRAY[]::text[]) AS department_names,
    dept.primary_department_id,
    dept.primary_department_name,
    COALESCE(rl.roles, ARRAY[]::public.app_role[]) AS roles
  FROM scoped_profiles sp
  LEFT JOIN LATERAL (
    SELECT
      array_agg(om.hotel_id ORDER BY h.name NULLS LAST, om.hotel_id) AS property_ids,
      array_agg(COALESCE(h.name, 'Unknown Property') ORDER BY h.name NULLS LAST, om.hotel_id) AS property_names,
      (array_agg(om.hotel_id ORDER BY h.name NULLS LAST, om.hotel_id))[1] AS primary_property_id,
      (array_agg(COALESCE(h.name, 'Unknown Property') ORDER BY h.name NULLS LAST, om.hotel_id))[1] AS primary_property_name
    FROM public.organization_memberships om
    LEFT JOIN public.hotels h ON h.id = om.hotel_id
    WHERE om.user_id = sp.id AND om.is_active = true AND om.hotel_id IS NOT NULL
  ) prop ON true
  LEFT JOIN LATERAL (
    SELECT
      array_agg(om.department_id ORDER BY d.name NULLS LAST, om.department_id) AS department_ids,
      array_agg(COALESCE(d.name, 'Unknown Department') ORDER BY d.name NULLS LAST, om.department_id) AS department_names,
      (array_agg(om.department_id ORDER BY d.name NULLS LAST, om.department_id))[1] AS primary_department_id,
      (array_agg(COALESCE(d.name, 'Unknown Department') ORDER BY d.name NULLS LAST, om.department_id))[1] AS primary_department_name
    FROM public.organization_memberships om
    LEFT JOIN public.departments d ON d.id = om.department_id
    WHERE om.user_id = sp.id AND om.is_active = true AND om.department_id IS NOT NULL
  ) dept ON true
  LEFT JOIN LATERAL (
    SELECT array_agg(ur.role ORDER BY ur.role) AS roles
    FROM public.user_roles ur
    WHERE ur.user_id = sp.id
  ) rl ON true
),
enriched AS (
  SELECT
    sd.id, sd.full_name, sd.avatar_url, sd.job_title, sd.email::text AS work_email,
    sd.phone_extension, sd.bio, sd.hire_date AS joining_date, sd.is_active, sd.staff_id,
    sd.reporting_to AS manager_id, mgr.full_name AS manager_name, mgr.job_title AS manager_title,
    sd.primary_property_id, sd.primary_property_name, sd.primary_department_id, sd.primary_department_name,
    sd.property_ids, sd.property_names, sd.department_ids, sd.department_names, sd.roles,
    CASE
      WHEN (
        'corporate_admin'::public.app_role = ANY(sd.roles) OR
        'regional_admin'::public.app_role = ANY(sd.roles) OR
        'regional_hr'::public.app_role = ANY(sd.roles)
      ) THEN 'executive'
      WHEN (
        'property_manager'::public.app_role = ANY(sd.roles) OR
        'property_hr'::public.app_role = ANY(sd.roles) OR
        'department_head'::public.app_role = ANY(sd.roles) OR
        'manager'::public.app_role = ANY(sd.roles)
      ) THEN 'management'
      ELSE 'staff'
    END AS management_level,
    sd.updated_at
  FROM scope_data sd
  LEFT JOIN public.profiles mgr ON mgr.id = sd.reporting_to
)
SELECT
  e.id, e.full_name, e.avatar_url, e.job_title, e.work_email, e.phone_extension,
  e.bio, e.joining_date, e.is_active, e.staff_id, e.manager_id, e.manager_name, e.manager_title,
  e.primary_property_id, e.primary_property_name, e.primary_department_id, e.primary_department_name,
  e.property_ids, e.property_names, e.department_ids, e.department_names, e.roles, e.management_level, e.updated_at
FROM enriched e
WHERE (p_property_id IS NULL OR p_property_id = ANY(e.property_ids))
  AND (p_department_id IS NULL OR p_department_id = ANY(e.department_ids))
  AND (p_role IS NULL OR p_role = ANY(e.roles))
  AND (
    p_management_level IS NULL OR lower(p_management_level) = 'all' OR
    lower(p_management_level) = lower(e.management_level)
  )
ORDER BY
  CASE WHEN p_sort = 'name_desc' THEN e.full_name END DESC NULLS LAST,
  CASE WHEN p_sort = 'joining_date_asc' THEN e.joining_date END ASC NULLS LAST,
  CASE WHEN p_sort = 'joining_date_desc' THEN e.joining_date END DESC NULLS LAST,
  CASE WHEN p_sort = 'name_asc' OR p_sort IS NULL THEN e.full_name END ASC NULLS LAST,
  e.full_name ASC;
$function$
;

CREATE OR REPLACE FUNCTION public.get_employee_public_profile(p_profile_id uuid)
 RETURNS TABLE(id uuid, full_name text, avatar_url text, job_title text, work_email text, phone_extension text, bio text, joining_date date, is_active boolean, staff_id text, manager_id uuid, manager_name text, manager_title text, property_names text[], department_names text[], roles app_role[], skills text[], certifications text[], direct_reports jsonb, updated_at timestamp with time zone, is_edited boolean)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
WITH base AS (
  SELECT d.*
  FROM public.get_employee_directory(
    p_search := NULL,
    p_property_id := NULL,
    p_department_id := NULL,
    p_role := NULL,
    p_management_level := 'all',
    p_sort := 'name_asc',
    p_include_inactive := true
  ) d
  WHERE d.id = p_profile_id
  LIMIT 1
),
skill_data AS (
  SELECT COALESCE(array_agg(s_name ORDER BY s_name), ARRAY[]::text[]) AS skills
  FROM (
    SELECT DISTINCT s.name AS s_name
    FROM public.user_skills us
    JOIN public.skills s ON s.id = us.skill_id
    WHERE us.user_id = p_profile_id
      AND COALESCE(us.verified, true) = true
  ) sub
),
cert_data AS (
  SELECT COALESCE(array_agg(c_title ORDER BY c_date DESC NULLS LAST), ARRAY[]::text[]) AS certifications
  FROM (
    SELECT DISTINCT ON (COALESCE(c.title, c.certificate_type, 'Certificate'))
      COALESCE(c.title, c.certificate_type, 'Certificate') AS c_title,
      COALESCE(c.completion_date, c.created_at) AS c_date
    FROM public.certificates c
    WHERE c.user_id = p_profile_id
      AND COALESCE(c.status, 'active') <> 'revoked'
    ORDER BY COALESCE(c.title, c.certificate_type, 'Certificate'), COALESCE(c.completion_date, c.created_at) DESC NULLS LAST
  ) sub
),
direct_report_data AS (
  SELECT COALESCE(
    jsonb_agg(
      jsonb_build_object(
        'id', p.id,
        'full_name', p.full_name,
        'job_title', p.job_title,
        'avatar_url', p.avatar_url
      )
      ORDER BY p.full_name
    ),
    '[]'::jsonb
  ) AS direct_reports
  FROM public.profiles p
  WHERE p.reporting_to = p_profile_id
    AND COALESCE(p.is_deleted, false) = false
    AND public.can_view_employee_public_profile(p.id)
)
SELECT
  b.id,
  b.full_name,
  b.avatar_url,
  b.job_title,
  b.work_email,
  b.phone_extension,
  b.bio,
  b.joining_date,
  b.is_active,
  b.staff_id,
  b.manager_id,
  b.manager_name,
  b.manager_title,
  b.property_names,
  b.department_names,
  b.roles,
  sd.skills,
  cd.certifications,
  dr.direct_reports,
  b.updated_at,
  (b.updated_at > (SELECT p.created_at FROM public.profiles p WHERE p.id = b.id)) AS is_edited
FROM base b
CROSS JOIN skill_data sd
CROSS JOIN cert_data cd
CROSS JOIN direct_report_data dr;
$function$
;

CREATE OR REPLACE FUNCTION public.get_events_for_range(start_date text, end_date text, property_filter uuid DEFAULT NULL::uuid)
 RETURNS TABLE(id uuid, title text, description text, start_time timestamp with time zone, end_time timestamp with time zone, type text, color text, created_by uuid)
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE
  v_start_date timestamp with time zone;
  v_end_date timestamp with time zone;
BEGIN
  -- Cast input text to timestamp
  v_start_date := start_date::timestamp with time zone;
  v_end_date := end_date::timestamp with time zone;

  RETURN QUERY
  -- Calendar Events
  SELECT 
    e.id,
    e.title,
    e.description,
    e.start_date as start_time,
    e.end_date as end_time,
    'event' as type,
    '#6366f1' as color,
    e.created_by
  FROM events e
  WHERE e.start_date >= v_start_date 
    AND e.start_date <= v_end_date
    AND (property_filter IS NULL OR e.property_id = property_filter)
  
  UNION ALL
  
  -- Announcements (as events)
  SELECT 
    a.id,
    a.title,
    a.content as description,
    a.created_at as start_time,
    a.created_at + interval '1 hour' as end_time,
    'announcement' as type,
    '#3b82f6' as color, -- blue-500
    a.created_by
  FROM announcements a
  WHERE a.created_at >= v_start_date 
    AND a.created_at <= v_end_date;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.get_expiring_certificates(p_within_days integer DEFAULT 90, p_department_id uuid DEFAULT NULL::uuid, p_property_id uuid DEFAULT NULL::uuid)
 RETURNS TABLE(certificate_id uuid, user_id uuid, recipient_name text, title text, training_module_id uuid, expiry_date timestamp with time zone, days_until_expiry integer)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
    SELECT
        c.id, c.user_id, c.recipient_name::text, c.title::text, c.training_module_id, c.expiry_date,
        (extract(day FROM c.expiry_date - now()))::integer
      FROM public.certificates c
     WHERE c.organization_id = ANY (public.learning_manager_org_ids())
       AND c.status = 'active'
       AND c.expiry_date IS NOT NULL
       AND c.expiry_date <= now() + make_interval(days => p_within_days)
       AND public._learner_matches_filters(c.user_id, c.organization_id, p_department_id, p_property_id, false)
     ORDER BY c.expiry_date ASC;
$function$
;

CREATE OR REPLACE FUNCTION public.get_expiring_documents(p_days_ahead integer DEFAULT 30)
 RETURNS TABLE(document_id uuid, title text, expires_at timestamp with time zone, days_until_expiry integer, owner_email text, owner_name text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
    IF NOT public.is_hr_or_admin((select auth.uid())) THEN
        RAISE EXCEPTION 'Unauthorized: expiring-document reports require HR/admin access';
    END IF;

    RETURN QUERY
    SELECT
        d.id AS document_id,
        d.title,
        d.expires_at,
        EXTRACT(DAY FROM d.expires_at - NOW())::INTEGER AS days_until_expiry,
        p.email AS owner_email,
        p.full_name AS owner_name
    FROM documents d
    LEFT JOIN profiles p ON d.owner_id = p.id
    WHERE d.expires_at IS NOT NULL
    AND d.expires_at <= NOW() + (p_days_ahead || ' days')::INTERVAL
    AND d.expires_at >= NOW()
    AND d.is_archived = FALSE
    ORDER BY d.expires_at ASC;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.get_fifty_fifty_eliminations(p_question_id uuid)
 RETURNS uuid[]
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_user_id uuid := auth.uid();
  v_result uuid[];
BEGIN
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Authentication required';
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM public.unified_questions
     WHERE id = p_question_id AND status = 'published'
  ) THEN
    RAISE EXCEPTION 'Question not found or not published';
  END IF;

  SELECT array_agg(id) INTO v_result
  FROM (
    SELECT id
      FROM public.unified_question_options
     WHERE question_id = p_question_id
       AND is_correct = false
     ORDER BY random()
     LIMIT 2
  ) sub;

  RETURN COALESCE(v_result, ARRAY[]::uuid[]);
END;
$function$
;

CREATE OR REPLACE FUNCTION public.get_knowledge_analytics_search_terms(p_days integer DEFAULT 30, p_limit integer DEFAULT 50)
 RETURNS TABLE(term text, searches bigint, distinct_users bigint, avg_result_count numeric, zero_result_searches bigint, last_searched_at timestamp with time zone)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
    SELECT
        lower(btrim(s.query))                                   AS term,
        count(*)                                                AS searches,
        count(DISTINCT s.user_id)                               AS distinct_users,
        round(avg(s.result_count)::numeric, 1)                  AS avg_result_count,
        count(*) FILTER (WHERE s.result_count = 0)              AS zero_result_searches,
        max(s.created_at)                                       AS last_searched_at
      FROM public.search_logs s
     WHERE s.organization_id = ANY (public.learning_manager_org_ids())
       AND s.created_at >= now() - make_interval(days => greatest(p_days, 1))
       AND btrim(coalesce(s.query, '')) <> ''
     GROUP BY lower(btrim(s.query))
     ORDER BY searches DESC, last_searched_at DESC
     LIMIT greatest(p_limit, 1);
$function$
;

CREATE OR REPLACE FUNCTION public.get_knowledge_analytics_top_documents(p_days integer DEFAULT 30, p_limit integer DEFAULT 25)
 RETURNS TABLE(document_id uuid, title text, content_type text, lifetime_views integer, recent_views bigint, distinct_recent_viewers bigint, last_viewed_at timestamp with time zone)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
    WITH scope AS (SELECT public.learning_manager_org_ids() AS orgs),
    recent AS (
        SELECT
            v.document_id,
            count(*)                    AS recent_views,
            count(DISTINCT v.user_id)   AS distinct_recent_viewers,
            max(v.viewed_at)            AS last_viewed_at
          FROM public.document_views_v v
         WHERE v.viewed_at >= now() - make_interval(days => greatest(p_days, 1))
         GROUP BY v.document_id
    )
    SELECT
        d.id,
        d.title,
        d.content_type,
        coalesce(d.view_count, 0),
        coalesce(recent.recent_views, 0),
        coalesce(recent.distinct_recent_viewers, 0),
        recent.last_viewed_at
      FROM public.documents d
      CROSS JOIN scope
      LEFT JOIN recent ON recent.document_id = d.id
     WHERE d.is_deleted IS NOT TRUE
       AND d.organization_id = ANY (scope.orgs)
       AND (d.status = 'PUBLISHED' OR (d.status)::text = 'published')
     ORDER BY coalesce(recent.recent_views, 0) DESC, coalesce(d.view_count, 0) DESC
     LIMIT greatest(p_limit, 1);
$function$
;

CREATE OR REPLACE FUNCTION public.get_knowledge_analytics_zero_result_searches(p_days integer DEFAULT 90, p_limit integer DEFAULT 50)
 RETURNS TABLE(term text, searches bigint, distinct_users bigint, last_searched_at timestamp with time zone)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
    SELECT
        lower(btrim(s.query))       AS term,
        count(*)                    AS searches,
        count(DISTINCT s.user_id)   AS distinct_users,
        max(s.created_at)           AS last_searched_at
      FROM public.search_logs s
     WHERE s.organization_id = ANY (public.learning_manager_org_ids())
       AND s.result_count = 0
       AND s.created_at >= now() - make_interval(days => greatest(p_days, 1))
       AND btrim(coalesce(s.query, '')) <> ''
     GROUP BY lower(btrim(s.query))
     ORDER BY searches DESC, last_searched_at DESC
     LIMIT greatest(p_limit, 1);
$function$
;

CREATE OR REPLACE FUNCTION public.get_learner_analytics(p_user_id uuid DEFAULT NULL::uuid)
 RETURNS TABLE(user_id uuid, full_name text, job_title text, enrolled_count bigint, completed_count bigint, in_progress_count bigint, not_started_count bigint, avg_progress numeric, total_time_seconds bigint, quiz_sessions bigint, avg_quiz_score numeric, pass_rate numeric, last_activity_at timestamp with time zone)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
    WITH scope AS (SELECT public.learning_manager_org_ids() AS orgs),
    tp AS (
        SELECT
            p.user_id,
            count(*)                                                          AS enrolled_count,
            count(*) FILTER (WHERE p.status = 'completed')                    AS completed_count,
            count(*) FILTER (WHERE p.status = 'in_progress')                  AS in_progress_count,
            count(*) FILTER (WHERE p.status = 'not_started')                  AS not_started_count,
            round(avg(coalesce(p.progress_percentage, 0))::numeric, 1)        AS avg_progress,
            coalesce(sum(p.time_spent_seconds), 0)::bigint                    AS total_time_seconds,
            max(coalesce(p.last_activity_at, p.last_accessed_at, p.completed_at)) AS last_activity_at
          FROM public.training_progress p, scope
         WHERE p.is_deleted = false
           AND p.organization_id = ANY (scope.orgs)
           AND (p_user_id IS NULL OR p.user_id = p_user_id)
         GROUP BY p.user_id
    ),
    qz AS (
        SELECT
            s.user_id,
            count(*) FILTER (WHERE s.completed_at IS NOT NULL)                                 AS quiz_sessions,
            round(avg(s.score_percentage) FILTER (WHERE s.completed_at IS NOT NULL)::numeric, 1) AS avg_quiz_score,
            round(
                100.0 * count(*) FILTER (WHERE s.passed IS TRUE)
                / nullif(count(*) FILTER (WHERE s.completed_at IS NOT NULL), 0), 1
            )                                                                                  AS pass_rate
          FROM public.unified_quiz_sessions s, scope
         WHERE s.organization_id = ANY (scope.orgs)
           AND (p_user_id IS NULL OR s.user_id = p_user_id)
         GROUP BY s.user_id
    )
    SELECT
        pr.id,
        pr.full_name,
        pr.job_title,
        coalesce(tp.enrolled_count, 0),
        coalesce(tp.completed_count, 0),
        coalesce(tp.in_progress_count, 0),
        coalesce(tp.not_started_count, 0),
        coalesce(tp.avg_progress, 0),
        coalesce(tp.total_time_seconds, 0),
        coalesce(qz.quiz_sessions, 0),
        qz.avg_quiz_score,
        qz.pass_rate,
        tp.last_activity_at
      FROM public.profiles pr
      JOIN tp ON tp.user_id = pr.id
      LEFT JOIN qz ON qz.user_id = pr.id
     ORDER BY tp.last_activity_at DESC NULLS LAST, pr.full_name;
$function$
;

CREATE OR REPLACE FUNCTION public.get_learner_topic_breakdown(p_user_id uuid)
 RETURNS TABLE(training_module_id uuid, module_title text, attempts bigint, correct bigint, accuracy numeric)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
    SELECT
        q.training_module_id,
        coalesce(tm.title, 'Unlinked questions') AS module_title,
        count(*)                                 AS attempts,
        count(*) FILTER (WHERE a.is_correct)     AS correct,
        round(100.0 * count(*) FILTER (WHERE a.is_correct) / nullif(count(*), 0), 1) AS accuracy
      FROM public.unified_question_attempts a
      JOIN public.unified_questions q ON q.id = a.question_id
      LEFT JOIN public.training_modules tm ON tm.id = q.training_module_id
     WHERE a.user_id = p_user_id
       AND a.organization_id = ANY (public.learning_manager_org_ids())
     GROUP BY q.training_module_id, tm.title
     ORDER BY accuracy ASC NULLS LAST, attempts DESC;
$function$
;

CREATE OR REPLACE FUNCTION public.get_master_content_adoption(p_master_id uuid, p_content_type text DEFAULT 'course'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_rows jsonb;
BEGIN
  IF NOT (public.is_platform_operator() AND public.platform_operator_can('tenant.read')) THEN
    RAISE EXCEPTION 'Permission denied: platform operator with tenant.read required'
      USING ERRCODE = '42501';
  END IF;

  SELECT COALESCE(jsonb_agg(row_to_json(r) ORDER BY r.organization_name), '[]'::jsonb) INTO v_rows
  FROM (
    SELECT
      d.target_organization_id AS organization_id,
      o.name AS organization_name,
      o.lifecycle_status,
      d.target_content_id AS deployed_content_id,
      d.deployed_at,
      d.has_update_available,
      (SELECT count(*) FROM public.training_assignment_rules ar
         WHERE ar.training_module_id = d.target_content_id AND ar.is_active = true) AS assignment_rules,
      (SELECT count(*) FROM public.training_progress tp
         WHERE tp.training_id = d.target_content_id) AS learners,
      (SELECT count(*) FROM public.training_progress tp
         WHERE tp.training_id = d.target_content_id AND tp.status = 'in_progress') AS in_progress,
      (SELECT count(*) FROM public.training_progress tp
         WHERE tp.training_id = d.target_content_id AND tp.status = 'completed') AS completed,
      (SELECT round(avg(tp.score_percentage)::numeric, 1) FROM public.training_progress tp
         WHERE tp.training_id = d.target_content_id AND tp.status = 'completed'
           AND tp.score_percentage IS NOT NULL) AS avg_score,
      (SELECT count(*) FROM public.certificates c
         WHERE c.training_module_id = d.target_content_id AND c.certificate_type = 'training') AS certificates_issued
    FROM public.master_content_deployments d
    JOIN public.organizations o ON o.id = d.target_organization_id
    WHERE d.master_content_id = p_master_id AND d.content_type = p_content_type
  ) r;

  RETURN jsonb_build_object('master_id', p_master_id, 'tenants', v_rows);
END;
$function$
;

CREATE OR REPLACE FUNCTION public.get_media_asset_with_usage(p_media_asset_id uuid)
 RETURNS TABLE(id uuid, title text, description text, filename text, public_url text, media_type media_type, category media_category, file_size_bytes bigint, mime_type text, duration_seconds integer, thumbnail_url text, tags text[], usage_count integer, last_used_at timestamp with time zone, uploaded_by uuid, uploader_name text, property_id uuid, property_name text, is_public boolean, created_at timestamp with time zone, usages jsonb)
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
  RETURN QUERY
  SELECT ma.id, ma.title, ma.description, ma.filename, ma.public_url, ma.media_type, ma.category,
    ma.file_size_bytes, ma.mime_type, ma.duration_seconds, ma.thumbnail_url, ma.tags, ma.usage_count,
    ma.last_used_at, ma.uploaded_by, p.full_name as uploader_name, ma.property_id, h.name as property_name,
    ma.is_public, ma.created_at,
    COALESCE((SELECT jsonb_agg(jsonb_build_object('id', mau.id,'usage_type', mau.usage_type,
      'usage_entity_id', mau.usage_entity_id,'usage_entity_title', mau.usage_entity_title,'created_at', mau.created_at))
      FROM media_asset_usages mau WHERE mau.media_asset_id = ma.id), '[]'::jsonb) as usages
  FROM media_assets ma
  LEFT JOIN profiles p ON p.id = ma.uploaded_by
  LEFT JOIN hotels h ON h.id = ma.property_id
  WHERE ma.id = p_media_asset_id;
END;
$function$
;

