CREATE OR REPLACE FUNCTION public.get_or_create_user_wizard_progress(p_wizard_id text, p_org_id uuid DEFAULT NULL::uuid, p_current_role text DEFAULT 'learner'::text)
 RETURNS wizard_user_progress
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_user_id UUID := auth.uid();
  v_progress public.wizard_user_progress;
BEGIN
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Authentication required.';
  END IF;

  SELECT * INTO v_progress
  FROM public.wizard_user_progress
  WHERE user_id = v_user_id
    AND ((p_org_id IS NULL AND organization_id IS NULL) OR organization_id = p_org_id)
    AND wizard_id = p_wizard_id;

  IF NOT FOUND THEN
    INSERT INTO public.wizard_user_progress (
      user_id,
      organization_id,
      wizard_id,
      wizard_version,
      role_at_onboarding,
      status,
      current_step_index,
      completed_step_ids,
      skipped_step_ids,
      dismissed_contextual_tips,
      last_activity_at
    )
    VALUES (
      v_user_id,
      p_org_id,
      p_wizard_id,
      1,
      p_current_role,
      'not_started',
      0,
      '[]'::jsonb,
      '[]'::jsonb,
      '[]'::jsonb,
      now()
    )
    RETURNING * INTO v_progress;
  END IF;

  RETURN v_progress;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.get_org_hierarchy(p_root_user_id uuid DEFAULT NULL::uuid, p_property_id uuid DEFAULT NULL::uuid)
 RETURNS TABLE(id uuid, full_name text, job_title text, email text, reporting_to uuid, manager_name text, depth integer, path uuid[], path_names text[])
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_caller uuid := auth.uid();
  v_org_ids uuid[];
BEGIN
  IF v_caller IS NULL THEN
    RAISE EXCEPTION 'Authentication required.' USING ERRCODE = '42501';
  END IF;

  v_org_ids := public.current_user_organization_ids();

  IF v_org_ids IS NULL OR array_length(v_org_ids, 1) IS NULL THEN
    RAISE EXCEPTION 'Access denied: no active organization membership.' USING ERRCODE = '42501';
  END IF;

  RETURN QUERY
  WITH RECURSIVE hierarchy AS (
    SELECT
      p.id,
      p.full_name,
      p.job_title,
      p.email,
      p.reporting_to,
      NULL::TEXT as manager_name,
      0 as depth,
      ARRAY[p.id] as path,
      ARRAY[p.full_name] as path_names
    FROM profiles p
    JOIN organization_memberships om ON om.user_id = p.id AND om.is_active = true
    WHERE p.is_active = true
      AND om.organization_id = ANY(v_org_ids)
      AND (
        CASE
          WHEN p_root_user_id IS NOT NULL THEN p.id = p_root_user_id
          ELSE p.reporting_to IS NULL
        END
      )
      AND (p_property_id IS NULL OR om.hotel_id = p_property_id)

    UNION ALL

    SELECT
      p.id,
      p.full_name,
      p.job_title,
      p.email,
      p.reporting_to,
      h.full_name as manager_name,
      h.depth + 1,
      h.path || p.id,
      h.path_names || p.full_name
    FROM profiles p
    JOIN organization_memberships om2 ON om2.user_id = p.id AND om2.is_active = true
    JOIN hierarchy h ON p.reporting_to = h.id
    WHERE p.is_active = true
      AND om2.organization_id = ANY(v_org_ids)
      AND NOT p.id = ANY(h.path)
      AND h.depth < 20
  )
  SELECT DISTINCT ON (hierarchy.id)
    hierarchy.id,
    hierarchy.full_name,
    hierarchy.job_title,
    hierarchy.email,
    hierarchy.reporting_to,
    hierarchy.manager_name,
    hierarchy.depth,
    hierarchy.path,
    hierarchy.path_names
  FROM hierarchy
  ORDER BY hierarchy.id, hierarchy.depth;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.get_org_structure(p_org_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v jsonb;
BEGIN
  IF NOT (public.org_visible(p_org_id) OR public.is_platform_operator()) THEN
    RAISE EXCEPTION 'Not authorized' USING ERRCODE = '42501';
  END IF;
  SELECT jsonb_build_object(
    'organization', (SELECT jsonb_build_object('id', o.id, 'name', o.name, 'lifecycle_status', o.lifecycle_status) FROM public.organizations o WHERE o.id = p_org_id),
    'brands', COALESCE((SELECT jsonb_agg(jsonb_build_object('id', b.id, 'name', b.name) ORDER BY b.name)
                        FROM public.brands b WHERE b.organization_id = p_org_id AND b.is_deleted = false), '[]'::jsonb),
    'hotels', COALESCE((SELECT jsonb_agg(jsonb_build_object(
                          'id', h.id, 'name', h.name, 'brand_id', h.brand_id, 'city', h.city,
                          'departments', (SELECT COALESCE(jsonb_agg(jsonb_build_object('id', d.id, 'name', d.name) ORDER BY d.name), '[]'::jsonb)
                                          FROM public.departments d WHERE d.hotel_id = h.id AND d.is_active = true),
                          'member_count', (SELECT count(*) FROM public.organization_memberships om WHERE om.hotel_id = h.id AND om.is_active = true)
                        ) ORDER BY h.name)
                        FROM public.hotels h WHERE h.organization_id = p_org_id AND h.is_deleted = false), '[]'::jsonb)
  ) INTO v;
  RETURN v;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.get_organization_profile(p_org_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v jsonb;
BEGIN
  IF NOT (public.org_visible(p_org_id) OR public.is_platform_operator()) THEN
    RAISE EXCEPTION 'Not authorized for this organization' USING ERRCODE = '42501';
  END IF;
  SELECT jsonb_build_object(
    'organization', (SELECT to_jsonb(o) FROM public.organizations o WHERE o.id = p_org_id),
    'entitlements', public.effective_entitlements(p_org_id),
    'counts', jsonb_build_object(
      'brands', (SELECT count(*) FROM public.brands WHERE organization_id = p_org_id AND is_deleted = false),
      'hotels', (SELECT count(*) FROM public.hotels WHERE organization_id = p_org_id AND is_deleted = false),
      'departments', (SELECT count(*) FROM public.departments WHERE organization_id = p_org_id AND is_active = true),
      'members', (SELECT count(*) FROM public.organization_memberships WHERE organization_id = p_org_id AND is_active = true),
      'courses', (SELECT count(*) FROM public.training_modules WHERE organization_id = p_org_id AND is_deleted = false),
      'documents', (SELECT count(*) FROM public.documents WHERE organization_id = p_org_id AND is_deleted = false)
    ),
    'primary_contacts', (
      SELECT COALESCE(jsonb_agg(jsonb_build_object('user_id', om.user_id, 'name', p.full_name, 'email', p.email, 'role', om.role::text)), '[]'::jsonb)
        FROM public.organization_memberships om JOIN public.profiles p ON p.id = om.user_id
       WHERE om.organization_id = p_org_id AND om.is_active = true AND om.role IN ('organization_owner', 'organization_admin')
    ),
    'lifecycle_history', (
      SELECT COALESCE(jsonb_agg(jsonb_build_object('action', action, 'metadata', metadata, 'at', created_at) ORDER BY created_at DESC), '[]'::jsonb)
        FROM public.platform_audit_logs WHERE target_organization_id = p_org_id AND action = 'set_organization_status'
    )
  ) INTO v;
  RETURN v;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.get_platform_ai_operations()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'cron'
AS $function$
DECLARE
  v_result jsonb;
  v_total_jobs bigint := 0;
  v_failed_jobs bigint := 0;
  v_processing_jobs bigint := 0;
  v_completed_jobs bigint := 0;
  v_recent_jobs jsonb := '[]'::jsonb;
  v_cron_jobs jsonb := '[]'::jsonb;
  v_cron_runs jsonb := '[]'::jsonb;
BEGIN
  IF NOT public.is_platform_operator() THEN
    RAISE EXCEPTION 'Access denied: platform operator privilege required'
      USING ERRCODE = '42501';
  END IF;

  SELECT
    count(*),
    count(*) FILTER (WHERE status = 'failed'),
    count(*) FILTER (WHERE status IN ('processing', 'pending', 'generating')),
    count(*) FILTER (WHERE status = 'completed')
  INTO v_total_jobs, v_failed_jobs, v_processing_jobs, v_completed_jobs
  FROM public.course_generation_jobs;

  SELECT COALESCE(jsonb_agg(to_jsonb(j)), '[]'::jsonb)
  INTO v_recent_jobs
  FROM (
    SELECT id, mode, course_id, status, error_message, duration_ms, models_used, created_at, updated_at
    FROM public.course_generation_jobs
    ORDER BY created_at DESC
    LIMIT 20
  ) j;

  BEGIN
    SELECT COALESCE(jsonb_agg(to_jsonb(cj)), '[]'::jsonb)
    INTO v_cron_jobs
    FROM (
      SELECT jobid, jobname, schedule, active
      FROM cron.job
      ORDER BY jobid
    ) cj;

    -- One row per cron job: its own most recent run, not a shared top-15 across all jobs.
    SELECT COALESCE(jsonb_agg(to_jsonb(cr)), '[]'::jsonb)
    INTO v_cron_runs
    FROM (
      SELECT j.jobid, j.jobname, r.runid, r.status, r.return_message, r.start_time, r.end_time
      FROM cron.job j
      LEFT JOIN LATERAL (
        SELECT r2.runid, r2.status, r2.return_message, r2.start_time, r2.end_time
        FROM cron.job_run_details r2
        WHERE r2.jobid = j.jobid
        ORDER BY r2.start_time DESC
        LIMIT 1
      ) r ON true
      WHERE r.runid IS NOT NULL
    ) cr;
  EXCEPTION WHEN OTHERS THEN
    v_cron_jobs := '[]'::jsonb;
    v_cron_runs := '[]'::jsonb;
  END;

  v_result := jsonb_build_object(
    'summary', jsonb_build_object(
      'total_jobs', v_total_jobs,
      'failed_jobs', v_failed_jobs,
      'processing_jobs', v_processing_jobs,
      'completed_jobs', v_completed_jobs
    ),
    'recent_jobs', v_recent_jobs,
    'cron_jobs', v_cron_jobs,
    'recent_cron_runs', v_cron_runs
  );

  RETURN v_result;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.get_platform_feature_matrix()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_result jsonb;
BEGIN
  IF NOT public.is_platform_operator() THEN
    RAISE EXCEPTION 'Platform operators only' USING ERRCODE = '42501';
  END IF;
  SELECT jsonb_build_object(
    'flags', COALESCE((SELECT jsonb_agg(to_jsonb(f) ORDER BY f.category, f.label) FROM public.platform_feature_flags f), '[]'::jsonb),
    'organizations', COALESCE((
      SELECT jsonb_agg(jsonb_build_object(
        'id', o.id, 'name', o.name, 'lifecycle_status', o.lifecycle_status,
        'features', (
          SELECT jsonb_object_agg(f2.key, jsonb_build_object(
            'effective', public.feature_enabled(o.id, f2.key),
            'override', (SELECT ofo.enabled FROM public.organization_feature_overrides ofo
                         WHERE ofo.organization_id = o.id AND ofo.key = f2.key)
          ))
          FROM public.platform_feature_flags f2
        )
      ) ORDER BY o.name)
      FROM public.organizations o WHERE o.is_deleted = false
    ), '[]'::jsonb)
  ) INTO v_result;
  RETURN v_result;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.get_platform_global_search(p_query text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_orgs jsonb;
  v_hotels jsonb;
  v_depts jsonb;
  v_users jsonb;
  v_master_sops jsonb;
  v_master_courses jsonb;
  v_tenant_sops jsonb;
  v_tenant_courses jsonb;
  v_assessments jsonb;
  v_question_banks jsonb;
BEGIN
  IF NOT (public.is_platform_operator(auth.uid()) OR public.is_platform_user(auth.uid())) THEN
    RAISE EXCEPTION 'Access Denied: Platform global search requires platform operator privileges.';
  END IF;

  IF p_query IS NULL OR TRIM(p_query) = '' THEN
    RETURN jsonb_build_object(
      'organizations', '[]'::jsonb, 'hotels', '[]'::jsonb, 'departments', '[]'::jsonb, 'users', '[]'::jsonb,
      'master_sops', '[]'::jsonb, 'master_courses', '[]'::jsonb, 'tenant_sops', '[]'::jsonb,
      'tenant_courses', '[]'::jsonb, 'assessments', '[]'::jsonb, 'question_banks', '[]'::jsonb);
  END IF;

  SELECT COALESCE(JSONB_AGG(JSONB_BUILD_OBJECT(
    'id', o.id, 'name', o.name, 'slug', o.slug, 'lifecycle_status', o.lifecycle_status, 'is_active', o.is_active,
    'hotel_count', (SELECT COUNT(*) FROM public.hotels h WHERE h.organization_id = o.id AND h.is_deleted = false)
  )), '[]'::jsonb) INTO v_orgs
  FROM (SELECT * FROM public.organizations o
         WHERE (o.name ILIKE '%' || p_query || '%' OR o.slug ILIKE '%' || p_query || '%') AND o.is_deleted = false
         LIMIT 10) o;

  SELECT COALESCE(JSONB_AGG(JSONB_BUILD_OBJECT(
    'id', h.id, 'name', h.name, 'city', h.city, 'organization_id', h.organization_id,
    'organization_name', o.name, 'brand_id', h.brand_id, 'brand_name', b.name
  )), '[]'::jsonb) INTO v_hotels
  FROM (SELECT * FROM public.hotels h
         WHERE (h.name ILIKE '%' || p_query || '%' OR h.city ILIKE '%' || p_query || '%') AND h.is_deleted = false
         LIMIT 10) h
  JOIN public.organizations o ON o.id = h.organization_id
  LEFT JOIN public.brands b ON b.id = h.brand_id;

  SELECT COALESCE(JSONB_AGG(JSONB_BUILD_OBJECT(
    'id', d.id, 'name', d.name, 'hotel_id', d.hotel_id, 'hotel_name', h.name,
    'organization_id', d.organization_id, 'organization_name', o.name
  )), '[]'::jsonb) INTO v_depts
  FROM (SELECT * FROM public.departments d WHERE d.name ILIKE '%' || p_query || '%' AND d.is_deleted = false LIMIT 10) d
  JOIN public.organizations o ON o.id = d.organization_id
  LEFT JOIN public.hotels h ON h.id = d.hotel_id;

  SELECT COALESCE(JSONB_AGG(JSONB_BUILD_OBJECT(
    'id', p.id, 'full_name', p.full_name, 'email', p.email, 'role', p.role,
    'organization_id', om.organization_id, 'organization_name', o.name,
    'hotel_id', om.hotel_id, 'hotel_name', h.name,
    'department_id', om.department_id, 'department_name', dep.name
  )), '[]'::jsonb) INTO v_users
  FROM (SELECT * FROM public.profiles p
         WHERE (p.full_name ILIKE '%' || p_query || '%' OR p.email ILIKE '%' || p_query || '%')
         LIMIT 10) p
  LEFT JOIN LATERAL (
    SELECT om1.organization_id, om1.hotel_id, om1.department_id
      FROM public.organization_memberships om1
     WHERE om1.user_id = p.id AND om1.is_deleted = false
     ORDER BY om1.created_at ASC
     LIMIT 1
  ) om ON true
  LEFT JOIN public.organizations o ON o.id = om.organization_id
  LEFT JOIN public.hotels h ON h.id = om.hotel_id
  LEFT JOIN public.departments dep ON dep.id = om.department_id;

  SELECT COALESCE(JSONB_AGG(JSONB_BUILD_OBJECT(
    'id', doc.id, 'title', doc.title, 'document_number', doc.document_number,
    'category', doc.category, 'version', doc.current_version
  )), '[]'::jsonb) INTO v_master_sops
  FROM (SELECT * FROM public.documents doc
         WHERE doc.is_master_template = true AND doc.is_deleted = false
           AND (doc.title ILIKE '%' || p_query || '%' OR doc.description ILIKE '%' || p_query || '%')
         LIMIT 10) doc;

  SELECT COALESCE(JSONB_AGG(JSONB_BUILD_OBJECT(
    'id', tm.id, 'title', tm.title, 'category', tm.category, 'difficulty_level', tm.difficulty_level
  )), '[]'::jsonb) INTO v_master_courses
  FROM (SELECT * FROM public.training_modules tm
         WHERE tm.is_master_template = true AND tm.is_deleted = false
           AND (tm.title ILIKE '%' || p_query || '%' OR tm.description ILIKE '%' || p_query || '%')
         LIMIT 10) tm;

  SELECT COALESCE(JSONB_AGG(JSONB_BUILD_OBJECT(
    'id', doc.id, 'title', doc.title, 'document_number', doc.document_number,
    'organization_id', doc.organization_id, 'organization_name', o.name
  )), '[]'::jsonb) INTO v_tenant_sops
  FROM (SELECT * FROM public.documents doc
         WHERE (doc.is_master_template = false OR doc.is_master_template IS NULL) AND doc.is_deleted = false
           AND (doc.title ILIKE '%' || p_query || '%' OR doc.description ILIKE '%' || p_query || '%')
         LIMIT 10) doc
  JOIN public.organizations o ON o.id = doc.organization_id;

  SELECT COALESCE(JSONB_AGG(JSONB_BUILD_OBJECT(
    'id', tm.id, 'title', tm.title, 'category', tm.category,
    'organization_id', tm.organization_id, 'organization_name', o.name
  )), '[]'::jsonb) INTO v_tenant_courses
  FROM (SELECT * FROM public.training_modules tm
         WHERE (tm.is_master_template = false OR tm.is_master_template IS NULL) AND tm.is_deleted = false
           AND (tm.title ILIKE '%' || p_query || '%' OR tm.description ILIKE '%' || p_query || '%')
         LIMIT 10) tm
  JOIN public.organizations o ON o.id = tm.organization_id;

  SELECT COALESCE(JSONB_AGG(JSONB_BUILD_OBJECT(
    'id', q.id, 'title', q.title, 'passing_score', q.passing_score_percentage,
    'organization_id', q.organization_id, 'organization_name', o.name
  )), '[]'::jsonb) INTO v_assessments
  FROM (SELECT * FROM public.learning_quizzes q
         WHERE NOT COALESCE(q.is_deleted, false)
           AND (q.title ILIKE '%' || p_query || '%' OR q.description ILIKE '%' || p_query || '%')
         LIMIT 10) q
  LEFT JOIN public.organizations o ON o.id = q.organization_id;

  SELECT COALESCE(JSONB_AGG(JSONB_BUILD_OBJECT(
    'id', qb.id, 'name', qb.name, 'organization_id', qb.organization_id, 'organization_name', o.name
  )), '[]'::jsonb) INTO v_question_banks
  FROM (SELECT * FROM public.question_banks qb
         WHERE (qb.name ILIKE '%' || p_query || '%' OR qb.description ILIKE '%' || p_query || '%')
         LIMIT 10) qb
  LEFT JOIN public.organizations o ON o.id = qb.organization_id;

  RETURN JSONB_BUILD_OBJECT(
    'organizations', v_orgs, 'hotels', v_hotels, 'departments', v_depts, 'users', v_users,
    'master_sops', v_master_sops, 'master_courses', v_master_courses,
    'tenant_sops', v_tenant_sops, 'tenant_courses', v_tenant_courses,
    'assessments', v_assessments, 'question_banks', v_question_banks
  );
END;
$function$
;

CREATE OR REPLACE FUNCTION public.get_platform_operations_summary()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_caller_id uuid := auth.uid();
  v_is_platform boolean;
  v_active_jobs bigint := 0;
  v_completed_jobs bigint := 0;
  v_failed_jobs bigint := 0;
  v_total_jobs bigint := 0;
  v_recent_jobs jsonb;
BEGIN
  SELECT public.is_platform_user(v_caller_id) INTO v_is_platform;
  IF NOT v_is_platform THEN
    RAISE EXCEPTION 'Access Denied: Platform operations summary requires platform privileges.';
  END IF;

  SELECT 
    COUNT(*) FILTER (WHERE status IN ('pending', 'processing', 'in_progress', 'queued')),
    COUNT(*) FILTER (WHERE status IN ('completed', 'success')),
    COUNT(*) FILTER (WHERE status IN ('failed', 'error')),
    COUNT(*)
  INTO v_active_jobs, v_completed_jobs, v_failed_jobs, v_total_jobs
  FROM public.course_generation_jobs;

  SELECT COALESCE(JSONB_AGG(JSONB_BUILD_OBJECT(
    'id', j.id,
    'mode', j.mode,
    'status', j.status,
    'created_at', j.created_at,
    'updated_at', j.updated_at,
    'duration_ms', j.duration_ms,
    'error_message', j.error_message,
    'models_used', j.models_used
  ) ORDER BY j.created_at DESC), '[]'::jsonb)
  INTO v_recent_jobs
  FROM (
    SELECT * FROM public.course_generation_jobs
    ORDER BY created_at DESC
    LIMIT 25
  ) j;

  RETURN JSONB_BUILD_OBJECT(
    'active_jobs', v_active_jobs,
    'completed_jobs', v_completed_jobs,
    'failed_jobs', v_failed_jobs,
    'total_jobs', v_total_jobs,
    'recent_jobs', v_recent_jobs
  );
END;
$function$
;

CREATE OR REPLACE FUNCTION public.get_platform_usage_analytics()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_result jsonb;
BEGIN
  IF NOT (public.is_platform_operator() AND public.platform_operator_can('tenant.read')) THEN
    RAISE EXCEPTION 'Platform operators only' USING ERRCODE = '42501';
  END IF;

  SELECT jsonb_build_object(
    'generated_at', now(),
    'totals', jsonb_build_object(
      'organizations',   (SELECT count(*) FROM public.organizations WHERE is_deleted = false),
      'hotels',          (SELECT count(*) FROM public.hotels WHERE is_deleted = false),
      'members',         (SELECT count(*) FROM public.organization_memberships WHERE is_active = true),
      'courses',         (SELECT count(*) FROM public.training_modules WHERE is_deleted = false),
      'documents',       (SELECT count(*) FROM public.documents WHERE is_deleted = false),
      'ai_jobs_total',   (SELECT count(*) FROM public.course_generation_jobs),
      'ai_jobs_failed',  (SELECT count(*) FROM public.course_generation_jobs WHERE status IN ('failed', 'error')),
      'deployments',     (SELECT count(*) FROM public.master_content_deployments),
      'training_records',(SELECT count(*) FROM public.training_progress WHERE is_deleted = false),
      'training_completed',(SELECT count(*) FROM public.training_progress WHERE is_deleted = false AND (status = 'completed' OR passed = true))
    ),
    'ai_credits', jsonb_build_object(
      'used',  COALESCE((SELECT sum(ai_credits_used_this_month) FROM public.organizations WHERE is_deleted = false), 0),
      'limit', COALESCE((SELECT sum(max_ai_credits_monthly)    FROM public.organizations WHERE is_deleted = false), 0)
    ),
    'organizations', COALESCE((
      SELECT jsonb_agg(jsonb_build_object(
        'id', o.id,
        'name', o.name,
        'lifecycle_status', o.lifecycle_status,
        'plan', (SELECT sp.name FROM public.subscriptions s JOIN public.subscription_plans sp ON sp.id = s.plan_id
                 WHERE s.organization_id = o.id AND s.status = 'active'
                 ORDER BY s.current_period_end DESC NULLS LAST LIMIT 1),
        'hotels', (SELECT count(*) FROM public.hotels h WHERE h.organization_id = o.id AND h.is_deleted = false),
        'members', (SELECT count(*) FROM public.organization_memberships om WHERE om.organization_id = o.id AND om.is_active = true),
        'courses', (SELECT count(*) FROM public.training_modules m WHERE m.organization_id = o.id AND m.is_deleted = false),
        'documents', (SELECT count(*) FROM public.documents d WHERE d.organization_id = o.id AND d.is_deleted = false),
        'ai_credits_used', o.ai_credits_used_this_month,
        'ai_credits_limit', o.max_ai_credits_monthly,
        'max_hotels', o.max_hotels,
        'max_learners', o.max_learners,
        'training_completion_pct', (
          SELECT CASE WHEN count(*) = 0 THEN NULL
                 ELSE round(100.0 * count(*) FILTER (WHERE tp.status = 'completed' OR tp.passed = true) / count(*), 1) END
            FROM public.training_progress tp
           WHERE tp.organization_id = o.id AND tp.is_deleted = false
        )
      ) ORDER BY o.name)
      FROM public.organizations o WHERE o.is_deleted = false
    ), '[]'::jsonb)
  ) INTO v_result;
  RETURN v_result;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.get_platform_user_directory(p_search text DEFAULT NULL::text, p_org_id uuid DEFAULT NULL::uuid, p_role text DEFAULT NULL::text, p_limit integer DEFAULT 50, p_offset integer DEFAULT 0)
 RETURNS TABLE(id uuid, email text, full_name text, avatar_url text, is_active boolean, is_platform_user boolean, platform_role text, primary_organization_id uuid, primary_organization_name text, membership_count bigint, memberships jsonb, created_at timestamp with time zone, total_count bigint)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_caller_id uuid := auth.uid();
BEGIN
  IF NOT public.is_platform_operator(v_caller_id) THEN
    RAISE EXCEPTION 'Access Denied: platform operators only' USING ERRCODE = '42501';
  END IF;

  RETURN QUERY
  WITH user_memberships AS (
    SELECT om.user_id, om.organization_id, o.name AS org_name, om.role::text AS role,
           om.hotel_id, h.name AS hotel_name, om.department_id, d.name AS dept_name,
           om.is_active AS member_active, om.is_primary
    FROM public.organization_memberships om
    LEFT JOIN public.organizations o ON o.id = om.organization_id
    LEFT JOIN public.hotels h ON h.id = om.hotel_id
    LEFT JOIN public.departments d ON d.id = om.department_id
  ),
  aggregated_memberships AS (
    SELECT um.user_id, COUNT(um.organization_id) AS m_count,
      (ARRAY_AGG(um.organization_id ORDER BY um.is_primary DESC))[1] AS first_org_id,
      (ARRAY_AGG(um.org_name ORDER BY um.is_primary DESC))[1] AS first_org_name,
      JSONB_AGG(JSONB_BUILD_OBJECT('organization_id', um.organization_id, 'organization_name', um.org_name,
        'role', um.role, 'hotel_id', um.hotel_id, 'hotel_name', um.hotel_name, 'department_id', um.department_id,
        'department_name', um.dept_name, 'is_active', um.member_active)) AS memberships_json
    FROM user_memberships um GROUP BY um.user_id
  ),
  op_roles AS (
    SELECT pra.platform_user_id AS user_id,
      (ARRAY_AGG(pra.platform_role::text ORDER BY CASE pra.platform_role::text
        WHEN 'system_owner' THEN 0 WHEN 'platform_admin' THEN 1
        WHEN 'platform_training_manager' THEN 2 WHEN 'platform_knowledge_manager' THEN 3
        WHEN 'platform_operations' THEN 4 WHEN 'platform_support' THEN 5
        ELSE 6 END))[1] AS top_role
    FROM public.platform_role_assignments pra
    JOIN public.platform_users pu ON pu.user_id = pra.platform_user_id AND pu.is_active
    WHERE pra.revoked_at IS NULL
    GROUP BY pra.platform_user_id
  ),
  filtered AS (
    SELECT p.id, p.email::text AS email, p.full_name::text AS full_name, p.avatar_url::text AS avatar_url,
      COALESCE(p.is_active, true) AS is_active,
      public.is_platform_operator(p.id) AS is_platform_user,
      opr.top_role AS platform_role,
      am.first_org_id AS primary_organization_id, am.first_org_name AS primary_organization_name,
      COALESCE(am.m_count, 0) AS membership_count, COALESCE(am.memberships_json, '[]'::jsonb) AS memberships,
      p.created_at
    FROM public.profiles p
    LEFT JOIN aggregated_memberships am ON am.user_id = p.id
    LEFT JOIN op_roles opr ON opr.user_id = p.id
    WHERE (p_search IS NULL OR p.full_name ILIKE '%'||p_search||'%' OR p.email ILIKE '%'||p_search||'%')
      AND (p_org_id IS NULL OR EXISTS (SELECT 1 FROM public.organization_memberships om2 WHERE om2.user_id = p.id AND om2.organization_id = p_org_id))
      AND (p_role IS NULL
           OR EXISTS (SELECT 1 FROM public.organization_memberships om3 WHERE om3.user_id = p.id AND om3.role::text = p_role)
           OR EXISTS (SELECT 1 FROM public.user_roles ur2 WHERE ur2.user_id = p.id AND ur2.role::text = p_role)
           OR opr.top_role = p_role)
  )
  SELECT f.id, f.email, f.full_name, f.avatar_url, f.is_active, f.is_platform_user, f.platform_role,
    f.primary_organization_id, f.primary_organization_name, f.membership_count, f.memberships, f.created_at,
    COUNT(*) OVER() AS total_count
  FROM filtered f
  ORDER BY f.created_at DESC
  LIMIT p_limit OFFSET p_offset;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.get_questions_for_attempt(p_question_ids uuid[])
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_result jsonb;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Authentication required';
  END IF;

  SELECT jsonb_agg(
    jsonb_build_object(
      'id', q.id,
      'question_text', q.question_text,
      'question_text_ar', q.question_text_ar,
      'question_type', q.question_type,
      'difficulty', q.difficulty,
      'points', q.points,
      'estimated_time_seconds', q.estimated_time_seconds,
      'tags', q.tags,
      'hint', q.hint,
      'hint_ar', q.hint_ar,
      'linked_sop_id', q.linked_sop_id,
      'linked_sop', (
        SELECT jsonb_build_object('id', d.id, 'title', d.title)
        FROM public.documents d
        WHERE d.id = q.linked_sop_id
      ),
      'options', (
        SELECT jsonb_agg(
          jsonb_build_object(
            'id', o.id,
            'option_text', o.option_text,
            'option_text_ar', o.option_text_ar,
            'display_order', o.display_order
          ) ORDER BY o.display_order
        )
        FROM public.unified_question_options o
        WHERE o.question_id = q.id
      )
    )
  ) INTO v_result
  FROM public.unified_questions q
  WHERE q.id = ANY(p_question_ids)
    AND q.status = 'published'
    AND (COALESCE(q.is_master_template, false) OR public.org_visible(q.organization_id));

  RETURN COALESCE(v_result, '[]'::jsonb);
END;
$function$
;

CREATE OR REPLACE FUNCTION public.get_questions_pass_rates(p_question_ids uuid[])
 RETURNS TABLE(question_id uuid, total_attempts integer, correct_attempts integer, accuracy_rate numeric)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
    SELECT
        a.question_id,
        count(*)::integer AS total_attempts,
        count(*) FILTER (WHERE a.is_correct)::integer AS correct_attempts,
        ROUND(100.0 * count(*) FILTER (WHERE a.is_correct) / NULLIF(count(*), 0), 1) AS accuracy_rate
      FROM public.unified_question_attempts a
     WHERE a.question_id = ANY (p_question_ids)
       AND a.organization_id = ANY (public.content_editor_org_ids() || public.learning_manager_org_ids())
     GROUP BY a.question_id;
$function$
;

CREATE OR REPLACE FUNCTION public.get_quiz_for_player(p_quiz_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_quiz public.learning_quizzes%ROWTYPE;
  v_questions jsonb;
  v_is_editor boolean;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Authentication required';
  END IF;

  SELECT * INTO v_quiz FROM public.learning_quizzes WHERE id = p_quiz_id AND is_deleted = false;
  IF NOT FOUND OR NOT (public.org_visible(v_quiz.organization_id) OR public.is_platform_super_admin()) THEN
    RAISE EXCEPTION 'Quiz not found';
  END IF;

  v_is_editor := public.is_platform_super_admin()
    OR (v_quiz.organization_id IS NOT NULL AND public.is_tenant_content_editor(v_quiz.organization_id));

  IF v_quiz.status <> 'published' AND v_quiz.created_by IS DISTINCT FROM auth.uid() AND NOT v_is_editor THEN
    RAISE EXCEPTION 'Quiz is not available';
  END IF;

  SELECT jsonb_agg(
    jsonb_build_object(
      'question_id', uq.question_id,
      'display_order', uq.display_order,
      'points_override', uq.points_override,
      'question', jsonb_build_object(
        'id', q.id,
        'question_text', q.question_text,
        'question_text_ar', q.question_text_ar,
        'question_type', q.question_type,
        'points', q.points,
        'hint', q.hint,
        'hint_ar', q.hint_ar,
        'options', (
          SELECT jsonb_agg(
            jsonb_build_object(
              'id', o.id,
              'option_text', o.option_text,
              'option_text_ar', o.option_text_ar,
              'display_order', o.display_order
            ) ORDER BY o.display_order
          )
          FROM public.unified_question_options o
          WHERE o.question_id = q.id
        )
      )
    )
  ) INTO v_questions
  FROM public.unified_quiz_questions uq
  JOIN public.unified_questions q ON q.id = uq.question_id AND q.status = 'published'
  WHERE uq.quiz_id = p_quiz_id;

  RETURN jsonb_build_object(
    'id', v_quiz.id,
    'title', v_quiz.title,
    'description', v_quiz.description,
    'time_limit_minutes', v_quiz.time_limit_minutes,
    'passing_score_percentage', v_quiz.passing_score_percentage,
    'max_attempts', v_quiz.max_attempts,
    'randomize_questions', v_quiz.randomize_questions,
    'randomize_answers', v_quiz.randomize_answers,
    'show_feedback_during', v_quiz.show_feedback_during,
    'questions', COALESCE(v_questions, '[]'::jsonb)
  );
END;
$function$
;

CREATE OR REPLACE FUNCTION public.get_reporting_chain(p_employee_id uuid)
 RETURNS TABLE(id uuid, full_name text, job_title text, level integer)
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
  RETURN QUERY
  WITH RECURSIVE chain AS (
    SELECT p.id, p.full_name, p.job_title, p.reporting_to, 0 as level
    FROM profiles p
    WHERE p.id = p_employee_id
    
    UNION ALL
    
    SELECT p.id, p.full_name, p.job_title, p.reporting_to, c.level + 1
    FROM profiles p
    JOIN chain c ON p.id = c.reporting_to
    WHERE c.level < 20
  )
  SELECT chain.id, chain.full_name, chain.job_title, chain.level
  FROM chain
  ORDER BY chain.level;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.get_role_priority(_role app_role)
 RETURNS integer
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
  SELECT CASE _role::text
    WHEN 'administrator'     THEN 0
    WHEN 'super_admin'       THEN 0
    WHEN 'corporate_admin'   THEN 1
    WHEN 'training_manager'  THEN 2
    WHEN 'regional_admin'    THEN 2
    WHEN 'knowledge_manager' THEN 3
    WHEN 'regional_hr'       THEN 3
    WHEN 'property_manager'  THEN 4
    WHEN 'property_hr'       THEN 5
    WHEN 'department_head'   THEN 6
    WHEN 'author'            THEN 6
    WHEN 'manager'           THEN 7
    WHEN 'learner'           THEN 8
    WHEN 'staff'             THEN 8
    ELSE 999
  END;
$function$
;

CREATE OR REPLACE FUNCTION public.get_search_metrics(days_ago integer DEFAULT 30)
 RETURNS TABLE(total_searches bigint, zero_results_count bigint, avg_results_count numeric, top_queries json)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_orgs uuid[] := public.learning_manager_org_ids();
BEGIN
  IF cardinality(v_orgs) = 0 THEN
    RETURN QUERY SELECT 0::bigint, 0::bigint, 0::numeric, '[]'::json; RETURN;
  END IF;
  RETURN QUERY
  WITH s AS (
    SELECT properties->>'query' AS q, NULLIF(properties->>'results_count','')::int AS rc
      FROM public.analytics_events
     WHERE organization_id = ANY (v_orgs)
       AND (event_name ILIKE 'search%' OR category = 'search')
       AND "timestamp" > now() - (days_ago || ' days')::interval
  )
  SELECT count(*)::bigint,
         count(*) FILTER (WHERE rc = 0)::bigint,
         COALESCE(round(avg(rc), 2), 0)::numeric,
         COALESCE((SELECT json_agg(json_build_object('query', q, 'count', c))
                     FROM (SELECT q, count(*) c FROM s WHERE q IS NOT NULL GROUP BY q ORDER BY count(*) DESC LIMIT 10) t),
                  '[]'::json)
    FROM s;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.get_secure_document_url(document_id uuid)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  doc record;
BEGIN
  SELECT d.id, d.file_url
  INTO doc
  FROM public.documents d
  WHERE d.id = document_id
  LIMIT 1;

  IF doc IS NULL THEN
    RAISE EXCEPTION 'Document not found';
  END IF;

  IF NOT public.can_view_document(document_id) THEN
    RAISE EXCEPTION 'Not authorized to access this document';
  END IF;

  -- Content-only knowledge base documents may have no file. Return NULL.
  IF doc.file_url IS NULL OR length(trim(doc.file_url)) = 0 THEN
    RETURN NULL;
  END IF;

  -- If this points at our own private 'documents' bucket, strip it down to the bare
  -- object path so the caller can generate a signed URL.
  IF doc.file_url ~* '/object/(public|sign|authenticated)/documents/' THEN
    RETURN regexp_replace(doc.file_url, '^.*/object/(public|sign|authenticated)/documents/', '');
  END IF;

  -- Anything else (a genuine external URL, or an already-bare path) is returned as-is.
  RETURN doc.file_url;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.get_secure_document_version_url(p_version_id uuid)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v record;
BEGIN
  SELECT dv.file_url, dv.document_id, dv.created_by INTO v
  FROM document_versions dv WHERE dv.id = p_version_id LIMIT 1;
  IF NOT FOUND THEN RAISE EXCEPTION 'Document version not found'; END IF;
  IF v.file_url IS NULL THEN RAISE EXCEPTION 'Document version file not available'; END IF;
  IF v.created_by <> (SELECT auth.uid())
     AND NOT can_view_document(v.document_id)
     AND NOT (has_role_optimized('corporate_admin') OR has_role_optimized('regional_admin') OR has_role_optimized('regional_hr')) THEN
    RAISE EXCEPTION 'Not authorized to access this document version';
  END IF;
  RETURN v.file_url;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.get_secure_media_url(p_media_asset_id uuid, p_expiry_seconds integer DEFAULT 3600)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_caller uuid := auth.uid();
  v_storage_path text;
  v_storage_bucket text;
  v_organization_id uuid;
  v_uploaded_by uuid;
  v_is_public boolean;
BEGIN
  IF v_caller IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  SELECT storage_path, storage_bucket, organization_id, uploaded_by, COALESCE(is_public, false)
  INTO v_storage_path, v_storage_bucket, v_organization_id, v_uploaded_by, v_is_public
  FROM public.media_assets
  WHERE id = p_media_asset_id;

  IF v_storage_path IS NULL THEN
    RETURN NULL;
  END IF;

  IF NOT (
    v_is_public
    OR v_uploaded_by = v_caller
    OR public.is_platform_operator()
    OR (v_organization_id IS NOT NULL AND public.org_visible(v_organization_id))
  ) THEN
    RAISE EXCEPTION 'Access denied: not authorized to view this media asset' USING ERRCODE = '42501';
  END IF;

  IF v_storage_path LIKE 'http%' THEN
    RETURN v_storage_path;
  END IF;

  RETURN json_build_object(
    'bucket', COALESCE(v_storage_bucket, 'media'),
    'path', v_storage_path
  )::text;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.get_secure_report_run_url(p_run_id uuid)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v record;
BEGIN
  SELECT rr.output_path, rr.triggered_by INTO v
  FROM report_runs rr WHERE rr.id = p_run_id LIMIT 1;
  IF NOT FOUND THEN RAISE EXCEPTION 'Report run not found'; END IF;
  IF v.output_path IS NULL THEN RAISE EXCEPTION 'Report file not available'; END IF;
  IF v.triggered_by IS DISTINCT FROM (SELECT auth.uid())
     AND NOT (has_role_optimized('corporate_admin') OR has_role_optimized('regional_admin') OR has_role_optimized('regional_hr')) THEN
    RAISE EXCEPTION 'Not authorized to access this report';
  END IF;
  RETURN v.output_path;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.get_setting(p_org_id uuid, p_key text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_val jsonb;
BEGIN
  -- 1. Try tenant-specific override first if p_org_id is provided
  IF p_org_id IS NOT NULL THEN
    SELECT value INTO v_val
    FROM public.system_settings
    WHERE organization_id = p_org_id AND key = p_key;

    IF v_val IS NOT NULL THEN
      RETURN v_val;
    END IF;
  END IF;

  -- 2. Fall back to global platform default
  SELECT value INTO v_val
  FROM public.system_settings
  WHERE organization_id IS NULL AND key = p_key;

  RETURN v_val;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.get_sidebar_counts(p_user_id uuid, p_role text DEFAULT NULL::text, p_property_ids uuid[] DEFAULT NULL::uuid[], p_department_ids uuid[] DEFAULT NULL::uuid[], p_current_property_id uuid DEFAULT NULL::uuid)
 RETURNS json
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_caller uuid := (SELECT auth.uid());
    v_unread_notifications integer := 0;
    v_pending_training integer := 0;
BEGIN
    IF v_caller IS NULL THEN
        RETURN json_build_object(
            'unreadNotifications', 0,
            'pendingApprovals', 0,
            'overdueTasks', 0,
            'unreadMessages', 0,
            'pendingTraining', 0,
            'activeGoals', 0
        );
    END IF;

    IF p_user_id IS DISTINCT FROM v_caller AND NOT public.is_hr_or_admin(v_caller) THEN
        RAISE EXCEPTION 'Unauthorized: can only view your own sidebar counts';
    END IF;

    -- Unread notifications count
    BEGIN
        SELECT count(*)::integer INTO v_unread_notifications
        FROM notifications
        WHERE user_id = p_user_id AND read_at IS NULL;
    EXCEPTION WHEN OTHERS THEN
        v_unread_notifications := 0;
    END;

    -- Pending training count
    BEGIN
        SELECT count(*)::integer INTO v_pending_training
        FROM training_progress tp
        WHERE tp.user_id = p_user_id
          AND (tp.status IS NULL OR tp.status NOT IN ('completed', 'passed'));
    EXCEPTION WHEN OTHERS THEN
        v_pending_training := 0;
    END;

    RETURN json_build_object(
        'unreadNotifications', COALESCE(v_unread_notifications, 0),
        'pendingApprovals', 0,
        'overdueTasks', 0,
        'unreadMessages', 0,
        'pendingTraining', COALESCE(v_pending_training, 0),
        'activeGoals', 0
    );
END;
$function$
;

CREATE OR REPLACE FUNCTION public.get_skills_matrix(p_department_id uuid DEFAULT NULL::uuid, p_property_id uuid DEFAULT NULL::uuid, p_my_team_only boolean DEFAULT false)
 RETURNS TABLE(user_id uuid, user_name text, department_name text, skill_id uuid, skill_name text, skill_category text, proficiency_level integer, verified boolean, has_skill boolean)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
    WITH scope AS (
        SELECT CASE WHEN p_my_team_only
                    THEN public.learning_manager_org_ids() || public.learning_team_org_ids()
                    ELSE public.learning_manager_org_ids() END AS orgs
    ),
    scoped_users AS (
        SELECT DISTINCT ON (p.id)
            p.id, p.full_name, d.name AS department_name
          FROM public.profiles p
          JOIN public.organization_memberships ud ON ud.user_id = p.id AND ud.is_active = true
          CROSS JOIN scope
          LEFT JOIN public.departments d ON d.id = ud.department_id
         WHERE p.is_active = true
           AND ud.organization_id = ANY (scope.orgs)
           AND public._learner_matches_filters(p.id, ud.organization_id, p_department_id, p_property_id, p_my_team_only)
         ORDER BY p.id, ud.department_id NULLS LAST
    )
    SELECT
        su.id, su.full_name, su.department_name, s.id, s.name, s.category,
        us.proficiency_level, us.verified, (us.id IS NOT NULL) AS has_skill
      FROM scoped_users su
      CROSS JOIN public.skills s
      CROSS JOIN scope
      LEFT JOIN public.user_skills us
        ON us.user_id = su.id AND us.skill_id = s.id AND us.organization_id = ANY (scope.orgs)
     ORDER BY su.full_name, s.category, s.name;
$function$
;

CREATE OR REPLACE FUNCTION public.get_task_completion_metrics(p_user_id uuid DEFAULT NULL::uuid, p_start_date timestamp with time zone DEFAULT NULL::timestamp with time zone, p_end_date timestamp with time zone DEFAULT NULL::timestamp with time zone)
 RETURNS TABLE(total_tasks bigint, completed_tasks bigint, pending_tasks bigint, in_progress_tasks bigint, completion_rate numeric, avg_completion_time_hours numeric)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth', 'extensions'
AS $function$
BEGIN
    IF p_user_id IS NULL THEN
        IF NOT public.is_hr_or_admin((select auth.uid())) THEN
            RAISE EXCEPTION 'Unauthorized: organization-wide task metrics require HR/admin access';
        END IF;
    ELSIF p_user_id IS DISTINCT FROM (select auth.uid()) AND NOT public.is_hr_or_admin((select auth.uid())) THEN
        RAISE EXCEPTION 'Unauthorized: can only view your own task metrics';
    END IF;

    RETURN QUERY
    SELECT
        COUNT(*) as total_tasks,
        COUNT(*) FILTER (WHERE status = 'completed') as completed_tasks,
        COUNT(*) FILTER (WHERE status = 'pending') as pending_tasks,
        COUNT(*) FILTER (WHERE status = 'in_progress') as in_progress_tasks,
        CASE
            WHEN COUNT(*) > 0 THEN
                ROUND(COUNT(*) FILTER (WHERE status = 'completed')::DECIMAL / COUNT(*) * 100, 2)
            ELSE 0
        END as completion_rate,
        CASE
            WHEN COUNT(*) FILTER (WHERE status = 'completed') > 0 THEN
                ROUND(AVG(EXTRACT(EPOCH FROM (completed_at - created_at))/3600), 2)
            ELSE NULL
        END as avg_completion_time_hours
    FROM tasks
    WHERE
        (p_user_id IS NULL OR created_by = p_user_id)
        AND (p_start_date IS NULL OR created_at >= p_start_date)
        AND (p_end_date IS NULL OR created_at <= p_end_date)
        AND is_deleted = false;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.get_task_stats(user_id_param uuid)
 RETURNS TABLE(total_tasks bigint, todo_tasks bigint, in_progress_tasks bigint, review_tasks bigint, completed_tasks bigint, overdue_tasks bigint)
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public'
AS $function$
BEGIN
  RETURN QUERY
  SELECT
    COUNT(*)::BIGINT AS total_tasks,
    COUNT(*) FILTER (WHERE status = 'todo')::BIGINT AS todo_tasks,
    COUNT(*) FILTER (WHERE status = 'in_progress')::BIGINT AS in_progress_tasks,
    COUNT(*) FILTER (WHERE status = 'review')::BIGINT AS review_tasks,
    COUNT(*) FILTER (WHERE status = 'completed')::BIGINT AS completed_tasks,
    COUNT(*) FILTER (WHERE status != 'completed' AND status != 'cancelled' AND due_date < CURRENT_DATE)::BIGINT AS overdue_tasks
  FROM tasks
  WHERE assigned_to_id = user_id_param OR created_by_id = user_id_param;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.get_tenant_email_context(p_org_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_org public.organizations%ROWTYPE;
  v_primary text;
  v_secondary text;
  v_accent text;
  v_logo text;
  v_name text;
  v_name_ar text;
  v_sender_name text;
  v_reply_to text;
  v_support_email text;
  v_website text;
  v_footer text;
  v_footer_ar text;
BEGIN
  IF p_org_id IS NOT NULL
     AND NOT (public._p7_is_service_context() OR public.is_platform_super_admin() OR public.org_visible(p_org_id)) THEN
    RAISE EXCEPTION 'not authorized for organization %', p_org_id USING ERRCODE = '42501';
  END IF;

  IF p_org_id IS NOT NULL THEN
    SELECT * INTO v_org FROM public.organizations WHERE id = p_org_id;
  END IF;

  -- Resolve brand colors with fallback
  v_primary := COALESCE(v_org.brand_colors->>'primary', '#0B1C3E');
  v_secondary := COALESCE(v_org.brand_colors->>'secondary', '#1a365d');
  v_accent := COALESCE(v_org.brand_colors->>'accent', '#D4AF37');

  -- Resolve logo with fallback
  v_logo := COALESCE(NULLIF(v_org.logo_url, ''), '/altus-emblem-icon.png');

  -- Resolve organization names
  v_name := COALESCE(NULLIF(v_org.name, ''), 'Altus Connect');
  v_name_ar := COALESCE(NULLIF(v_org.name_ar, ''), v_name);

  -- Resolve sender identity
  v_sender_name := COALESCE(NULLIF(v_org.email_sender_name, ''), v_name);
  v_support_email := COALESCE(NULLIF(v_org.support_email, ''), NULLIF(v_org.billing_email, ''), 'support@altus-advisory.com');
  v_reply_to := COALESCE(NULLIF(v_org.email_reply_to, ''), v_support_email);
  v_website := COALESCE(NULLIF(v_org.website_url, ''), 'https://www.altus-advisory.com');

  -- Resolve footers
  v_footer := COALESCE(NULLIF(v_org.email_footer_text, ''), 'All rights reserved.');
  v_footer_ar := COALESCE(NULLIF(v_org.email_footer_text_ar, ''), 'جميع الحقوق محفوظة.');

  RETURN jsonb_build_object(
    'org_id', v_org.id,
    'org_name', v_name,
    'org_name_ar', v_name_ar,
    'logo_url', v_logo,
    'brand_colors', jsonb_build_object(
      'primary', v_primary,
      'secondary', v_secondary,
      'accent', v_accent
    ),
    'sender_name', v_sender_name,
    'from_email', 'notifications@phg-connect.com',
    'reply_to', v_reply_to,
    'support_email', v_support_email,
    'website_url', v_website,
    'footer_text', v_footer,
    'footer_text_ar', v_footer_ar,
    'is_custom_branded', (v_org.id IS NOT NULL)
  );
END;
$function$
;

CREATE OR REPLACE FUNCTION public.get_top_events(limit_count integer DEFAULT 10)
 RETURNS TABLE(event_name text, count bigint)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_orgs uuid[] := public.learning_manager_org_ids();
BEGIN
  IF cardinality(v_orgs) = 0 THEN RETURN; END IF;
  RETURN QUERY
  SELECT ae.event_name, count(*) AS count
    FROM public.analytics_events ae
   WHERE ae.organization_id = ANY (v_orgs)
   GROUP BY ae.event_name
   ORDER BY count(*) DESC
   LIMIT GREATEST(limit_count, 1);
END;
$function$
;

CREATE OR REPLACE FUNCTION public.get_training_analytics_summary(p_start_date timestamp with time zone DEFAULT NULL::timestamp with time zone, p_department_id uuid DEFAULT NULL::uuid, p_property_id uuid DEFAULT NULL::uuid, p_my_team_only boolean DEFAULT false)
 RETURNS TABLE(total_assignees bigint, completed_count bigint, in_progress_count bigint, not_started_count bigint, overdue_count bigint, completion_rate numeric, average_score numeric)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
    WITH scope AS (
        SELECT CASE WHEN p_my_team_only
                    THEN public.learning_manager_org_ids() || public.learning_team_org_ids()
                    ELSE public.learning_manager_org_ids() END AS orgs
    ),
    targets AS (
        SELECT t.user_id, t.training_id, min(t.due_date) AS due_date
          FROM scope, public._module_assignment_targets(scope.orgs) t
         WHERE (p_start_date IS NULL OR t.rule_created_at >= p_start_date)
           AND public._learner_matches_filters(t.user_id, t.organization_id, p_department_id, p_property_id, p_my_team_only)
         GROUP BY t.user_id, t.training_id
    ),
    joined AS (
        SELECT dt.user_id, dt.training_id, dt.due_date, tp.status, tp.score_percentage
          FROM targets dt
          LEFT JOIN public.training_progress tp
            ON tp.user_id = dt.user_id
           AND tp.training_id = dt.training_id
           AND tp.lp_content_type = 'module'
           AND tp.is_deleted = false
    )
    SELECT
        count(*) AS total_assignees,
        count(*) FILTER (WHERE status = 'completed') AS completed_count,
        count(*) FILTER (WHERE status = 'in_progress') AS in_progress_count,
        count(*) FILTER (WHERE status IS NULL OR status = 'not_started') AS not_started_count,
        count(*) FILTER (WHERE status IS DISTINCT FROM 'completed' AND due_date IS NOT NULL AND due_date < now()) AS overdue_count,
        CASE WHEN count(*) > 0
            THEN round(100.0 * count(*) FILTER (WHERE status = 'completed') / count(*), 1)
            ELSE 0
        END AS completion_rate,
        (SELECT round(avg(j2.score_percentage), 1) FROM joined j2 WHERE j2.status = 'completed' AND j2.score_percentage IS NOT NULL) AS average_score
    FROM joined;
$function$
;

CREATE OR REPLACE FUNCTION public.get_training_completion_trend(p_weeks integer DEFAULT 12, p_department_id uuid DEFAULT NULL::uuid, p_property_id uuid DEFAULT NULL::uuid, p_my_team_only boolean DEFAULT false)
 RETURNS TABLE(week_start date, completed_count bigint)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
    WITH scope AS (
        SELECT CASE WHEN p_my_team_only
                    THEN public.learning_manager_org_ids() || public.learning_team_org_ids()
                    ELSE public.learning_manager_org_ids() END AS orgs
    ),
    weeks AS (
        SELECT generate_series(
            date_trunc('week', now() - ((p_weeks - 1) || ' weeks')::interval),
            date_trunc('week', now()),
            interval '1 week'
        )::date AS week_start
    ),
    scoped_completions AS (
        SELECT tp.completed_at
          FROM public.training_progress tp, scope
         WHERE tp.organization_id = ANY (scope.orgs)
           AND tp.lp_content_type = 'module'
           AND tp.is_deleted = false
           AND tp.status = 'completed'
           AND tp.completed_at >= now() - (p_weeks || ' weeks')::interval
           AND public._learner_matches_filters(tp.user_id, tp.organization_id, p_department_id, p_property_id, p_my_team_only)
    )
    SELECT w.week_start, count(sc.completed_at) AS completed_count
      FROM weeks w
      LEFT JOIN scoped_completions sc ON date_trunc('week', sc.completed_at)::date = w.week_start
     GROUP BY w.week_start
     ORDER BY w.week_start;
$function$
;

CREATE OR REPLACE FUNCTION public.get_training_module_funnel(p_module_id uuid)
 RETURNS TABLE(block_id uuid, block_title text, block_type text, block_order integer, completed_count bigint, completion_rate numeric)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
    WITH allowed AS (
        SELECT EXISTS (
            SELECT 1 FROM public.training_modules m
             WHERE m.id = p_module_id
               AND m.organization_id = ANY (public.learning_manager_org_ids())) AS ok
    ),
    enrolled AS (
        SELECT count(*) AS total
          FROM public.training_progress tp
         WHERE tp.training_id = p_module_id
           AND tp.lp_content_type = 'module'
           AND tp.is_deleted = false
    )
    SELECT
        b.id,
        b.title,
        b.type,
        b."order",
        count(bp.user_id) AS completed_count,
        CASE WHEN (SELECT total FROM enrolled) > 0
            THEN round(100.0 * count(bp.user_id) / (SELECT total FROM enrolled), 1)
            ELSE 0
        END AS completion_rate
      FROM public.training_content_blocks_v b
      LEFT JOIN public.training_block_progress bp
        ON bp.block_id = b.id AND bp.completed_at IS NOT NULL
     WHERE b.training_module_id = p_module_id
       AND b.is_deleted = false
       AND (SELECT ok FROM allowed)
     GROUP BY b.id, b.title, b.type, b."order"
     ORDER BY b."order";
$function$
;

CREATE OR REPLACE FUNCTION public.get_training_module_performance(p_department_id uuid DEFAULT NULL::uuid, p_property_id uuid DEFAULT NULL::uuid, p_limit integer DEFAULT 10)
 RETURNS TABLE(module_id uuid, title text, assignee_count bigint, completed_count bigint, completion_rate numeric, average_score numeric)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
    WITH scope AS (SELECT public.learning_manager_org_ids() AS orgs),
    targets AS (
        SELECT DISTINCT t.user_id, t.training_id
          FROM scope, public._module_assignment_targets(scope.orgs) t
         WHERE public._learner_matches_filters(t.user_id, t.organization_id, p_department_id, p_property_id, false)
    ),
    joined AS (
        SELECT dt.user_id, dt.training_id, tp.status, tp.score_percentage
          FROM targets dt
          LEFT JOIN public.training_progress tp
            ON tp.user_id = dt.user_id AND tp.training_id = dt.training_id
           AND tp.lp_content_type = 'module' AND tp.is_deleted = false
    )
    SELECT
        m.id AS module_id, m.title,
        count(j.user_id) AS assignee_count,
        count(j.user_id) FILTER (WHERE j.status = 'completed') AS completed_count,
        CASE WHEN count(j.user_id) > 0
            THEN round(100.0 * count(j.user_id) FILTER (WHERE j.status = 'completed') / count(j.user_id), 1)
            ELSE 0
        END AS completion_rate,
        round(avg(j.score_percentage) FILTER (WHERE j.status = 'completed'), 1) AS average_score
      FROM public.training_modules m
      CROSS JOIN scope
      LEFT JOIN joined j ON j.training_id = m.id
     WHERE m.is_deleted = false
       AND m.organization_id = ANY (scope.orgs)
     GROUP BY m.id, m.title
     ORDER BY assignee_count DESC NULLS LAST
     LIMIT p_limit;
$function$
;

CREATE OR REPLACE FUNCTION public.get_training_module_related_resources(p_module_id uuid)
 RETURNS TABLE(resource_type text, resource_id uuid, title text, description text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
    RETURN QUERY
    SELECT 'document', d.id, d.title, d.description
      FROM documents d
      WHERE d.id IN (
        SELECT DISTINCT tb.linked_training_id
        FROM documents tb
        WHERE tb.content_type = 'training_block'
          AND tb.training_module_id = p_module_id
          AND tb.linked_training_id IS NOT NULL
      )
    UNION ALL
    SELECT 'quiz', lq.id, lq.title, lq.description
      FROM learning_quizzes lq WHERE lq.training_module_id = p_module_id
    UNION ALL
    SELECT 'question', kq.id, kq.question_text, kq.explanation
      FROM knowledge_questions kq WHERE kq.training_module_id = p_module_id;
END;
$function$
;

