CREATE OR REPLACE FUNCTION public.has_active_platform_session(p_org_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT EXISTS (
    SELECT 1 FROM public.platform_access_sessions
    WHERE admin_user_id = auth.uid()
      AND target_organization_id = p_org_id
      AND is_active = true
      AND (ended_at IS NULL OR ended_at > now())
      AND expires_at > now()
  );
$function$
;

CREATE OR REPLACE FUNCTION public.has_any_role(_user_id uuid, _roles app_role[])
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT EXISTS (
    SELECT 1
    FROM unnest(_roles) req
    WHERE public.has_role(_user_id, req)
  );
$function$
;

CREATE OR REPLACE FUNCTION public.has_profile_access(_admin_id uuid, _target_user_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT
    _admin_id = _target_user_id
    OR EXISTS (SELECT 1 FROM public.user_roles WHERE user_id = _admin_id AND role = 'super_admin')
    OR EXISTS (
      SELECT 1
      FROM public.organization_memberships ma
      JOIN public.organization_memberships mt ON mt.organization_id = ma.organization_id
      WHERE ma.user_id = _admin_id AND mt.user_id = _target_user_id
        AND ma.is_active = true AND mt.is_active = true
        AND ma.role IN ('organization_owner','organization_admin','hotel_admin')
    );
$function$
;

CREATE OR REPLACE FUNCTION public.has_property_access(_user_id uuid, _property_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT
    -- Platform operators always have access
    public.is_platform_operator()
    OR
    -- Legacy super_admin fallback, preserved from the original check
    EXISTS (SELECT 1 FROM public.user_roles WHERE user_id = _user_id AND role = 'super_admin')
    OR
    -- Org-wide admins see every hotel within their own organization
    EXISTS (
      SELECT 1 FROM public.organization_memberships om
      JOIN public.hotels h ON h.id = _property_id
      WHERE om.user_id = _user_id AND om.is_active = true
        AND om.role IN ('organization_owner', 'organization_admin')
        AND om.organization_id = h.organization_id
    )
    OR
    -- Direct hotel-scoped membership
    EXISTS (
      SELECT 1 FROM public.organization_memberships om
      WHERE om.user_id = _user_id AND om.is_active = true AND om.hotel_id = _property_id
    );
$function$
;

CREATE OR REPLACE FUNCTION public.has_role(_user_id uuid, _role app_role)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT EXISTS (
    SELECT 1 FROM public.user_roles
    WHERE user_id = _user_id
      AND role = ANY (public.roles_satisfying(_role))
  );
$function$
;

CREATE OR REPLACE FUNCTION public.has_role_optimized(check_role app_role)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT check_role = ANY(public.get_my_roles());
$function$
;

CREATE OR REPLACE FUNCTION public.has_tenant_access(record_org_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT record_org_id IS NOT NULL AND (
    public.has_active_platform_session(record_org_id)
    OR (record_org_id = ANY (public.current_user_organization_ids())
        AND public.org_is_operational(record_org_id))
  );
$function$
;

CREATE OR REPLACE FUNCTION public.hydrate_training_certificate_fields()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE
  v_progress_id uuid;
  v_module_id uuid;
  v_quiz_score integer;
  v_passing_score integer;
BEGIN
  IF NEW.certificate_type <> 'training' THEN
    RETURN NEW;
  END IF;

  IF NEW.training_progress_id IS NOT NULL AND NEW.training_module_id IS NULL THEN
    SELECT tp.training_id, tp.quiz_score
    INTO v_module_id, v_quiz_score
    FROM public.training_progress tp
    WHERE tp.id = NEW.training_progress_id
      AND coalesce(tp.is_deleted, false) = false
    LIMIT 1;

    IF v_module_id IS NOT NULL THEN
      NEW.training_module_id := v_module_id;
    END IF;
    IF NEW.score IS NULL AND v_quiz_score IS NOT NULL THEN
      NEW.score := v_quiz_score;
    END IF;
  END IF;

  IF NEW.training_progress_id IS NULL
     AND NEW.training_module_id IS NOT NULL
     AND NEW.user_id IS NOT NULL THEN
    SELECT public.resolve_training_certificate_progress(
      NEW.user_id,
      NEW.training_module_id,
      NEW.completion_date
    )
    INTO v_progress_id;

    IF v_progress_id IS NOT NULL THEN
      NEW.training_progress_id := v_progress_id;
    END IF;
  END IF;

  IF NEW.training_progress_id IS NOT NULL
     AND (NEW.score IS NULL OR NEW.training_module_id IS NULL) THEN
    SELECT tp.training_id, tp.quiz_score
    INTO v_module_id, v_quiz_score
    FROM public.training_progress tp
    WHERE tp.id = NEW.training_progress_id
      AND coalesce(tp.is_deleted, false) = false
    LIMIT 1;

    IF NEW.training_module_id IS NULL AND v_module_id IS NOT NULL THEN
      NEW.training_module_id := v_module_id;
    END IF;
    IF NEW.score IS NULL AND v_quiz_score IS NOT NULL THEN
      NEW.score := v_quiz_score;
    END IF;
  END IF;

  IF NEW.passing_score IS NULL AND NEW.training_module_id IS NOT NULL THEN
    SELECT tm.passing_score_percentage
    INTO v_passing_score
    FROM public.training_modules tm
    WHERE tm.id = NEW.training_module_id
    LIMIT 1;

    IF v_passing_score IS NOT NULL THEN
      NEW.passing_score := v_passing_score;
    END IF;
  END IF;

  RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.increment_article_view_count(doc_id uuid)
 RETURNS void
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  UPDATE public.documents SET view_count = COALESCE(view_count, 0) + 1 WHERE id = doc_id;
$function$
;

CREATE OR REPLACE FUNCTION public.increment_batch_email_counters(p_batch_id uuid, p_sent integer DEFAULT 0, p_failed integer DEFAULT 0)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  UPDATE public.notification_batches
  SET
    email_sent_count = email_sent_count + coalesce(p_sent, 0),
    email_failed_count = email_failed_count + coalesce(p_failed, 0),
    last_processed_at = now()
  WHERE id = p_batch_id;
END;
$function$
;

