CREATE OR REPLACE FUNCTION public.lock_account(p_email text, p_duration_minutes integer DEFAULT 30)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_profile_id uuid;
  v_capped_minutes integer := LEAST(GREATEST(p_duration_minutes, 1), 60);
BEGIN
    SELECT id INTO v_profile_id FROM public.profiles WHERE email = lower(p_email);
    IF FOUND THEN
        UPDATE public.profiles SET account_status = 'locked', locked_until = now() + (v_capped_minutes || ' minutes')::interval WHERE id = v_profile_id;
        INSERT INTO public.system_events (event_type, actor_id, entity_type, entity_id, metadata)
        VALUES ('security', v_profile_id, 'profile', v_profile_id,
            jsonb_build_object('security_event_type', 'account.locked', 'severity', 'warning',
                'email', p_email, 'duration_minutes', v_capped_minutes));
        RETURN true;
    END IF;
    RETURN false;
END; $function$
;

CREATE OR REPLACE FUNCTION public.log_audit_event()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
    actor_id uuid;
    changes jsonb;
    action_type text;
    record_id uuid;
    v_org_id uuid;
    v_json_data jsonb;
BEGIN
    actor_id := auth.uid();
    IF TG_OP = 'INSERT' THEN
        action_type := 'create'; 
        changes := to_jsonb(NEW); 
        record_id := NEW.id;
        v_json_data := to_jsonb(NEW);
    ELSIF TG_OP = 'UPDATE' THEN
        action_type := 'update'; 
        changes := jsonb_build_object('old', to_jsonb(OLD), 'new', to_jsonb(NEW)); 
        record_id := NEW.id;
        v_json_data := to_jsonb(NEW);
    ELSIF TG_OP = 'DELETE' THEN
        action_type := 'delete'; 
        changes := to_jsonb(OLD); 
        record_id := OLD.id;
        v_json_data := to_jsonb(OLD);
    END IF;

    -- 1. Try resolving from row itself
    IF v_json_data ? 'organization_id' AND (v_json_data->>'organization_id') ~ '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$' THEN
        v_org_id := (v_json_data->>'organization_id')::uuid;
    END IF;

    -- 2. Try resolving from actor's memberships
    IF v_org_id IS NULL AND actor_id IS NOT NULL THEN
        SELECT organization_id INTO v_org_id 
        FROM public.organization_memberships 
        WHERE user_id = actor_id AND is_active = true 
        ORDER BY is_primary DESC NULLS LAST, created_at ASC 
        LIMIT 1;
    END IF;

    -- 3. Try resolving from record's user_id if table has user_id
    IF v_org_id IS NULL AND v_json_data ? 'user_id' AND (v_json_data->>'user_id') ~ '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$' THEN
        SELECT organization_id INTO v_org_id 
        FROM public.organization_memberships 
        WHERE user_id = (v_json_data->>'user_id')::uuid AND is_active = true 
        ORDER BY is_primary DESC NULLS LAST, created_at ASC 
        LIMIT 1;
    END IF;

    -- 4. Fallback to default active organization
    IF v_org_id IS NULL THEN
        SELECT id INTO v_org_id 
        FROM public.organizations 
        WHERE is_active = true 
        ORDER BY created_at ASC 
        LIMIT 1;
    END IF;

    IF record_id IS NOT NULL AND v_org_id IS NOT NULL THEN
        INSERT INTO public.system_events (event_type, actor_id, entity_type, entity_id, organization_id, metadata)
        VALUES ('audit', actor_id, TG_TABLE_NAME, record_id, v_org_id, jsonb_build_object('action', action_type, 'details', changes));
    END IF;
    RETURN NULL;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.log_audit_event(p_action text, p_entity_type text, p_entity_id uuid, p_old_values jsonb DEFAULT NULL::jsonb, p_new_values jsonb DEFAULT NULL::jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN INSERT INTO public.system_events(event_type,actor_id,entity_type,entity_id,metadata) VALUES('audit',auth.uid(),p_entity_type,p_entity_id,jsonb_build_object('action',p_action,'details',jsonb_build_object('old',p_old_values,'new',p_new_values))); END; $function$
;

CREATE OR REPLACE FUNCTION public.log_audit_event_trigger()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_actor_id uuid := auth.uid();
    v_action text;
    v_changes jsonb;
    v_record_id uuid;
BEGIN
    IF TG_OP = 'INSERT' THEN
        v_action := 'create'; v_changes := to_jsonb(NEW); v_record_id := NEW.id;
    ELSIF TG_OP = 'UPDATE' THEN
        v_action := 'update'; v_changes := jsonb_build_object('old', to_jsonb(OLD), 'new', to_jsonb(NEW)); v_record_id := NEW.id;
    ELSIF TG_OP = 'DELETE' THEN
        v_action := 'delete'; v_changes := to_jsonb(OLD); v_record_id := OLD.id;
    END IF;
    IF v_record_id IS NOT NULL THEN
        INSERT INTO public.system_events (event_type, actor_id, entity_type, entity_id, metadata)
        VALUES ('audit', v_actor_id, TG_TABLE_NAME, v_record_id, jsonb_build_object('action', v_action, 'details', v_changes));
    END IF;
    RETURN NULL;
END; $function$
;

