      read_at = NEW.completed_at,
      completed = TRUE;
  END IF;
  
  RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.match_knowledge_chunks(p_query_embedding vector, p_query_text text DEFAULT NULL::text, p_match_count integer DEFAULT 8, p_min_similarity double precision DEFAULT 0.0, p_organization_id uuid DEFAULT NULL::uuid)
 RETURNS TABLE(id uuid, document_id uuid, article_id uuid, title text, section text, content text, similarity double precision, keyword_rank double precision)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public, extensions'
AS $function$
  SELECT
    kc.id,
    kc.document_id,
    kc.article_id,
    d.title,
    kc.section,
    kc.content,
    CASE
      WHEN kc.embedding IS NULL OR p_query_embedding IS NULL THEN 0.0
      ELSE 1 - (kc.embedding OPERATOR(extensions.<=>) p_query_embedding)
    END AS similarity,
    CASE
      WHEN p_query_text IS NULL OR p_query_text = '' THEN 0.0
      ELSE ts_rank(
             to_tsvector('simple', kc.content),
             plainto_tsquery('simple', p_query_text)
           )::double precision
    END AS keyword_rank
  FROM public.knowledge_chunks kc
  LEFT JOIN public.documents d ON d.id = kc.document_id
  WHERE
    -- Tenant isolation filter
    (
      public.is_platform_super_admin()
      OR (p_organization_id IS NOT NULL AND kc.organization_id = p_organization_id AND public.org_visible(p_organization_id))
      OR (p_organization_id IS NULL AND (
            kc.organization_id = ANY(public.current_user_organization_ids()) 
            AND public.org_is_operational(kc.organization_id)
         ))
      OR (kc.organization_id IS NULL AND COALESCE(d.is_master_template, false) = true)
    )
    AND (
      (kc.embedding IS NOT NULL AND p_query_embedding IS NOT NULL
        AND 1 - (kc.embedding OPERATOR(extensions.<=>) p_query_embedding) >= p_min_similarity)
      OR
      (p_query_text IS NOT NULL AND p_query_text <> ''
        AND to_tsvector('simple', kc.content) @@ plainto_tsquery('simple', p_query_text))
    )
  ORDER BY
    (0.7 * CASE
             WHEN kc.embedding IS NULL OR p_query_embedding IS NULL THEN 0.0
             ELSE 1 - (kc.embedding OPERATOR(extensions.<=>) p_query_embedding)
           END)
    + (0.3 * CASE
               WHEN p_query_text IS NULL OR p_query_text = '' THEN 0.0
               ELSE least(
                      ts_rank(
                        to_tsvector('simple', kc.content),
                        plainto_tsquery('simple', p_query_text)
                      )::double precision,
                      1.0)
             END) DESC
  LIMIT greatest(p_match_count, 1);
$function$
;

CREATE OR REPLACE FUNCTION public.membership_app_roles(p_role membership_role)
 RETURNS app_role[]
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
  SELECT CASE p_role
    WHEN 'organization_owner' THEN ARRAY['administrator', 'learner']::public.app_role[]
    WHEN 'organization_admin' THEN ARRAY['administrator', 'learner']::public.app_role[]
    WHEN 'brand_admin'        THEN ARRAY['administrator', 'learner']::public.app_role[]
    WHEN 'hotel_admin'        THEN ARRAY['training_manager', 'learner']::public.app_role[]
    WHEN 'training_manager'   THEN ARRAY['training_manager', 'learner']::public.app_role[]
    WHEN 'knowledge_manager'  THEN ARRAY['knowledge_manager', 'learner']::public.app_role[]
    WHEN 'department_manager' THEN ARRAY['author', 'learner']::public.app_role[]
    WHEN 'author'             THEN ARRAY['author', 'learner']::public.app_role[]
    WHEN 'instructor'         THEN ARRAY['author', 'learner']::public.app_role[]
    ELSE ARRAY['learner']::public.app_role[]
  END;
$function$
;

CREATE OR REPLACE FUNCTION public.my_feature_enabled(p_key text, p_org_id uuid DEFAULT NULL::uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_org uuid;
BEGIN
  v_org := COALESCE(
    p_org_id, public.get_operator_impersonated_org(),
    (SELECT organization_id FROM public.organization_memberships
     WHERE user_id = auth.uid() AND is_active = true ORDER BY is_primary DESC LIMIT 1)
  );
  IF v_org IS NULL THEN RETURN false; END IF;
  RETURN public.feature_enabled(v_org, p_key);
END;
$function$
;

CREATE OR REPLACE FUNCTION public.notification_policy_enabled(p_org_id uuid, p_key text)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT COALESCE(
    (
      SELECT CASE
        WHEN NOT pnp.allow_tenant_override THEN pnp.default_enabled
        WHEN ono.is_enabled IS NOT NULL THEN ono.is_enabled
        ELSE pnp.default_enabled
      END
      FROM public.platform_notification_policies pnp
      LEFT JOIN public.organization_notification_overrides ono
        ON ono.policy_key = pnp.key AND ono.organization_id = p_org_id
      WHERE pnp.key = p_key
    ),
    true
  );
$function$
;

CREATE OR REPLACE FUNCTION public.notify_comment_added()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  -- Notify current assignee and requester about new comment
  IF NEW.request_id IS NOT NULL THEN
    DECLARE
      req RECORD;
    BEGIN
      SELECT * INTO req FROM requests WHERE id = NEW.request_id;
      
      -- Notify current assignee (if not the commenter)
      IF req.current_assignee_id IS NOT NULL AND req.current_assignee_id != NEW.author_id THEN
        INSERT INTO notifications (user_id, type, title, message, metadata)
        VALUES (
          req.current_assignee_id,
          'comment_added',
          'New Comment Added',
          format('A new comment was added to request #%s', req.request_no),
          jsonb_build_object('request_id', NEW.request_id, 'comment_id', NEW.id)
        );
      END IF;
      
      -- Notify requester (if not the commenter and different from assignee)
      IF req.requester_id != NEW.author_id AND req.requester_id != req.current_assignee_id THEN
        INSERT INTO notifications (user_id, type, title, message, metadata)
        VALUES (
          req.requester_id,
          'comment_added',
          'New Comment Added',
          format('A new comment was added to request #%s', req.request_no),
          jsonb_build_object('request_id', NEW.request_id, 'comment_id', NEW.id)
        );
      END IF;
    END;
  END IF;
  
  RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.notify_document_created()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_rule RECORD;
    v_folder_name TEXT;
BEGIN
    -- Get folder name if document is in a folder
    IF NEW.folder_id IS NOT NULL THEN
        SELECT name INTO v_folder_name FROM document_folders WHERE id = NEW.folder_id;
    ELSE
        v_folder_name := 'All Documents';
    END IF;
    
    -- Create notifications for users watching this folder
    FOR v_rule IN 
        SELECT user_id 
        FROM document_notification_rules 
        WHERE (folder_id = NEW.folder_id OR folder_id IS NULL)
        AND notify_on_new = TRUE
        AND user_id != NEW.created_by  -- Don't notify the creator
    LOOP
        -- Insert into notifications table (assumes notifications table exists)
        INSERT INTO notifications (user_id, type, title, content, entity_type, entity_id)
        VALUES (
            v_rule.user_id,
            'document_created',
            'New Document: ' || NEW.title,
            'A new document has been added to ' || v_folder_name,
            'document',
            NEW.id
        );
    END LOOP;
    
    RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.notify_document_updated()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_rule RECORD;
    v_folder_name TEXT;
BEGIN
    -- Only notify if title or status changed (not just view counts, etc.)
    IF NEW.title = OLD.title AND NEW.status = OLD.status AND NEW.folder_id IS NOT DISTINCT FROM OLD.folder_id THEN
        RETURN NEW;
    END IF;
    
    -- Get folder name
    IF NEW.folder_id IS NOT NULL THEN
        SELECT name INTO v_folder_name FROM document_folders WHERE id = NEW.folder_id;
    ELSE
        v_folder_name := 'All Documents';
    END IF;
    
    -- Create notifications for users watching this folder
    FOR v_rule IN 
        SELECT user_id 
        FROM document_notification_rules 
        WHERE (folder_id = NEW.folder_id OR folder_id IS NULL)
        AND notify_on_update = TRUE
        AND user_id != COALESCE(NEW.updated_by, NEW.created_by)  -- Don't notify the updater
    LOOP
        INSERT INTO notifications (user_id, type, title, content, entity_type, entity_id)
        VALUES (
            v_rule.user_id,
            'document_updated',
            'Updated Document: ' || NEW.title,
            'The document has been updated in ' || v_folder_name,
            'document',
            NEW.id
        );
    END LOOP;
    
    RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.notify_message_received()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NEW.message_type = 'direct' AND NEW.recipient_id IS NOT NULL AND NEW.recipient_id <> NEW.sender_id THEN
    INSERT INTO public.notifications (user_id, type, title, message, metadata, entity_type, entity_id, link, created_at)
    VALUES (
      NEW.recipient_id,
      'message_received',
      'New message',
      COALESCE(NULLIF(NEW.subject, ''), 'You have a new message'),
      jsonb_build_object('message_id', NEW.id, 'sender_id', NEW.sender_id),
      'message',
      NEW.id,
      '/messaging/' || NEW.id::text,
      now()
    )
    ON CONFLICT (user_id, type, entity_type, entity_id)
      WHERE (type = 'message_received' AND entity_type = 'message' AND entity_id IS NOT NULL)
    DO NOTHING;
  END IF;

  RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.notify_request_status_changed()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  -- Notify requester if status changed
  IF OLD.status != NEW.status AND NEW.requester_id IS NOT NULL THEN
    INSERT INTO notifications (user_id, type, title, message, metadata)
    VALUES (
      NEW.requester_id,
      CASE NEW.status
        WHEN 'approved' THEN 'request_approved'
        WHEN 'rejected' THEN 'request_rejected'
        WHEN 'returned_for_correction' THEN 'request_returned'
        WHEN 'closed' THEN 'request_closed'
        ELSE 'request_approved' -- fallback
      END,
      format('Request #%s %s', NEW.request_no, REPLACE(NEW.status, '_', ' ')),
      format('Your request has been %s', REPLACE(NEW.status, '_', ' ')),
      jsonb_build_object('request_id', NEW.id, 'entity_type', NEW.entity_type)
    );
  END IF;
  
  RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.notify_request_submitted()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  -- Notify supervisor
  IF NEW.supervisor_id IS NOT NULL THEN
    INSERT INTO notifications (user_id, type, title, message, metadata)
    VALUES (
      NEW.supervisor_id,
      'request_submitted',
      'New Request Submitted',
      format('Request #%s from %s requires your approval', NEW.request_no, COALESCE((SELECT full_name FROM profiles WHERE id = NEW.requester_id), 'Unknown')),
      jsonb_build_object('request_id', NEW.id, 'entity_type', NEW.entity_type)
    );
  END IF;
  
  RETURN NEW;
END;
$function$
;

