CREATE OR REPLACE FUNCTION public.platform_assign_master_content(p_master_id uuid, p_org_ids uuid[], p_content_type text DEFAULT 'course'::text, p_scope_type text DEFAULT 'organization'::text, p_target_role text DEFAULT NULL::text, p_target_user_ids uuid[] DEFAULT NULL::uuid[], p_due_date timestamp with time zone DEFAULT NULL::timestamp with time zone, p_priority text DEFAULT 'normal'::text, p_instructions text DEFAULT NULL::text, p_auto_deploy boolean DEFAULT true)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_org uuid;
  v_deployed uuid;
  v_assign jsonb;
  v_results jsonb := '[]'::jsonb;
  v_org_name text;
BEGIN
  IF NOT (public.is_platform_operator() AND public.platform_operator_can('tenant.manage')) THEN
    RAISE EXCEPTION 'Permission denied: platform operator with tenant.manage required'
      USING ERRCODE = '42501';
  END IF;
  IF p_org_ids IS NULL OR array_length(p_org_ids, 1) IS NULL THEN
    RAISE EXCEPTION 'At least one target organization is required' USING ERRCODE = '22023';
  END IF;

  FOREACH v_org IN ARRAY p_org_ids LOOP
    SELECT name INTO v_org_name FROM public.organizations WHERE id = v_org;
    v_deployed := NULL;

    BEGIN
      -- Resolve (or create) this tenant's copy of the master content.
      SELECT target_content_id INTO v_deployed
      FROM public.master_content_deployments
      WHERE master_content_id = p_master_id
        AND content_type = p_content_type
        AND target_organization_id = v_org;

      IF v_deployed IS NULL THEN
        IF p_auto_deploy THEN
          v_deployed := public.deploy_master_content(p_master_id, p_content_type, v_org);
        ELSE
          v_results := v_results || jsonb_build_object(
            'org_id', v_org, 'org_name', v_org_name, 'assigned', false,
            'error', 'not deployed to this tenant');
          CONTINUE;
        END IF;
      END IF;

      -- Assign via the existing tenant engine (it re-checks authority, snapshots
      -- the rule, seeds training_progress/enrollments, notifies, and audits).
      v_assign := public.create_scoped_training_assignment(
        p_course_id            => v_deployed,
        p_scope_type           => p_scope_type,
        p_organization_id      => v_org,
        p_target_role          => p_target_role,
        p_target_user_ids      => p_target_user_ids,
        p_due_date             => p_due_date,
        p_priority             => p_priority,
        p_instructions         => p_instructions
      );

      v_results := v_results || jsonb_build_object(
        'org_id', v_org, 'org_name', v_org_name,
        'deployed_content_id', v_deployed,
        'assigned', COALESCE((v_assign->>'success')::boolean, false),
        'rule_id', v_assign->>'rule_id',
        'recipient_count', COALESCE((v_assign->>'recipient_count')::int, 0)
      );
    EXCEPTION WHEN OTHERS THEN
      v_results := v_results || jsonb_build_object(
        'org_id', v_org, 'org_name', v_org_name,
        'deployed_content_id', v_deployed,
        'assigned', false, 'error', SQLERRM);
    END;
  END LOOP;

  INSERT INTO public.platform_audit_logs (actor_id, action, resource_type, resource_id, metadata)
  VALUES (auth.uid(), 'master_content.assigned', p_content_type, p_master_id::text,
          jsonb_build_object('org_ids', to_jsonb(p_org_ids), 'scope_type', p_scope_type,
                             'due_date', p_due_date, 'results', v_results));

  RETURN jsonb_build_object('master_id', p_master_id, 'results', v_results);
END;
$function$
;

CREATE OR REPLACE FUNCTION public.platform_operator_can(_permission text, _user_id uuid DEFAULT auth.uid())
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  WITH caller AS (
    SELECT pra.platform_role::text AS role
    FROM public.platform_users pu
    JOIN public.platform_role_assignments pra ON pra.platform_user_id = pu.user_id
    WHERE pu.user_id = _user_id AND pu.is_active AND pra.revoked_at IS NULL
  )
  SELECT EXISTS (
    SELECT 1 FROM caller c
    JOIN (VALUES
      ('system_owner','*'),
      ('platform_admin','operator.manage'),      ('platform_admin','tenant.manage'),
      ('platform_admin','billing.manage'),       ('platform_admin','master_content.manage'),
      ('platform_admin','ops.manage'),           ('platform_admin','config.manage'),
      ('platform_admin','tenant.enter'),         ('platform_admin','tenant.read'),
      ('platform_training_manager','master_content.manage'),
      ('platform_training_manager','tenant.enter'),  ('platform_training_manager','tenant.read'),
      ('platform_knowledge_manager','master_content.manage'),
      ('platform_knowledge_manager','tenant.enter'), ('platform_knowledge_manager','tenant.read'),
      ('platform_support','tenant.enter'),       ('platform_support','tenant.read'),
      ('platform_operations','ops.manage'),      ('platform_operations','tenant.read'),
      ('platform_instructor','tenant.enter'),    ('platform_instructor','tenant.read')
    ) AS perm(role, permission) ON perm.role = c.role
    WHERE perm.permission = _permission OR perm.permission = '*'
  );
$function$
;

CREATE OR REPLACE FUNCTION public.platform_operator_has_role(_role text, _user_id uuid DEFAULT auth.uid())
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT EXISTS (
    SELECT 1 FROM public.platform_users pu
    JOIN public.platform_role_assignments pra ON pra.platform_user_id = pu.user_id
    WHERE pu.user_id = _user_id AND pu.is_active AND pra.revoked_at IS NULL
      AND ( pra.platform_role::text = _role
            OR pra.platform_role = 'system_owner'
            OR (pra.platform_role = 'platform_admin' AND _role <> 'system_owner') )
  );
$function$
;

CREATE OR REPLACE FUNCTION public.platform_set_membership(p_org_id uuid, p_user_id uuid, p_role text, p_hotel_id uuid DEFAULT NULL::uuid, p_department_id uuid DEFAULT NULL::uuid, p_active boolean DEFAULT true)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NOT (public.is_platform_operator() AND public.platform_operator_can('tenant.manage'))
     AND NOT public.is_tenant_people_admin(p_org_id) THEN
    RAISE EXCEPTION 'Not authorized to manage members of this organization' USING ERRCODE = '42501';
  END IF;
  IF p_role NOT IN ('organization_owner','organization_admin','brand_admin','hotel_admin',
                    'department_manager','training_manager','knowledge_manager','author','instructor','learner') THEN
    RAISE EXCEPTION 'Invalid membership role' USING ERRCODE = '22023';
  END IF;
  IF p_role = 'organization_owner' AND NOT public.is_platform_operator() THEN
    RAISE EXCEPTION 'Only a platform operator may set organization_owner' USING ERRCODE = '42501';
  END IF;
  UPDATE public.organization_memberships SET
    role = p_role::public.membership_role, hotel_id = p_hotel_id,
    department_id = p_department_id, is_active = p_active, updated_at = now()
  WHERE organization_id = p_org_id AND user_id = p_user_id;
  IF NOT FOUND THEN
    INSERT INTO public.organization_memberships (organization_id, user_id, role, hotel_id, department_id, is_active)
    VALUES (p_org_id, p_user_id, p_role::public.membership_role, p_hotel_id, p_department_id, p_active);
  END IF;
  INSERT INTO public.platform_audit_logs (actor_id, target_organization_id, action, resource_type, resource_id, metadata)
  VALUES (auth.uid(), p_org_id, 'set_membership', 'organization_membership', p_user_id::text,
          jsonb_build_object('role', p_role, 'hotel_id', p_hotel_id, 'department_id', p_department_id, 'is_active', p_active));
END;
$function$
;

CREATE OR REPLACE FUNCTION public.process_certificate_expirations()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_cert record;
    v_progress_id uuid;
    v_processed integer := 0;
BEGIN
    FOR v_cert IN
        SELECT c.id, c.user_id, c.title, c.training_module_id, c.training_progress_id,
               COALESCE(m.organization_id, c.organization_id) AS organization_id,
               (m.id IS NOT NULL AND m.status = 'published' AND m.is_deleted = false) AS module_live
          FROM public.certificates c
          LEFT JOIN public.training_modules m ON m.id = c.training_module_id
         WHERE c.status = 'active'
           AND c.expiry_date IS NOT NULL
           AND c.expiry_date <= now()
    LOOP
        BEGIN
            UPDATE public.certificates SET status = 'expired', updated_at = now() WHERE id = v_cert.id;

            INSERT INTO public.certificate_history (certificate_id, organization_id, action, details)
            VALUES (v_cert.id, v_cert.organization_id, 'updated',
                    jsonb_build_object('reason', 'expired', 'processed_at', now()));

            IF v_cert.module_live AND v_cert.organization_id IS NOT NULL THEN
                SELECT tp.id INTO v_progress_id
                  FROM public.training_progress tp
                 WHERE tp.user_id = v_cert.user_id AND tp.training_id = v_cert.training_module_id;

                IF v_progress_id IS NOT NULL THEN
                    PERFORM public._reset_training_cycle(v_progress_id, 'certificate_expired', NULL);
                END IF;

                PERFORM public._issue_recertification_assignment(
                    v_cert.organization_id, v_cert.user_id, v_cert.training_module_id, v_cert.title,
                    v_progress_id, now() + interval '30 days', NULL,
                    'Your certificate for "' || v_cert.title || '" has expired. Please retake the training within 30 days.');
            ELSE
                INSERT INTO public.notifications (user_id, organization_id, type, title, message, entity_type, entity_id)
                VALUES (v_cert.user_id, v_cert.organization_id, 'training_recertification', 'Certification expired',
                        'Your certificate for "' || v_cert.title || '" has expired.', 'certificate', v_cert.id);
            END IF;

            v_processed := v_processed + 1;
        EXCEPTION WHEN OTHERS THEN
            -- One bad row must not stop the nightly batch.
            RAISE WARNING 'process_certificate_expirations: certificate % failed: %', v_cert.id, SQLERRM;
        END;
    END LOOP;

    RETURN v_processed;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.process_employee_transfer(p_user_id uuid, p_target_hotel_id uuid, p_target_dept_id uuid, p_target_role text, p_reason text, p_actor_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  -- Authority always comes from the session; p_actor_id is honoured only for
  -- trusted server-side (service_role) callers acting on someone's behalf.
  v_caller_id uuid := CASE WHEN COALESCE(auth.role(), '') = 'service_role'
                           THEN COALESCE(p_actor_id, auth.uid()) ELSE auth.uid() END;
  v_is_platform boolean;
  v_org_id uuid;
  v_old_hotel_id uuid;
  v_old_dept_id uuid;
  v_old_role text;
  v_target_role_enum public.membership_role;
  v_waived_count integer := 0;
  v_waived_ids uuid[];
  v_assigned_count integer := 0;
  v_rule record;
  v_module_id uuid;
BEGIN
  IF v_caller_id IS NULL AND COALESCE(auth.role(), '') <> 'service_role' THEN
    RAISE EXCEPTION 'Authentication required.' USING ERRCODE = '42501';
  END IF;

  SELECT organization_id, hotel_id, department_id, role::text
    INTO v_org_id, v_old_hotel_id, v_old_dept_id, v_old_role
    FROM public.organization_memberships
   WHERE user_id = p_user_id AND is_active = true
   ORDER BY is_primary DESC, created_at ASC
   LIMIT 1;

  IF v_org_id IS NULL THEN
    RAISE EXCEPTION 'Active organization membership not found for user %', p_user_id;
  END IF;

  v_is_platform := COALESCE(auth.role(), '') = 'service_role' OR public.is_platform_super_admin();

  IF NOT v_is_platform AND NOT public.is_tenant_people_admin(v_org_id) THEN
    RAISE EXCEPTION 'Access denied: not authorized to transfer employees in this organization' USING ERRCODE = '42501';
  END IF;

  BEGIN
    v_target_role_enum := p_target_role::public.membership_role;
  EXCEPTION WHEN OTHERS THEN
    v_target_role_enum := 'learner'::public.membership_role;
  END;

  -- Tenant people-admins cannot mint owners, and only tenant admins grant admin.
  IF NOT v_is_platform THEN
    IF v_target_role_enum = 'organization_owner' AND v_old_role IS DISTINCT FROM 'organization_owner' THEN
      RAISE EXCEPTION 'Only the platform can transfer organization ownership' USING ERRCODE = '42501';
    END IF;
    IF v_target_role_enum IN ('organization_admin', 'brand_admin') AND NOT public.is_tenant_admin(v_org_id) THEN
      RAISE EXCEPTION 'Only organization admins can grant admin roles' USING ERRCODE = '42501';
    END IF;
    IF p_user_id = v_caller_id AND v_target_role_enum::text IS DISTINCT FROM v_old_role THEN
      RAISE EXCEPTION 'You cannot change your own role' USING ERRCODE = '42501';
    END IF;
  END IF;

  INSERT INTO public.employee_transfer_logs (
    user_id, organization_id,
    previous_hotel_id, new_hotel_id, from_hotel_id, to_hotel_id,
    previous_department_id, new_department_id, from_department_id, to_department_id,
    previous_role, new_role, from_role, to_role,
    notes, reason, transferred_by, transfer_effective_date, created_at
  ) VALUES (
    p_user_id, v_org_id,
    v_old_hotel_id, p_target_hotel_id, v_old_hotel_id, p_target_hotel_id,
    v_old_dept_id, p_target_dept_id, v_old_dept_id, p_target_dept_id,
    v_old_role, v_target_role_enum::text, v_old_role, v_target_role_enum::text,
    p_reason, p_reason, v_caller_id, CURRENT_DATE, now()
  );

  UPDATE public.organization_memberships
     SET hotel_id = p_target_hotel_id,
         department_id = p_target_dept_id,
         role = v_target_role_enum,
         updated_at = now()
   WHERE user_id = p_user_id AND organization_id = v_org_id;

  UPDATE public.profiles SET updated_at = now() WHERE id = p_user_id;

  -- Waive optional, hotel-specific individual assignments from the old hotel, and
  -- retire the untouched progress rows they seeded (work already started stays).
  WITH waived_rows AS (
    UPDATE public.training_assignment_rules r
       SET is_active = false,
           status = 'waived',
           instructions = COALESCE(r.instructions || ' | ', '') || 'Waived due to transfer to new hotel'
     WHERE r.organization_id = v_org_id
       AND r.target_type = 'user' AND r.target_id = p_user_id::text
       AND r.is_active AND NOT COALESCE(r.is_deleted, false)
       AND r.is_mandatory IS NOT TRUE
       AND r.hotel_id IS NOT NULL
       AND r.hotel_id IS DISTINCT FROM p_target_hotel_id
    RETURNING r.id
  )
  SELECT array_agg(id) INTO v_waived_ids FROM waived_rows;
  v_waived_count := COALESCE(cardinality(v_waived_ids), 0);

  IF v_waived_count > 0 THEN
    UPDATE public.training_progress tp
       SET is_deleted = true,
           updated_at = now()
     WHERE tp.user_id = p_user_id
       AND tp.status = 'not_started'
       AND tp.assignment_id = ANY (v_waived_ids);
  END IF;

  -- Standing rules for the new hotel / department / role.
  FOR v_rule IN
    SELECT tar.training_module_id, tar.content_id, tar.is_mandatory, COALESCE(tar.due_in_days, 14) AS due_in_days
      FROM public.training_assignment_rules tar
     WHERE tar.is_active AND NOT COALESCE(tar.is_deleted, false)
       AND tar.organization_id = v_org_id
       AND public._is_standing_assignment_rule(tar.target_type, tar.target_user_ids)
       AND (tar.hotel_id IS NULL OR tar.hotel_id = p_target_hotel_id OR (tar.scope_type = 'hotel' AND tar.scope_id = p_target_hotel_id))
       AND (tar.department_id IS NULL OR tar.department_id = p_target_dept_id OR (tar.scope_type = 'department' AND tar.scope_id = p_target_dept_id))
       AND (tar.target_role IS NULL OR tar.target_role = 'all' OR tar.target_role = v_target_role_enum::text)
  LOOP
    v_module_id := COALESCE(v_rule.training_module_id, v_rule.content_id);
    IF v_module_id IS NOT NULL
       AND public._assign_module_to_user(
             v_org_id, p_user_id, v_module_id, now() + make_interval(days => v_rule.due_in_days),
             v_rule.is_mandatory, v_caller_id, p_target_hotel_id, p_target_dept_id,
             'Assigned via transfer delta evaluation') IS NOT NULL THEN
      v_assigned_count := v_assigned_count + 1;
    END IF;
  END LOOP;

  UPDATE public.employee_transfer_logs
     SET waived_obsolete_courses_count = v_waived_count,
         assigned_delta_courses_count = v_assigned_count
   WHERE user_id = p_user_id
     AND organization_id = v_org_id
     AND transfer_effective_date = CURRENT_DATE
     AND to_hotel_id IS NOT DISTINCT FROM p_target_hotel_id;

  RETURN jsonb_build_object(
    'success', true,
    'user_id', p_user_id,
    'from_hotel_id', v_old_hotel_id,
    'to_hotel_id', p_target_hotel_id,
    'waived_count', v_waived_count,
    'assigned_count', v_assigned_count
  );
END;
$function$
;

CREATE OR REPLACE FUNCTION public.process_notification_batch(p_batch_size integer DEFAULT 50)
 RETURNS TABLE(processed integer, remaining integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_processed INT := 0;
  v_remaining INT;
  v_item RECORD;
BEGIN
  FOR v_item IN (
    SELECT id, user_id, notification_type, notification_data, batch_id
    FROM notification_queue
    WHERE status = 'pending'
    ORDER BY created_at
    LIMIT p_batch_size
    FOR UPDATE SKIP LOCKED
  ) LOOP
    UPDATE notification_queue SET status = 'processing', attempts = attempts + 1 WHERE id = v_item.id;
    INSERT INTO notifications (user_id, title, message, type, data)
    VALUES (
      v_item.user_id,
      v_item.notification_data->>'title',
      v_item.notification_data->>'message',
      v_item.notification_type,
      v_item.notification_data
    );
    UPDATE notification_queue SET status = 'sent', processed_at = NOW() WHERE id = v_item.id;
    UPDATE notification_batches SET processed_count = processed_count + 1 WHERE id = v_item.batch_id;
    v_processed := v_processed + 1;
  END LOOP;

  SELECT COUNT(*) INTO v_remaining FROM notification_queue WHERE status = 'pending';

  UPDATE notification_batches
  SET status = 'completed', completed_at = NOW()
  WHERE status = 'processing' AND processed_count + failed_count >= total_count;

  RETURN QUERY SELECT v_processed, v_remaining;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.process_request_finalization()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
    IF NEW.status = 'approved' AND OLD.status IS DISTINCT FROM 'approved' THEN
        IF NEW.entity_type = 'promotion' THEN
            PERFORM public.process_due_promotions();
        ELSIF NEW.entity_type = 'transfer' THEN
            PERFORM public.process_due_transfers();
        END IF;
    END IF;
    RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.publish_document_to_kb(p_document_id uuid, p_user_id uuid, p_visibility text DEFAULT NULL::text, p_category_id uuid DEFAULT NULL::uuid, p_department_id uuid DEFAULT NULL::uuid, p_supersedes_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_doc record;
    v_supersede_target uuid;
    v_guard_org uuid;
BEGIN
    SELECT organization_id INTO v_guard_org FROM public.documents WHERE id = p_document_id;
    IF NOT (public.is_platform_super_admin() OR public._p7_is_service_context()
            OR public.is_tenant_admin(v_guard_org) OR public.is_tenant_content_editor(v_guard_org)) THEN
      RAISE EXCEPTION 'not authorized for organization %', v_guard_org USING ERRCODE = '42501';
    END IF;

    SELECT * INTO v_doc FROM public.documents WHERE id = p_document_id;
    IF NOT FOUND THEN
        RETURN jsonb_build_object('success', false, 'error', 'Document not found');
    END IF;

    v_supersede_target := COALESCE(p_supersedes_id, v_doc.supersedes_document_id);

    -- If this document supersedes an earlier version, deactivate the previous version from KB
    IF v_supersede_target IS NOT NULL THEN
        UPDATE public.documents
        SET
            knowledge_base_status = 'superseded',
            is_active_kb_version = false,
            updated_at = NOW()
        WHERE id = v_supersede_target;
    END IF;

    -- Update target document to Published KB status
    UPDATE public.documents
    SET
        status = 'PUBLISHED'::document_status,
        knowledge_base_status = 'indexed',
        is_active_kb_version = true,
        published_at = NOW(),
        published_by = p_user_id,
        last_published_by = p_user_id,
        visibility = COALESCE(p_visibility::document_visibility, visibility),
        category_id = COALESCE(p_category_id, category_id),
        department_id = COALESCE(p_department_id, department_id),
        supersedes_document_id = v_supersede_target,
        updated_at = NOW(),
        updated_by = p_user_id
    WHERE id = p_document_id;

    RETURN jsonb_build_object('success', true, 'document_id', p_document_id, 'superseded_id', v_supersede_target);
END;
$function$
;

CREATE OR REPLACE FUNCTION public.purge_archived_organizations()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE r record; n integer := 0;
BEGIN
  FOR r IN
    SELECT id, name FROM public.organizations
    WHERE lifecycle_status = 'archived'
      AND purge_scheduled_at IS NOT NULL
      AND purge_scheduled_at < now()
  LOOP
    -- final audit BEFORE the delete (platform_audit_logs is retained ~7y, no target FK cascade)
    INSERT INTO public.platform_audit_logs (actor_id, target_organization_id, action, resource_type, resource_id, metadata)
    VALUES (NULL, NULL, 'purge_organization', 'organization', r.id::text,
            jsonb_build_object('name', r.name, 'purged_at', now()));
    DELETE FROM public.organizations WHERE id = r.id;   -- ON DELETE CASCADE fans out to tenant data
    n := n + 1;
  END LOOP;
  RETURN n;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.rebuild_document_search_index()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_count INTEGER := 0;
    v_doc RECORD;
BEGIN
    FOR v_doc IN SELECT id FROM documents WHERE is_archived = FALSE
    LOOP
        UPDATE documents SET id = id WHERE id = v_doc.id;
        v_count := v_count + 1;
    END LOOP;
    
    RETURN v_count;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.record_failed_login_attempt(p_email text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_record public.failed_login_attempts%ROWTYPE;
  v_profile_id uuid;
  v_client_ip text;
BEGIN
  -- Per-target-email limit: at most 8 recorded attempts per 5 minutes. Genuine mistyped-password
  -- sequences stay well under this; it caps how fast/often an attacker can force or refresh a
  -- lockout on a single account.
  IF NOT public.check_rate_limit('failed_login_rpc:email:' || lower(p_email), 8, 300) THEN
    RETURN;
  END IF;

  -- Per-source-IP limit: at most 20 recorded attempts per 5 minutes across all target emails.
  -- Caps one attacker source from sweeping through many different accounts. inet_client_addr()
  -- reflects the immediate connecting peer (may be a shared proxy/pooler address in some
  -- deployments) - treated as a defense-in-depth layer alongside the per-email limit, not the
  -- sole control.
  v_client_ip := coalesce(inet_client_addr()::text, 'unknown');
  IF NOT public.check_rate_limit('failed_login_rpc:ip:' || v_client_ip, 20, 300) THEN
    RETURN;
  END IF;

  -- Check if there's an existing record for this email
  SELECT * INTO v_record
  FROM public.failed_login_attempts
  WHERE email = lower(p_email)
  ORDER BY last_attempt_at DESC
  LIMIT 1;

  IF FOUND AND v_record.locked_until IS NOT NULL AND v_record.locked_until > now() THEN
    -- Already locked, just update timestamp
    UPDATE public.failed_login_attempts
    SET last_attempt_at = now()
    WHERE id = v_record.id;
    RETURN;
  END IF;

  IF FOUND THEN
    -- Update existing record
    UPDATE public.failed_login_attempts
    SET attempt_count = attempt_count + 1,
        last_attempt_at = now(),
        captcha_required = CASE WHEN attempt_count >= 3 THEN true ELSE captcha_required END,
        locked_until = CASE
          WHEN attempt_count >= 5 THEN now() + interval '30 minutes'
          ELSE locked_until
        END
    WHERE id = v_record.id;
  ELSE
    -- Insert new record
    INSERT INTO public.failed_login_attempts (email, attempt_count)
    VALUES (lower(p_email), 1);
  END IF;

  -- Also update the profile if it exists
  SELECT id INTO v_profile_id
  FROM public.profiles
  WHERE email = lower(p_email);

  IF FOUND THEN
    UPDATE public.profiles
    SET failed_login_attempts = COALESCE(failed_login_attempts, 0) + 1,
        locked_until = CASE
          WHEN COALESCE(failed_login_attempts, 0) + 1 >= 5 THEN now() + interval '30 minutes'
          ELSE locked_until
        END,
        account_status = CASE
          WHEN COALESCE(failed_login_attempts, 0) + 1 >= 5 THEN 'locked'
          ELSE account_status
        END
    WHERE id = v_profile_id;
  END IF;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.refresh_sop_document_search()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  REFRESH MATERIALIZED VIEW CONCURRENTLY sop_document_search;
  RETURN NULL;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.reject_training_module(p_module_id uuid, p_reason text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_org uuid;
    v_title text;
    v_author uuid;
BEGIN
    SELECT organization_id INTO v_org FROM public.training_modules WHERE id = p_module_id;
    IF v_org IS NULL OR NOT public.can_review_training_module(v_org) THEN
        RAISE EXCEPTION 'Not authorized to reject training modules';
    END IF;

    UPDATE public.training_modules
       SET status = 'draft', updated_at = now(), updated_by = auth.uid()
     WHERE id = p_module_id AND status = 'pending_review'
    RETURNING title, created_by INTO v_title, v_author;

    IF v_title IS NULL THEN
        RAISE EXCEPTION 'Module not found or not pending review';
    END IF;

    IF v_author IS NOT NULL THEN
        INSERT INTO public.notifications (user_id, organization_id, type, title, message, link, entity_type, entity_id, metadata)
        VALUES (
            v_author, v_org,
            'training_review_rejected',
            'Training module needs changes',
            '"' || v_title || '" was sent back to draft.' || CASE WHEN p_reason IS NOT NULL THEN ' Reason: ' || p_reason ELSE '' END,
            '/training/hub/' || p_module_id || '?view=builder',
            'training_module',
            p_module_id,
            jsonb_build_object('reason', p_reason)
        );
    END IF;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.remove_document_from_kb(p_document_id uuid, p_user_id uuid, p_reason text DEFAULT 'Removed by administrator'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_guard_org uuid;
BEGIN
    SELECT organization_id INTO v_guard_org FROM public.documents WHERE id = p_document_id;
    IF NOT (public.is_platform_super_admin() OR public._p7_is_service_context()
            OR public.is_tenant_admin(v_guard_org) OR public.is_tenant_content_editor(v_guard_org)) THEN
      RAISE EXCEPTION 'not authorized for organization %', v_guard_org USING ERRCODE = '42501';
    END IF;

    UPDATE public.documents
    SET
        knowledge_base_status = 'removed',
        is_active_kb_version = false,
        updated_at = NOW(),
        updated_by = p_user_id
    WHERE id = p_document_id;

    IF NOT FOUND THEN
        RETURN jsonb_build_object('success', false, 'error', 'Document not found');
    END IF;

    RETURN jsonb_build_object('success', true, 'document_id', p_document_id);
END;
$function$
;

CREATE OR REPLACE FUNCTION public.reorder_user_pins(p_user_id uuid, p_pin_orders jsonb)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_pin_id UUID;
  v_order INT;
  v_item RECORD;
BEGIN
  -- Verify user can only modify their own pins
  IF p_user_id != auth.uid() THEN
    RAISE EXCEPTION 'Cannot modify pins for other users';
  END IF;

  -- Update display orders
  FOR v_item IN 
    SELECT 
      (elem->>'pin_id')::UUID as pin_id,
      (elem->>'display_order')::INT as display_order
    FROM jsonb_array_elements(p_pin_orders) as elem
  LOOP
    UPDATE user_pins
    SET display_order = v_item.display_order
    WHERE id = v_item.pin_id AND user_id = p_user_id;
  END LOOP;

  RETURN TRUE;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.request_after_update_status_event()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NEW.status IS DISTINCT FROM OLD.status THEN
    INSERT INTO request_events (request_id, actor_id, event_type, payload)
    VALUES (
      NEW.id,
      auth.uid(),
      'status_changed',
      jsonb_build_object('from', OLD.status, 'to', NEW.status)
    );
  END IF;

  RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.request_attachment_event()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  INSERT INTO request_events (request_id, actor_id, event_type, payload)
  VALUES (NEW.request_id, NEW.uploaded_by, 'attachment_added', jsonb_build_object('file_name', NEW.file_name));
  RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.request_comment_event()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  assignee_id UUID;
BEGIN
  INSERT INTO request_events (request_id, actor_id, event_type, payload)
  VALUES (NEW.request_id, NEW.author_id, 'comment_added', jsonb_build_object('visibility', NEW.visibility));

  SELECT r.current_assignee_id INTO assignee_id FROM requests r WHERE r.id = NEW.request_id;

  -- In-app notification to current assignee (if any and not self)
  IF assignee_id IS NOT NULL AND assignee_id <> NEW.author_id THEN
    INSERT INTO notifications (user_id, type, title, message, metadata)
    VALUES (
      assignee_id,
      'comment_added',
      'New comment on request',
      'A new comment was added to a request requiring attention.',
      jsonb_build_object('request_id', NEW.request_id)
    );
  END IF;

  RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.request_id_from_storage_path(p_path text)
 RETURNS uuid
