CREATE OR REPLACE FUNCTION public.reset_user_wizard_progress(p_target_user_id uuid, p_wizard_id text, p_org_id uuid DEFAULT NULL::uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_caller UUID := auth.uid();
  v_is_authorized BOOLEAN := false;
BEGIN
  IF v_caller IS NULL THEN
    RAISE EXCEPTION 'Authentication required.';
  END IF;

  IF v_caller = p_target_user_id THEN
    v_is_authorized := true;
  ELSIF public.is_platform_operator() THEN
    v_is_authorized := true;
  ELSIF p_org_id IS NOT NULL AND EXISTS (
    SELECT 1 FROM public.organization_memberships
    WHERE organization_id = p_org_id
      AND user_id = v_caller
      AND role IN ('organization_owner', 'organization_admin')
      AND is_active = true
  ) THEN
    v_is_authorized := true;
  END IF;

  IF NOT v_is_authorized THEN
    RAISE EXCEPTION 'Access denied: not authorized to reset wizard progress.';
  END IF;

  UPDATE public.wizard_user_progress
  SET
    status = 'not_started',
    current_step_index = 0,
    completed_step_ids = '[]'::jsonb,
    skipped_step_ids = '[]'::jsonb,
    reset_at = now(),
    completed_at = NULL,
    last_activity_at = now(),
    updated_at = now()
  WHERE user_id = p_target_user_id
    AND ((p_org_id IS NULL AND organization_id IS NULL) OR organization_id = p_org_id)
    AND wizard_id = p_wizard_id;

  RETURN true;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.resolve_account_context()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_is_operator boolean;
  v_roles text[];
  v_perms text[];
  v_session jsonb;
  v_memberships jsonb;
  v_primary_org uuid;
  v_member_count int;
  v_operational_count int;
  v_dest text;
  v_top_role text;
BEGIN
  IF v_uid IS NULL THEN
    RETURN jsonb_build_object('is_platform_operator', false, 'recommended_destination', '/login');
  END IF;
  v_is_operator := public.is_platform_operator(v_uid);

  SELECT array_agg(DISTINCT pra.platform_role::text) INTO v_roles
  FROM public.platform_users pu
  JOIN public.platform_role_assignments pra ON pra.platform_user_id = pu.user_id
  WHERE pu.user_id = v_uid AND pu.is_active AND pra.revoked_at IS NULL;

  SELECT array_agg(p) INTO v_perms
  FROM (SELECT unnest(ARRAY['operator.manage','tenant.manage','billing.manage','master_content.manage',
                            'ops.manage','config.manage','tenant.enter','tenant.read']) AS p) cand
  WHERE public.platform_operator_can(cand.p, v_uid);

  SELECT to_jsonb(s) INTO v_session FROM (
    SELECT pas.id, pas.target_organization_id, pas.acting_role, pas.access_reason,
           pas.started_at, pas.expires_at, o.name AS target_organization_name
    FROM public.platform_access_sessions pas
    JOIN public.organizations o ON o.id = pas.target_organization_id
    WHERE pas.admin_user_id = v_uid AND pas.is_active = true
      AND (pas.ended_at IS NULL OR pas.ended_at > now()) AND pas.expires_at > now()
    ORDER BY pas.started_at DESC LIMIT 1
  ) s;

  SELECT jsonb_agg(jsonb_build_object(
           'organization_id', om.organization_id, 'organization_name', o.name, 'role', om.role::text,
           'brand_id', om.brand_id, 'hotel_id', om.hotel_id, 'hotel_name', h.name,
           'department_id', om.department_id, 'department_name', d.name, 'is_active', om.is_active,
           'lifecycle_status', o.lifecycle_status,
           'operational', public.org_is_operational(om.organization_id)
         ) ORDER BY om.is_primary DESC, o.name),
         count(*),
         count(*) FILTER (WHERE public.org_is_operational(om.organization_id)),
         (array_agg(om.organization_id ORDER BY om.is_primary DESC, o.name))[1]
    INTO v_memberships, v_member_count, v_operational_count, v_primary_org
  FROM public.organization_memberships om
  JOIN public.organizations o ON o.id = om.organization_id
  LEFT JOIN public.hotels h ON h.id = om.hotel_id
  LEFT JOIN public.departments d ON d.id = om.department_id
  WHERE om.user_id = v_uid AND om.is_active = true;

  SELECT om.role::text INTO v_top_role
  FROM public.organization_memberships om
  JOIN public.organizations o ON o.id = om.organization_id
  WHERE om.user_id = v_uid AND om.is_active = true AND public.org_is_operational(om.organization_id)
  ORDER BY CASE om.role::text
    WHEN 'organization_owner' THEN 0 WHEN 'organization_admin' THEN 1 WHEN 'brand_admin' THEN 2
    WHEN 'hotel_admin' THEN 3 WHEN 'department_manager' THEN 4 WHEN 'training_manager' THEN 5
    WHEN 'instructor' THEN 6 WHEN 'knowledge_manager' THEN 7 WHEN 'author' THEN 8 ELSE 9 END
  LIMIT 1;

  IF v_is_operator THEN
    v_dest := '/platform';
    -- A platform operator operates on the global plane; primary_organization_id is null
    -- unless an active break-glass impersonation session is underway.
    IF v_session IS NOT NULL THEN
      v_primary_org := (v_session->>'target_organization_id')::uuid;
    ELSE
      v_primary_org := NULL;
    END IF;
  ELSIF v_member_count > 0 AND v_operational_count = 0 THEN
    v_dest := '/suspended';
  ELSIF v_top_role IN ('organization_owner','organization_admin','brand_admin','hotel_admin') THEN
    v_dest := '/admin';
  ELSIF v_top_role IN ('training_manager','instructor') THEN
    v_dest := '/training';
  ELSIF v_top_role IN ('knowledge_manager','author') THEN
    v_dest := '/knowledge';
  ELSE
    v_dest := '/home/learner';
  END IF;

  RETURN jsonb_build_object(
    'user_id', v_uid,
    'is_platform_operator', v_is_operator,
    'platform_roles', COALESCE(to_jsonb(v_roles), '[]'::jsonb),
    'platform_permissions', COALESCE(to_jsonb(v_perms), '[]'::jsonb),
    'active_platform_session', v_session,
    'tenant_memberships', COALESCE(v_memberships, '[]'::jsonb),
    'primary_organization_id', v_primary_org,
    'is_multi_org', COALESCE(v_member_count, 0) > 1,
    'all_orgs_suspended', (COALESCE(v_member_count,0) > 0 AND COALESCE(v_operational_count,0) = 0),
    'recommended_destination', v_dest
  );
END;
$function$
;

CREATE OR REPLACE FUNCTION public.resolve_training_certificate_progress(p_user_id uuid, p_training_module_id uuid, p_completion_date timestamp with time zone DEFAULT NULL::timestamp with time zone)
 RETURNS uuid
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  SELECT tp.id
  FROM public.training_progress tp
  WHERE tp.user_id = p_user_id
    AND tp.training_id = p_training_module_id
    AND coalesce(tp.is_deleted, false) = false
  ORDER BY
    CASE WHEN tp.status = 'completed' THEN 0 ELSE 1 END,
    ABS(EXTRACT(EPOCH FROM (
      coalesce(tp.completed_at, tp.updated_at, tp.created_at) - coalesce(p_completion_date, coalesce(tp.completed_at, tp.updated_at, tp.created_at))
    ))) ASC NULLS LAST,
    coalesce(tp.completed_at, tp.updated_at, tp.created_at) DESC
  LIMIT 1;
$function$
;

CREATE OR REPLACE FUNCTION public.resolve_training_module_write_target(p_module_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE
  v_module RECORD;
  v_target uuid;
BEGIN
  SELECT id, title, status, is_active, is_deleted, property_id, department_id
  INTO v_module
  FROM public.training_modules
  WHERE id = p_module_id;

  IF NOT FOUND THEN
    RETURN NULL;
  END IF;

  IF COALESCE(v_module.is_deleted, false) = false
     AND COALESCE(v_module.is_active, true) = true
     AND COALESCE(v_module.status, 'draft') <> 'archived' THEN
    RETURN v_module.id;
  END IF;

  SELECT tm.id
  INTO v_target
  FROM public.training_modules tm
  WHERE tm.id <> v_module.id
    AND tm.title = v_module.title
    AND COALESCE(tm.is_deleted, false) = false
    AND COALESCE(tm.is_active, true) = true
    AND COALESCE(tm.status, 'draft') <> 'archived'
    AND tm.property_id IS NOT DISTINCT FROM v_module.property_id
    AND tm.department_id IS NOT DISTINCT FROM v_module.department_id
  ORDER BY tm.updated_at DESC NULLS LAST
  LIMIT 1;

  RETURN v_target;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.retry_course_generation_job(p_job_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NOT (public.is_platform_operator() AND public.platform_operator_can('system.manage')) THEN
    RAISE EXCEPTION 'Access denied: platform operator with system.manage capability required'
      USING ERRCODE = '42501';
  END IF;

  UPDATE public.course_generation_jobs
  SET status = 'pending', error_message = NULL, updated_at = now()
  WHERE id = p_job_id;

  RETURN FOUND;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.retry_failed_job(p_job_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_caller_id uuid := auth.uid();
  v_is_platform boolean;
BEGIN
  SELECT public.is_platform_user(v_caller_id) INTO v_is_platform;
  IF NOT v_is_platform THEN
    RAISE EXCEPTION 'Access Denied: Only platform administrators can retry system jobs.';
  END IF;

  UPDATE public.course_generation_jobs
  SET status = 'pending',
      error_message = NULL,
      updated_at = NOW()
  WHERE id = p_job_id;

  INSERT INTO public.platform_audit_logs (
    actor_id,
    action,
    resource_type,
    resource_id,
    metadata
  ) VALUES (
    v_caller_id,
    'retry_background_job',
    'course_generation_job',
    p_job_id::text,
    jsonb_build_object('retried_at', NOW())
  );

  RETURN true;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.revoke_all_other_sessions(p_user_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
    IF coalesce(auth.role(), '') <> 'service_role' AND auth.uid() IS DISTINCT FROM p_user_id THEN
      RAISE EXCEPTION 'Users can only revoke their own sessions';
    END IF;

    UPDATE public.user_sessions SET revoked_at = now(), revoked_reason = 'revoke_all_other'
    WHERE user_id = p_user_id AND is_current = false AND revoked_at IS NULL;
    INSERT INTO public.system_events (event_type, actor_id, entity_type, entity_id, metadata)
    VALUES ('security', p_user_id, 'user', p_user_id,
        jsonb_build_object('security_event_type', 'session.revoke_all_other', 'severity', 'info',
            'count', (SELECT count(*) FROM public.user_sessions WHERE user_id = p_user_id AND revoked_at IS NOT NULL)));
    RETURN true;
END; $function$
;

CREATE OR REPLACE FUNCTION public.revoke_platform_role(p_user_id uuid, p_role text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NOT (public.platform_operator_has_role('platform_admin') OR public.platform_operator_has_role('system_owner')) THEN
    RAISE EXCEPTION 'Only platform admins may revoke platform roles' USING ERRCODE = '42501';
  END IF;
  UPDATE public.platform_role_assignments SET revoked_at = now(), revoked_by = auth.uid()
   WHERE platform_user_id = p_user_id AND platform_role = p_role::public.platform_role AND revoked_at IS NULL;
  INSERT INTO public.platform_audit_logs (actor_id, action, resource_type, resource_id, metadata)
  VALUES (auth.uid(), 'revoke_platform_role', 'platform_role_assignment', p_user_id::text,
          jsonb_build_object('target_user', p_user_id, 'role', p_role));
END;
$function$
;

CREATE OR REPLACE FUNCTION public.revoke_session(p_session_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
    UPDATE public.user_sessions SET revoked_at = now(), revoked_reason = 'user_initiated'
    WHERE id = p_session_id AND user_id = auth.uid();
    IF FOUND THEN
        INSERT INTO public.system_events (event_type, actor_id, entity_type, entity_id, metadata)
        VALUES ('security', auth.uid(), 'session', p_session_id,
            jsonb_build_object('security_event_type', 'session.revoked', 'severity', 'info', 'session_id', p_session_id));
        RETURN true;
    END IF;
    RETURN false;
END; $function$
;

CREATE OR REPLACE FUNCTION public.roles_satisfying(_role app_role)
 RETURNS app_role[]
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  SELECT ARRAY(
    SELECT DISTINCT r FROM (
      SELECT _role AS r
      UNION ALL SELECT legacy_role   FROM platform_role_map        WHERE platform_role = _role
      UNION ALL SELECT legacy_role   FROM platform_role_map_extra  WHERE platform_role = _role
      UNION ALL SELECT platform_role FROM platform_role_map        WHERE legacy_role   = _role
      UNION ALL SELECT 'administrator'::app_role
      UNION ALL SELECT 'training_manager'::app_role
        WHERE _role IN ('author','knowledge_manager','learner')
      UNION ALL SELECT 'knowledge_manager'::app_role WHERE _role = 'learner'
      UNION ALL SELECT 'author'::app_role            WHERE _role = 'learner'
      UNION ALL SELECT 'super_admin'::app_role
      UNION ALL SELECT 'corporate_admin'::app_role WHERE _role <> 'super_admin'
    ) s
  );
$function$
;

CREATE OR REPLACE FUNCTION public.safe_notification_type(p_value text, p_default notification_type DEFAULT 'system'::notification_type)
 RETURNS notification_type
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
  v_value text;
begin
  v_value := lower(trim(coalesce(p_value, '')));
  if v_value = '' then
    return p_default;
  end if;

  begin
    return v_value::public.notification_type;
  exception when others then
    return p_default;
  end;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.sanitize_search_input(p_input text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
SELECT regexp_replace(
    regexp_replace(
        regexp_replace(
            COALESCE(p_input, ''),
            '[^a-zA-Z0-9\s\-_@.]', '', 'g'  -- Remove special characters
        ),
        '\s+', ' ', 'g'  -- Normalize whitespace
    ),
    '^\s+|\s+$', '', 'g'  -- Trim
);
$function$
;

CREATE OR REPLACE FUNCTION public.save_password_history()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NEW.encrypted_password <> OLD.encrypted_password THEN
    INSERT INTO public.password_history (user_id, password_hash)
    VALUES (NEW.id, NEW.encrypted_password);
  END IF;
  RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.scan_source_change_flags()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_inserted integer;
  v_count integer;
BEGIN
  WITH stale AS (
    SELECT
      csd.training_module_id,
      csd.document_id,
      d.updated_at            AS source_updated_at,
      tm.last_reviewed_at     AS course_last_reviewed_at
    FROM public.course_source_documents csd
    JOIN public.documents d          ON d.id = csd.document_id
    JOIN public.training_modules tm  ON tm.id = csd.training_module_id
    WHERE csd.relationship = 'source'
      AND tm.is_deleted IS NOT TRUE
      AND d.updated_at > COALESCE(tm.last_reviewed_at, tm.created_at)
  ),
  ins AS (
    INSERT INTO public.source_change_flags (
      training_module_id, document_id, source_updated_at, course_last_reviewed_at
    )
    SELECT training_module_id, document_id, source_updated_at, course_last_reviewed_at
    FROM stale
    ON CONFLICT (training_module_id, document_id, source_updated_at) DO NOTHING
    RETURNING 1
  )
  SELECT count(*) INTO v_count FROM ins;

  RETURN COALESCE(v_count, 0);
END;
$function$
;

CREATE OR REPLACE FUNCTION public.search_knowledge_articles(p_query text DEFAULT NULL::text, p_content_type text DEFAULT NULL::text, p_status text DEFAULT 'PUBLISHED'::text, p_department_id uuid DEFAULT NULL::uuid, p_property_id uuid DEFAULT NULL::uuid, p_requires_acknowledgment boolean DEFAULT NULL::boolean, p_limit integer DEFAULT 20, p_offset integer DEFAULT 0)
 RETURNS TABLE(id uuid, rank real, total_count bigint)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
    SELECT
        d.id,
        CASE WHEN p_query IS NOT NULL AND btrim(p_query) <> ''
            THEN ts_rank_cd(d.search_vector, websearch_to_tsquery('english', p_query), 32)
            ELSE 0
        END AS rank,
        count(*) OVER() AS total_count
    FROM public.documents d
    WHERE d.is_deleted = false
        AND d.is_archived = false
        AND (
          public.is_platform_super_admin()
          OR COALESCE(d.is_master_template, false) = true
          OR public.org_visible(d.organization_id)
        )
        AND (p_status IS NULL OR d.status::text = p_status)
        AND d.knowledge_base_status = 'indexed'
        AND d.is_active_kb_version = true
        AND (p_query IS NULL OR btrim(p_query) = '' OR d.search_vector @@ websearch_to_tsquery('english', p_query))
        AND (p_content_type IS NULL OR lower(d.content_type) = lower(p_content_type))
        AND (p_department_id IS NULL OR d.department_id = p_department_id)
        AND (p_property_id IS NULL OR d.property_id IS NULL OR d.property_id = p_property_id)
        AND (p_requires_acknowledgment IS NULL OR d.requires_acknowledgment = p_requires_acknowledgment)
    ORDER BY rank DESC, d.updated_at DESC
    LIMIT p_limit OFFSET p_offset;
$function$
;

CREATE OR REPLACE FUNCTION public.secure_search_documents(p_search_query text, p_property_id uuid DEFAULT NULL::uuid, p_folder_id uuid DEFAULT NULL::uuid, p_status text DEFAULT NULL::text, p_visibility text DEFAULT NULL::text, p_department_id uuid DEFAULT NULL::uuid, p_file_type text[] DEFAULT NULL::text[], p_date_from timestamp with time zone DEFAULT NULL::timestamp with time zone, p_date_to timestamp with time zone DEFAULT NULL::timestamp with time zone, p_confidentiality_level text DEFAULT NULL::text, p_include_deleted boolean DEFAULT false, p_include_archived boolean DEFAULT false, p_sort_by text DEFAULT 'created_at'::text, p_sort_order text DEFAULT 'desc'::text, p_limit integer DEFAULT 100, p_offset integer DEFAULT 0)
 RETURNS TABLE(id uuid, title text, description text, content text, file_url text, status text, visibility text, property_id uuid, department_id uuid, folder_id uuid, file_type text, file_size bigint, file_extension text, confidentiality_level text, is_deleted boolean, is_archived boolean, created_by uuid, created_at timestamp with time zone, updated_at timestamp with time zone, expires_at timestamp with time zone, view_count integer, download_count integer, content_type text, author jsonb)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_user_id UUID := auth.uid();
    v_is_admin BOOLEAN;
    v_sort_column TEXT;
BEGIN
    v_sort_column := CASE WHEN p_sort_by IN ('created_at','updated_at','title','file_size','view_count') THEN p_sort_by ELSE 'created_at' END;
    v_is_admin := public.is_platform_super_admin();

    RETURN QUERY
    SELECT d.id, d.title, d.description, d.content, d.file_url, d.status::TEXT, d.visibility::TEXT,
           d.property_id, d.department_id, d.folder_id, d.file_type, d.file_size, d.file_extension,
           d.confidentiality_level::TEXT, d.is_deleted, d.is_archived, d.created_by, d.created_at,
           d.updated_at, d.expires_at, d.view_count, d.download_count, d.content_type,
           jsonb_build_object('id', p.id, 'full_name', p.full_name, 'avatar_url', p.avatar_url) AS author
    FROM documents d
    LEFT JOIN profiles p ON d.created_by = p.id
    WHERE
        (p_search_query IS NULL OR p_search_query = '' OR
            (d.title ILIKE '%'||p_search_query||'%' OR d.description ILIKE '%'||p_search_query||'%' OR d.content ILIKE '%'||p_search_query||'%'))
        AND (p_folder_id IS NULL OR d.folder_id = p_folder_id)
        AND (p_status IS NULL OR d.status::TEXT = p_status)
        AND (p_visibility IS NULL OR d.visibility::TEXT = p_visibility)
        AND (p_department_id IS NULL OR d.department_id = p_department_id)
        AND (p_file_type IS NULL OR p_file_type = '{}' OR d.file_type = ANY(p_file_type))
        AND (p_date_from IS NULL OR d.created_at >= p_date_from)
        AND (p_date_to IS NULL OR d.created_at <= p_date_to)
        AND (p_confidentiality_level IS NULL OR d.confidentiality_level::TEXT = p_confidentiality_level)
        AND (p_include_deleted = TRUE OR d.is_deleted = FALSE)
        AND (p_include_archived = TRUE OR d.is_archived = FALSE)
        AND (v_is_admin OR COALESCE(d.is_master_template,false) OR public.org_visible(d.organization_id))
        AND (
            v_is_admin
            OR d.created_by = v_user_id
            OR d.owner_id = v_user_id
            OR (d.status = 'PUBLISHED' AND (
                    d.visibility = 'all_properties'
                    OR (d.visibility = 'department' AND EXISTS (
                        SELECT 1 FROM organization_memberships om
                        WHERE om.user_id = v_user_id AND om.is_active = true AND om.department_id = d.department_id
                    ))
                    OR (d.visibility = 'role' AND EXISTS (SELECT 1 FROM user_roles ur WHERE ur.user_id = v_user_id AND ur.role::TEXT = d.role::TEXT))
               ))
        )
    ORDER BY
        CASE v_sort_column WHEN 'title' THEN d.title ELSE NULL END ASC NULLS LAST,
        CASE v_sort_column WHEN 'created_at' THEN d.created_at::TEXT WHEN 'updated_at' THEN d.updated_at::TEXT ELSE NULL END::TIMESTAMPTZ DESC NULLS LAST
    LIMIT LEAST(p_limit, 500) OFFSET GREATEST(p_offset, 0);
END;
$function$
;

CREATE OR REPLACE FUNCTION public.secure_search_tasks(p_search_query text DEFAULT NULL::text, p_status text[] DEFAULT NULL::text[], p_priority text[] DEFAULT NULL::text[], p_assigned_to uuid DEFAULT NULL::uuid, p_created_by uuid DEFAULT NULL::uuid, p_property_id uuid DEFAULT NULL::uuid, p_department_id uuid DEFAULT NULL::uuid, p_limit integer DEFAULT 100, p_offset integer DEFAULT 0)
 RETURNS TABLE(id uuid, title text, description text, status text, priority text, assigned_to_id uuid, created_by_id uuid, property_id uuid, department_id uuid, due_date timestamp with time zone, created_at timestamp with time zone, updated_at timestamp with time zone, is_deleted boolean)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_user_id UUID := auth.uid();
    v_is_platform BOOLEAN;
    v_user_org_ids UUID[];
BEGIN
    IF v_user_id IS NULL THEN
        RETURN;
    END IF;

    v_is_platform := public.is_platform_super_admin();
    v_user_org_ids := public.current_user_organization_ids();

    RETURN QUERY
    SELECT 
        t.id,
        t.title,
        t.description,
        t.status::TEXT,
        t.priority::TEXT,
        t.assigned_to_id,
        t.created_by_id,
        t.property_id,
        t.department_id,
        t.due_date,
        t.created_at,
        t.updated_at,
        t.is_deleted
    FROM public.tasks t
    LEFT JOIN public.hotels h ON h.id = t.property_id
    WHERE t.is_deleted = FALSE
        AND (p_search_query IS NULL OR p_search_query = '' OR 
            (t.title ILIKE '%' || p_search_query || '%' OR
             t.description ILIKE '%' || p_search_query || '%'))
        AND (p_status IS NULL OR p_status = '{}' OR t.status::TEXT = ANY(p_status))
        AND (p_priority IS NULL OR p_priority = '{}' OR t.priority::TEXT = ANY(p_priority))
        AND (p_assigned_to IS NULL OR t.assigned_to_id = p_assigned_to)
        AND (p_created_by IS NULL OR t.created_by_id = p_created_by)
        AND (p_property_id IS NULL OR t.property_id = p_property_id)
        AND (p_department_id IS NULL OR t.department_id = p_department_id)
        -- HARD MULTI-TENANT BOUNDARY:
        AND (
            v_is_platform
            OR (
                h.organization_id = ANY(v_user_org_ids)
                AND public.org_is_operational(h.organization_id)
            )
            OR (
                t.assigned_to_id = v_user_id
                OR t.created_by_id = v_user_id
            )
        )
    ORDER BY t.created_at DESC
    LIMIT LEAST(p_limit, 500)
    OFFSET GREATEST(p_offset, 0);
END;
$function$
;

CREATE OR REPLACE FUNCTION public.secure_search_users(p_search_query text, p_property_id uuid DEFAULT NULL::uuid, p_department_id uuid DEFAULT NULL::uuid, p_role text DEFAULT NULL::text, p_is_active boolean DEFAULT true, p_limit integer DEFAULT 50)
 RETURNS TABLE(id uuid, email text, full_name text, phone text, job_title text, staff_id text, avatar_url text, is_active boolean, hire_date date, created_at timestamp with time zone)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_user_id UUID := auth.uid();
    v_is_platform BOOLEAN;
    v_user_org_ids UUID[];
BEGIN
    IF v_user_id IS NULL THEN
        RETURN;
    END IF;

    v_is_platform := public.is_platform_super_admin();
    v_user_org_ids := public.current_user_organization_ids();

    RETURN QUERY
    SELECT DISTINCT
        p.id, p.email, p.full_name, p.phone, p.job_title, p.staff_id, p.avatar_url,
        p.is_active, p.hire_date, p.created_at
    FROM public.profiles p
    LEFT JOIN public.organization_memberships om ON om.user_id = p.id AND om.is_active = true
    WHERE
        (p_search_query IS NULL OR p_search_query = '' OR 
            (p.full_name ILIKE '%' || p_search_query || '%' OR
             p.email ILIKE '%' || p_search_query || '%' OR
             p.job_title ILIKE '%' || p_search_query || '%' OR
             p.staff_id ILIKE '%' || p_search_query || '%'))
        AND (p_is_active IS NULL OR p.is_active = p_is_active)
        -- Property (hotel) filter -- organization_memberships.hotel_id is the current
        -- source of truth; the dead user_properties fallback EXISTS is gone.
        AND (p_property_id IS NULL OR EXISTS (
            SELECT 1 FROM public.organization_memberships om2
            WHERE om2.user_id = p.id AND om2.is_active = true AND om2.hotel_id = p_property_id
        ))
        -- Department filter
        AND (p_department_id IS NULL OR EXISTS (
            SELECT 1 FROM public.organization_memberships om3
            WHERE om3.user_id = p.id AND om3.is_active = true AND om3.department_id = p_department_id
        ))
        -- Role filter
        AND (p_role IS NULL OR om.role::text = p_role OR EXISTS (
            SELECT 1 FROM public.user_roles ur 
            WHERE ur.user_id = p.id AND ur.role::TEXT = p_role
        ))
        AND (
            v_is_platform
            OR p.id = v_user_id
            OR (
                om.organization_id = ANY(v_user_org_ids)
                AND public.org_is_operational(om.organization_id)
            )
        )
    ORDER BY p.full_name ASC NULLS LAST
    LIMIT LEAST(p_limit, 200);
END;
$function$
;

CREATE OR REPLACE FUNCTION public.seed_default_scheduled_reports()
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_admin_id uuid := auth.uid();
BEGIN
  IF v_admin_id IS NULL THEN
    SELECT id INTO v_admin_id FROM public.profiles LIMIT 1;
  END IF;

  -- Default 1: Monthly Saudization Report
  IF NOT EXISTS (SELECT 1 FROM public.scheduled_compliance_reports WHERE report_name = 'Monthly Saudization Compliance Report') THEN
    INSERT INTO public.scheduled_compliance_reports (
      report_name,
      description,
      report_type,
      schedule_cron,
      schedule_timezone,
      report_scope,
      format,
      template_name,
      delivery_config,
      created_by,
      recipient_roles,
      is_active
    ) VALUES (
      'Monthly Saudization Compliance Report',
      'Automated Nitaqat and Saudization metrics by property and department.',
      'saudization',
      '0 8 1 * *',
      'Asia/Riyadh',
      jsonb_build_object('scope_type', 'all_properties'),
      'pdf',
      'standard_saudization',
      jsonb_build_object('include_attachment', true, 'email_subject', 'Monthly Saudization Compliance Report'),
      v_admin_id,
      ARRAY['corporate_admin', 'regional_admin', 'regional_hr'],
      true
    );
  END IF;

  -- Default 2: Quarterly Training Compliance
  IF NOT EXISTS (SELECT 1 FROM public.scheduled_compliance_reports WHERE report_name = 'Quarterly Training Compliance Audit') THEN
    INSERT INTO public.scheduled_compliance_reports (
      report_name,
      description,
      report_type,
      schedule_cron,
      schedule_timezone,
      report_scope,
      format,
      template_name,
      delivery_config,
      created_by,
      recipient_roles,
      is_active
    ) VALUES (
      'Quarterly Training Compliance Audit',
      'Quarterly overview of mandatory training module completions and expiring certifications.',
      'training_compliance',
      '0 8 1 1,4,7,10 *',
      'Asia/Riyadh',
      jsonb_build_object('scope_type', 'all_properties'),
      'xlsx',
      'standard_training',
      jsonb_build_object('include_attachment', true, 'email_subject', 'Quarterly Training Compliance Report'),
      v_admin_id,
      ARRAY['corporate_admin', 'regional_admin', 'department_head'],
      true
    );
  END IF;

  -- Default 3: Security & Access Audit Export
  IF NOT EXISTS (SELECT 1 FROM public.scheduled_compliance_reports WHERE report_name = 'Monthly Security & Access Audit Export') THEN
    INSERT INTO public.scheduled_compliance_reports (
      report_name,
      description,
      report_type,
      schedule_cron,
      schedule_timezone,
      report_scope,
      format,
      template_name,
      delivery_config,
      created_by,
      recipient_roles,
      is_active
    ) VALUES (
      'Monthly Security & Access Audit Export',
      'Comprehensive security event, PII access, and role change audit trail.',
      'security_audit',
      '0 6 1 * *',
      'Asia/Riyadh',
      jsonb_build_object('scope_type', 'all_properties'),
      'json',
      'standard_security',
      jsonb_build_object('include_attachment', true, 'email_subject', 'Monthly Security Audit Log'),
      v_admin_id,
      ARRAY['corporate_admin'],
      true
    );
  END IF;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.set_ai_provider_health(p_provider text, p_status text, p_cooldown_seconds integer DEFAULT NULL::integer)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF coalesce(auth.role(), '') <> 'service_role' AND NOT public.is_platform_super_admin() THEN
    RAISE EXCEPTION 'Not authorized' USING ERRCODE = '42501';
  END IF;
  UPDATE public.ai_providers
     SET health_status = p_status,
         cooldown_until = CASE WHEN p_cooldown_seconds IS NULL THEN NULL
                               ELSE now() + make_interval(secs => p_cooldown_seconds) END,
         updated_at = now()
   WHERE id::text = p_provider OR name = p_provider;
END $function$
;

CREATE OR REPLACE FUNCTION public.set_announcement_child_org()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_org uuid;
BEGIN
  IF NEW.announcement_id IS NOT NULL THEN
    SELECT a.organization_id INTO v_org FROM public.announcements a WHERE a.id = NEW.announcement_id;
  END IF;

  IF v_org IS NULL THEN
    RAISE EXCEPTION 'Cannot resolve organization for % — announcement % missing or has no organization_id',
      TG_TABLE_NAME, NEW.announcement_id USING ERRCODE = '23502';
  END IF;

  IF NEW.organization_id IS NOT NULL AND NEW.organization_id <> v_org THEN
    RAISE EXCEPTION 'Cross-tenant violation: child organization_id (%) does not match parent (%)',
      NEW.organization_id, v_org USING ERRCODE = '42501';
  END IF;

  NEW.organization_id := v_org;
  RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.set_certificate_identifiers()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NEW.certificate_number IS NULL THEN
    NEW.certificate_number := generate_certificate_number();
  END IF;
  IF NEW.verification_code IS NULL THEN
    NEW.verification_code := generate_verification_code();
  END IF;
  RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.set_document_internal(p_document_id uuid, p_user_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_guard_org uuid;
BEGIN
    SELECT organization_id INTO v_guard_org FROM public.documents WHERE id = p_document_id;
    IF NOT (public.is_platform_super_admin() OR public._p7_is_service_context()
            OR public.is_tenant_admin(v_guard_org) OR public.is_tenant_content_editor(v_guard_org)) THEN
      RAISE EXCEPTION 'not authorized for organization %', v_guard_org USING ERRCODE = '42501';
    END IF;

    UPDATE public.documents
    SET
        status = 'APPROVED'::document_status,
        knowledge_base_status = 'excluded',
        is_active_kb_version = false,
        reviewed_by = p_user_id,
        reviewed_at = NOW(),
        updated_at = NOW(),
        updated_by = p_user_id
    WHERE id = p_document_id;

    IF NOT FOUND THEN
        RETURN jsonb_build_object('success', false, 'error', 'Document not found');
    END IF;

    RETURN jsonb_build_object('success', true, 'document_id', p_document_id);
END;
$function$
;

CREATE OR REPLACE FUNCTION public.set_documents_child_org()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_fk text := TG_ARGV[0];
  v_fkval uuid;
  v_org uuid;
BEGIN
  EXECUTE format('SELECT ($1).%I', v_fk) INTO v_fkval USING NEW;
  IF v_fkval IS NOT NULL THEN
    SELECT d.organization_id INTO v_org FROM public.documents d WHERE d.id = v_fkval;
  END IF;

  IF v_org IS NULL THEN
    RAISE EXCEPTION 'Cannot resolve organization for % via documents.% = % — parent document missing or has no organization_id',
      TG_TABLE_NAME, v_fk, v_fkval USING ERRCODE = '23502';
  END IF;

  IF NEW.organization_id IS NOT NULL AND NEW.organization_id <> v_org THEN
    RAISE EXCEPTION 'Cross-tenant violation: child organization_id (%) does not match parent (%)',
      NEW.organization_id, v_org USING ERRCODE = '42501';
  END IF;

  NEW.organization_id := v_org;
  RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.set_feature_flag_default(p_key text, p_enabled boolean)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NOT (public.is_platform_operator() AND public.platform_operator_can('config.manage')) THEN
    RAISE EXCEPTION 'config.manage required' USING ERRCODE = '42501';
  END IF;
  UPDATE public.platform_feature_flags SET default_enabled = p_enabled, updated_at = now(), updated_by = auth.uid()
   WHERE key = p_key;
  INSERT INTO public.platform_audit_logs (actor_id, action, resource_type, resource_id, metadata)
  VALUES (auth.uid(), 'set_feature_flag_default', 'feature_flag', p_key, jsonb_build_object('enabled', p_enabled));
END;
$function$
;

CREATE OR REPLACE FUNCTION public.set_leave_requests_updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  NEW.updated_at = now();
  RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.set_messaging_message_org()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_org uuid;
BEGIN
  IF NEW.organization_id IS NOT NULL THEN
    RETURN NEW;
  END IF;

  IF NEW.department_id IS NOT NULL THEN
    SELECT d.organization_id INTO v_org
    FROM public.departments d
    WHERE d.id = NEW.department_id;
  END IF;

  IF v_org IS NULL AND NEW.sender_id IS NOT NULL THEN
    SELECT om.organization_id INTO v_org
    FROM public.organization_memberships om
    WHERE om.user_id = NEW.sender_id
      AND om.is_active
    ORDER BY om.is_primary DESC, om.created_at ASC
    LIMIT 1;
  END IF;

  NEW.organization_id := COALESCE(v_org, (public.current_user_organization_ids())[1]);
  RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.set_messaging_org_default_lit()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NEW.organization_id IS NULL THEN
    NEW.organization_id := (public.current_user_organization_ids())[1];
  END IF;
  RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.set_messaging_org_from_parent()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_parent text := TG_ARGV[0];
  v_fk     text := TG_ARGV[1];
  v_fkval  uuid;
  v_org    uuid;
BEGIN
  IF NEW.organization_id IS NOT NULL THEN
    RETURN NEW;
  END IF;

  EXECUTE format('SELECT ($1).%I', v_fk) INTO v_fkval USING NEW;

  IF v_fkval IS NOT NULL THEN
    EXECUTE format('SELECT organization_id FROM public.%I WHERE id = $1', v_parent)
      INTO v_org USING v_fkval;
  END IF;

  NEW.organization_id := COALESCE(v_org, (public.current_user_organization_ids())[1]);
  RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.set_org_feature_override(p_org_id uuid, p_key text, p_enabled boolean, p_note text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NOT (public.is_platform_operator() AND public.platform_operator_can('tenant.manage')) THEN
    RAISE EXCEPTION 'tenant.manage required' USING ERRCODE = '42501';
  END IF;
  INSERT INTO public.organization_feature_overrides (organization_id, key, enabled, note, updated_by)
  VALUES (p_org_id, p_key, p_enabled, p_note, auth.uid())
  ON CONFLICT (organization_id, key)
  DO UPDATE SET enabled = EXCLUDED.enabled, note = EXCLUDED.note, updated_by = auth.uid(), updated_at = now();
  INSERT INTO public.platform_audit_logs (actor_id, target_organization_id, action, resource_type, resource_id, metadata)
  VALUES (auth.uid(), p_org_id, 'set_org_feature_override', 'feature_flag', p_key, jsonb_build_object('enabled', p_enabled));
END;
$function$
;

CREATE OR REPLACE FUNCTION public.set_org_from_department_or_inviter()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_org uuid;
BEGIN
  IF NEW.organization_id IS NOT NULL THEN
    RETURN NEW;
  END IF;

  IF NEW.department_id IS NOT NULL THEN
    SELECT d.organization_id INTO v_org
    FROM public.departments d
    WHERE d.id = NEW.department_id;
  END IF;

  IF v_org IS NULL AND NEW.invited_by IS NOT NULL THEN
    SELECT om.organization_id INTO v_org
    FROM public.organization_memberships om
    WHERE om.user_id = NEW.invited_by
      AND om.is_active
    ORDER BY om.is_primary DESC, om.created_at ASC
    LIMIT 1;
  END IF;

  NEW.organization_id := v_org;
  RETURN NEW;
END;
$function$
;

