CREATE OR REPLACE FUNCTION public.set_organization_id_from_member()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_col text := COALESCE(TG_ARGV[0], 'user_id');
  v_uid uuid;
  v_org uuid;
BEGIN
  IF NEW.organization_id IS NOT NULL THEN
    RETURN NEW;
  END IF;

  EXECUTE format('SELECT ($1).%I', v_col) INTO v_uid USING NEW;

  IF v_uid IS NOT NULL THEN
    SELECT om.organization_id INTO v_org
    FROM public.organization_memberships om
    WHERE om.user_id = v_uid AND om.is_active
    ORDER BY om.is_primary DESC, om.created_at ASC
    LIMIT 1;

    IF v_org IS NULL AND TG_TABLE_NAME = 'profiles' THEN
      SELECT (u.raw_user_meta_data->>'organization_id')::uuid INTO v_org
      FROM auth.users u
      WHERE u.id = v_uid
        AND COALESCE(u.raw_user_meta_data->>'organization_id', '') ~ '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$';
    END IF;
  END IF;

  NEW.organization_id := v_org;
  RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.set_organization_status(p_org_id uuid, p_status text, p_reason text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_old text; v_window int;
BEGIN
  IF NOT (public.is_platform_operator() AND public.platform_operator_can('tenant.manage')) THEN
    RAISE EXCEPTION 'tenant.manage permission required' USING ERRCODE = '42501';
  END IF;
  IF p_status NOT IN ('prospect','trial','onboarding','active','suspended','renewal','archived') THEN
    RAISE EXCEPTION 'Invalid lifecycle status: %', p_status USING ERRCODE = '22023';
  END IF;
  IF p_status IN ('suspended','archived') AND (p_reason IS NULL OR length(btrim(p_reason)) < 5) THEN
    RAISE EXCEPTION 'A reason is required to suspend or archive an organization' USING ERRCODE = '22023';
  END IF;
  SELECT lifecycle_status::text INTO v_old FROM public.organizations WHERE id = p_org_id;
  IF v_old IS NULL THEN RAISE EXCEPTION 'Unknown organization' USING ERRCODE = '23503'; END IF;

  SELECT retention_days INTO v_window FROM public.data_retention_policies WHERE data_class = 'archived_org' AND is_active;

  UPDATE public.organizations SET
    lifecycle_status  = p_status::public.tenant_lifecycle_status,
    is_active         = (p_status NOT IN ('suspended','archived')),
    suspension_reason = CASE WHEN p_status IN ('suspended','archived') THEN btrim(p_reason) ELSE NULL END,
    archived_at        = CASE WHEN p_status = 'archived' THEN now() ELSE NULL END,
    purge_scheduled_at = CASE WHEN p_status = 'archived' THEN now() + (COALESCE(v_window,90) || ' days')::interval ELSE NULL END,
    updated_at = now()
  WHERE id = p_org_id;

  INSERT INTO public.platform_audit_logs (actor_id, target_organization_id, action, resource_type, resource_id, metadata)
  VALUES (auth.uid(), p_org_id, 'set_organization_status', 'organization', p_org_id::text,
          jsonb_build_object('from', v_old, 'to', p_status, 'reason', p_reason,
            'purge_scheduled_at', CASE WHEN p_status = 'archived' THEN (now() + (COALESCE(v_window,90) || ' days')::interval) END));
END;
$function$
;

CREATE OR REPLACE FUNCTION public.set_p5_child_org_from_parent()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_parent text := TG_ARGV[0];
  v_fk     text := TG_ARGV[1];
  v_fkval  uuid;
  v_org    uuid;
BEGIN
  IF NEW.organization_id IS NOT NULL THEN
    RETURN NEW;
  END IF;
  EXECUTE format('SELECT ($1).%I', v_fk) INTO v_fkval USING NEW;
  IF v_fkval IS NOT NULL THEN
    EXECUTE format('SELECT organization_id FROM public.%I WHERE id = $1', v_parent)
      INTO v_org USING v_fkval;
  END IF;
  NEW.organization_id := v_org;
  RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.set_p5_org_from_parent()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_parent text := TG_ARGV[0];
  v_fk     text := TG_ARGV[1];
  v_fkval  uuid;
  v_org    uuid;
BEGIN
  IF NEW.organization_id IS NOT NULL THEN
    RETURN NEW;
  END IF;
  EXECUTE format('SELECT ($1).%I', v_fk) INTO v_fkval USING NEW;
  IF v_fkval IS NOT NULL THEN
    EXECUTE format('SELECT organization_id FROM public.%I WHERE id = $1', v_parent)
      INTO v_org USING v_fkval;
  END IF;
  NEW.organization_id := v_org;
