CREATE OR REPLACE FUNCTION public.set_platform_user_active(p_user_id uuid, p_active boolean)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NOT (public.platform_operator_has_role('platform_admin') OR public.platform_operator_has_role('system_owner')) THEN
    RAISE EXCEPTION 'Only platform admins may change operator status' USING ERRCODE = '42501';
  END IF;
  UPDATE public.platform_users SET is_active = p_active,
         deactivated_at = CASE WHEN p_active THEN NULL ELSE now() END
   WHERE user_id = p_user_id;
  INSERT INTO public.platform_audit_logs (actor_id, action, resource_type, resource_id, metadata)
  VALUES (auth.uid(), CASE WHEN p_active THEN 'activate_platform_user' ELSE 'deactivate_platform_user' END,
          'platform_user', p_user_id::text, jsonb_build_object('target_user', p_user_id));
END;
$function$
;

CREATE OR REPLACE FUNCTION public.set_read_at_on_read()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  IF OLD.status != 'read' AND NEW.status = 'read' THEN
    NEW.read_at = now();
  END IF;
  RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.set_sent_at_on_send()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  IF OLD.status != 'sent' AND NEW.status = 'sent' THEN
    NEW.sent_at = now();
  END IF;
  RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.set_training_child_org()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_fk text := TG_ARGV[0];
  v_parent text := TG_ARGV[1];
  v_fkval uuid;
  v_org uuid;
BEGIN
  EXECUTE format('SELECT ($1).%I', v_fk) INTO v_fkval USING NEW;
  IF v_fkval IS NOT NULL THEN
    EXECUTE format('SELECT p.organization_id FROM public.%I p WHERE p.id = $1', v_parent)
      INTO v_org USING v_fkval;
  END IF;

  IF v_org IS NULL THEN
    RAISE EXCEPTION 'Cannot resolve organization for % via %.% = % — parent row missing or has no organization_id',
      TG_TABLE_NAME, v_parent, v_fk, v_fkval USING ERRCODE = '23502';
  END IF;

  IF NEW.organization_id IS NOT NULL AND NEW.organization_id <> v_org THEN
    RAISE EXCEPTION 'Cross-tenant violation: child organization_id (%) does not match parent (%)',
      NEW.organization_id, v_org USING ERRCODE = '42501';
  END IF;

  NEW.organization_id := v_org;
  RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.skip_or_complete_wizard(p_wizard_id text, p_status text, p_org_id uuid DEFAULT NULL::uuid)
 RETURNS wizard_user_progress
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_user_id UUID := auth.uid();
  v_progress public.wizard_user_progress;
BEGIN
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Authentication required.';
  END IF;

  IF p_status NOT IN ('skipped', 'completed', 'in_progress', 'reset') THEN
    RAISE EXCEPTION 'Invalid status: %', p_status;
  END IF;

  -- Update target row if it exists
  UPDATE public.wizard_user_progress
  SET
    status = p_status,
    completed_at = CASE WHEN p_status = 'completed' THEN now() ELSE completed_at END,
    last_activity_at = now(),
    updated_at = now()
  WHERE user_id = v_user_id
    AND ((p_org_id IS NULL AND organization_id IS NULL) OR organization_id = p_org_id)
    AND wizard_id = p_wizard_id
  RETURNING * INTO v_progress;

  -- If status is skipped or completed, also cascade to any other not_started rows for this user
  -- so orphaned records from intermediate role/org evaluations never re-trigger onboarding.
  IF p_status IN ('skipped', 'completed') THEN
    UPDATE public.wizard_user_progress
    SET
      status = p_status,
      completed_at = CASE WHEN p_status = 'completed' AND completed_at IS NULL THEN now() ELSE completed_at END,
      last_activity_at = now(),
      updated_at = now()
    WHERE user_id = v_user_id
      AND status = 'not_started';
  END IF;

  -- If target row was not found (e.g. org/wizard mismatch), return the user's latest progress row
  IF v_progress IS NULL THEN
    SELECT * INTO v_progress
    FROM public.wizard_user_progress
    WHERE user_id = v_user_id
    ORDER BY updated_at DESC
    LIMIT 1;
  END IF;

  RETURN v_progress;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.snapshot_training_module_version(p_module_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_next_version integer;
    v_module jsonb;
    v_blocks jsonb;
    v_version_id uuid;
    v_org uuid;
BEGIN
    SELECT organization_id INTO v_org FROM public.training_modules WHERE id = p_module_id;
    IF NOT (public._can_edit_training_module(p_module_id)
            OR (v_org IS NOT NULL AND public.can_review_training_module(v_org))) THEN
        RAISE EXCEPTION 'Not authorized to version this module';
    END IF;

    SELECT to_jsonb(m) INTO v_module FROM public.training_modules m WHERE m.id = p_module_id;
    IF v_module IS NULL THEN
        RAISE EXCEPTION 'Module not found';
    END IF;

    SELECT coalesce(jsonb_agg(to_jsonb(b) ORDER BY b."order"), '[]'::jsonb)
      INTO v_blocks
      FROM public.training_content_blocks_v b
     WHERE b.training_module_id = p_module_id AND b.is_deleted = false;

    SELECT coalesce(max(version_number), 0) + 1 INTO v_next_version
      FROM public.training_module_versions
     WHERE training_module_id = p_module_id;

    INSERT INTO public.training_module_versions (training_module_id, organization_id, version_number, snapshot, published_by)
    VALUES (p_module_id, v_org, v_next_version, jsonb_build_object('module', v_module, 'blocks', v_blocks), auth.uid())
    RETURNING id INTO v_version_id;

    RETURN v_version_id;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.start_platform_session(p_org_id uuid, p_reason text, p_acting_role text DEFAULT 'organization_admin'::text, p_ttl_minutes integer DEFAULT NULL::integer)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_session_id uuid;
  v_cfg public.platform_config;
  v_ttl integer;
BEGIN
  IF NOT (public.is_platform_operator() AND public.platform_operator_can('tenant.enter')) THEN
    RAISE EXCEPTION 'Only platform operators with tenant-entry permission may enter a tenant' USING ERRCODE = '42501';
  END IF;
  SELECT * INTO v_cfg FROM public.platform_config WHERE id;
  IF v_cfg.require_session_reason
     AND (p_reason IS NULL OR length(btrim(p_reason)) < COALESCE(v_cfg.min_session_reason_length, 10)) THEN
    RAISE EXCEPTION 'A substantive access reason (>= % chars) is required',
      COALESCE(v_cfg.min_session_reason_length, 10) USING ERRCODE = '22023';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM public.organizations WHERE id = p_org_id) THEN
    RAISE EXCEPTION 'Unknown organization' USING ERRCODE = '23503';
  END IF;
  v_ttl := LEAST(
    GREATEST(COALESCE(p_ttl_minutes, v_cfg.default_session_ttl_minutes, 30), 5),
    COALESCE(v_cfg.max_session_ttl_minutes, 480)
  );
  UPDATE public.platform_access_sessions SET is_active = false, ended_at = now()
   WHERE admin_user_id = auth.uid() AND is_active = true;
  INSERT INTO public.platform_access_sessions
    (admin_user_id, target_organization_id, acting_role, access_reason, is_active, started_at, expires_at)
  VALUES
    (auth.uid(), p_org_id, COALESCE(p_acting_role,'organization_admin'), btrim(COALESCE(p_reason,'')),
     true, now(), now() + (v_ttl || ' minutes')::interval)
  RETURNING id INTO v_session_id;
  INSERT INTO public.platform_audit_logs (actor_id, target_organization_id, session_id, action, resource_type, resource_id, metadata)
  VALUES (auth.uid(), p_org_id, v_session_id, 'enter_tenant', 'platform_access_session', v_session_id::text,
          jsonb_build_object('acting_role', p_acting_role, 'access_reason', btrim(COALESCE(p_reason,'')), 'ttl_minutes', v_ttl));
  RETURN v_session_id;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.start_recertification(p_user_id uuid, p_training_module_id uuid, p_due_date timestamp with time zone DEFAULT NULL::timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_actor uuid := auth.uid();
  v_module public.training_modules%ROWTYPE;
  v_progress public.training_progress%ROWTYPE;
  v_history_id uuid;
  v_rule_id uuid;
  v_due timestamptz := COALESCE(p_due_date, now() + interval '14 days');
BEGIN
  IF v_actor IS NULL THEN
    RAISE EXCEPTION 'Authentication required';
  END IF;

  SELECT * INTO v_module FROM public.training_modules WHERE id = p_training_module_id AND is_deleted = false;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Training module not found';
  END IF;

  IF NOT (public.is_platform_super_admin()
          OR (public.org_visible(v_module.organization_id)
              AND (public.is_tenant_content_editor(v_module.organization_id)
                   OR public.can_manage_learning_assignment(v_module.organization_id, NULL)))) THEN
    RAISE EXCEPTION 'Not authorized to recertify learners for this training';
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM public.organization_memberships om
     WHERE om.user_id = p_user_id AND om.organization_id = v_module.organization_id AND om.is_active
  ) THEN
    RAISE EXCEPTION 'Learner is not an active member of this organization';
  END IF;

  IF v_due <= now() THEN
    RAISE EXCEPTION 'Due date must be in the future';
  END IF;

  SELECT * INTO v_progress FROM public.training_progress
   WHERE user_id = p_user_id AND training_id = p_training_module_id
   FOR UPDATE;

  IF v_progress.id IS NOT NULL AND v_progress.completed_at IS NOT NULL THEN
    v_history_id := public._reset_training_cycle(v_progress.id, 'manual_recertification', v_actor);
  END IF;

  v_rule_id := public._issue_recertification_assignment(
    v_module.organization_id, p_user_id, v_module.id, v_module.title,
    v_progress.id, v_due, v_actor,
    'Recertification required for "' || v_module.title || '". Please complete it by '
      || to_char(v_due, 'YYYY-MM-DD') || '.');

  RETURN jsonb_build_object(
    'assignment_id', v_rule_id,
    'history_id', v_history_id,
    'due_date', v_due
  );
END;
$function$
;

CREATE OR REPLACE FUNCTION public.submit_quiz_attempt(p_quiz_id uuid, p_answers jsonb, p_context_type text DEFAULT 'quiz'::text, p_context_entity_id uuid DEFAULT NULL::uuid, p_assignment_id uuid DEFAULT NULL::uuid, p_time_spent_seconds integer DEFAULT 0)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_user_id uuid := auth.uid();
  v_quiz public.learning_quizzes%ROWTYPE;
  v_is_editor boolean;
  v_attempt_count integer;
  v_attempt_window_start timestamptz;
  v_session_id uuid;
  v_answer jsonb;
  v_question_id uuid;
  v_selected_options uuid[];
  v_is_correct boolean;
  v_locked boolean;
  v_attempt_number integer;
  v_correct_count integer := 0;
  v_total_count integer := 0;
  v_score numeric;
  v_passed boolean;
  v_results jsonb := '[]'::jsonb;
  v_existing public.training_progress%ROWTYPE;
  v_final_score numeric;
  v_final_passed boolean;
  v_metadata jsonb;
BEGIN
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Authentication required';
  END IF;

  SELECT * INTO v_quiz FROM public.learning_quizzes WHERE id = p_quiz_id AND is_deleted = false;
  IF NOT FOUND OR NOT (public.org_visible(v_quiz.organization_id) OR public.is_platform_super_admin()) THEN
    RAISE EXCEPTION 'Quiz not found';
  END IF;

  v_is_editor := public.is_platform_super_admin()
    OR (v_quiz.organization_id IS NOT NULL AND public.is_tenant_content_editor(v_quiz.organization_id));

  IF v_quiz.status <> 'published' AND v_quiz.created_by IS DISTINCT FROM v_user_id AND NOT v_is_editor THEN
    RAISE EXCEPTION 'Quiz is not available';
  END IF;

  SELECT count(*) INTO v_attempt_count
    FROM public.unified_quiz_sessions
   WHERE user_id = v_user_id AND quiz_type = 'learning_quiz' AND quiz_entity_id = p_quiz_id
     AND completed_at IS NOT NULL
     AND archived_at IS NULL
     AND (p_context_entity_id IS NULL OR context_entity_id IS NOT DISTINCT FROM p_context_entity_id);

  -- Per-question feedback given since the last submission of this quiz locks in.
  SELECT max(completed_at) INTO v_attempt_window_start
    FROM public.unified_quiz_sessions
   WHERE user_id = v_user_id AND quiz_type = 'learning_quiz' AND quiz_entity_id = p_quiz_id;

  IF v_quiz.max_attempts IS NOT NULL AND v_attempt_count >= v_quiz.max_attempts THEN
    RAISE EXCEPTION 'Maximum attempts reached for this quiz';
  END IF;

  INSERT INTO public.unified_quiz_sessions (
    user_id, quiz_type, quiz_entity_id, started_at, time_limit_seconds, passing_score,
    context_type, context_entity_id
  ) VALUES (
    v_user_id, 'learning_quiz', p_quiz_id,
    now() - make_interval(secs => GREATEST(COALESCE(p_time_spent_seconds, 0), 0)),
    CASE WHEN v_quiz.time_limit_minutes IS NOT NULL THEN v_quiz.time_limit_minutes * 60 ELSE NULL END,
    v_quiz.passing_score_percentage,
    p_context_type, p_context_entity_id
  ) RETURNING id INTO v_session_id;

  FOR v_answer IN SELECT * FROM jsonb_array_elements(COALESCE(p_answers, '[]'::jsonb))
  LOOP
    v_question_id := public._safe_uuid(v_answer ->> 'question_id');

    IF v_question_id IS NULL OR NOT EXISTS (
      SELECT 1 FROM public.unified_quiz_questions
       WHERE quiz_id = p_quiz_id AND question_id = v_question_id
    ) THEN
      CONTINUE;
    END IF;

    -- Each question counts once per submission.
    IF v_results @> jsonb_build_array(jsonb_build_object('question_id', v_question_id)) THEN
      CONTINUE;
    END IF;

    BEGIN
      SELECT array_agg(public._safe_uuid(x)) INTO v_selected_options
        FROM jsonb_array_elements_text(COALESCE(v_answer -> 'selected_options', '[]'::jsonb)) AS x;
    EXCEPTION WHEN others THEN
      v_selected_options := NULL;
    END;

    v_is_correct := public._grade_question_answer(
      v_question_id,
      v_answer ->> 'selected_answer',
      v_selected_options
    );

    SELECT a.is_correct INTO v_locked
      FROM public.unified_question_attempts a
     WHERE a.user_id = v_user_id
       AND a.question_id = v_question_id
       AND a.session_id IS NULL
       AND a.created_at > COALESCE(v_attempt_window_start, '-infinity'::timestamptz)
     ORDER BY a.created_at ASC
     LIMIT 1;
    IF FOUND THEN
      v_is_correct := COALESCE(v_locked, false);
    END IF;

    SELECT count(*) + 1 INTO v_attempt_number
      FROM public.unified_question_attempts
     WHERE user_id = v_user_id AND question_id = v_question_id;

    INSERT INTO public.unified_question_attempts (
      user_id, question_id, session_id, selected_answer, selected_options,
      is_correct, context_type, context_entity_id, time_spent_seconds,
      attempt_number, hint_used
    ) VALUES (
      v_user_id, v_question_id, v_session_id,
      v_answer ->> 'selected_answer', v_selected_options,
      v_is_correct, p_context_type, p_context_entity_id,
      NULLIF(v_answer ->> 'time_spent_seconds', '')::integer,
      v_attempt_number,
      COALESCE((v_answer ->> 'hint_used')::boolean, false)
    );

    v_total_count := v_total_count + 1;
    IF v_is_correct THEN
      v_correct_count := v_correct_count + 1;
    END IF;

    v_results := v_results || jsonb_build_array(jsonb_build_object('question_id', v_question_id, 'is_correct', v_is_correct));
  END LOOP;

  IF v_total_count = 0 THEN
    RAISE EXCEPTION 'No valid answers submitted for this quiz';
  END IF;

  -- Unanswered questions count as wrong: score against the whole quiz.
  v_total_count := GREATEST(v_total_count, (
    SELECT count(*) FROM public.unified_quiz_questions uqq
      JOIN public.unified_questions q ON q.id = uqq.question_id AND q.status = 'published'
     WHERE uqq.quiz_id = p_quiz_id));

  v_score := round((v_correct_count::numeric / v_total_count::numeric) * 100);
  v_passed := v_score >= COALESCE(v_quiz.passing_score_percentage, 70);

  UPDATE public.unified_quiz_sessions
     SET completed_at = now(),
         total_questions = v_total_count,
         correct_answers = v_correct_count,
         total_points = v_total_count,
         earned_points = v_correct_count,
         score_percentage = v_score,
         passed = v_passed
   WHERE id = v_session_id;

  SELECT * INTO v_existing FROM public.training_progress
   WHERE user_id = v_user_id AND training_id = p_quiz_id AND lp_content_type = 'quiz';

  -- A later failed retake must never erase a successful attempt.
  IF FOUND AND v_existing.passed IS TRUE AND v_passed IS NOT TRUE THEN
    v_final_score := v_existing.score_percentage;
    v_final_passed := v_existing.passed;
  ELSIF FOUND AND v_existing.score_percentage IS NOT NULL AND v_existing.score_percentage > v_score THEN
    v_final_score := v_existing.score_percentage;
    v_final_passed := v_existing.passed;
  ELSE
    v_final_score := v_score;
    v_final_passed := v_passed;
  END IF;

  v_metadata := COALESCE(v_existing.metadata, '{}'::jsonb) || jsonb_build_object(
    'quiz_attempt_count', v_attempt_count + 1,
    'latest_quiz_result', jsonb_build_object(
      'quiz_id', p_quiz_id,
      'quiz_title', v_quiz.title,
      'score', v_score,
      'passed', v_passed,
      'correct_count', v_correct_count,
      'total_questions', v_total_count,
      'completed_at', now(),
      'session_id', v_session_id
    )
  );

  PERFORM set_config('app.trusted_progress_write', 'on', true);

  INSERT INTO public.training_progress (
    user_id, training_id, lp_content_type, assignment_id, status,
    progress_percentage, score_percentage, passed, completed_at,
    last_accessed_at, last_activity_at, metadata, updated_at
  ) VALUES (
    v_user_id, p_quiz_id, 'quiz', p_assignment_id, 'completed',
    100, v_final_score, v_final_passed, now(),
    now(), now(), v_metadata, now()
  )
  ON CONFLICT (user_id, training_id) DO UPDATE SET
    lp_content_type = 'quiz',
    assignment_id = COALESCE(public.training_progress.assignment_id, EXCLUDED.assignment_id),
    status = 'completed',
    progress_percentage = 100,
    score_percentage = EXCLUDED.score_percentage,
    passed = EXCLUDED.passed,
    completed_at = EXCLUDED.completed_at,
    last_accessed_at = EXCLUDED.last_accessed_at,
    last_activity_at = EXCLUDED.last_activity_at,
    metadata = EXCLUDED.metadata,
    updated_at = EXCLUDED.updated_at;

  PERFORM set_config('app.trusted_progress_write', 'off', true);

  RETURN jsonb_build_object(
    'session_id', v_session_id,
    'score_percentage', v_score,
    'passed', v_passed,
    'correct_count', v_correct_count,
    'total_questions', v_total_count,
    'attempt_number', v_attempt_count + 1,
    'final_score_percentage', v_final_score,
    'final_passed', v_final_passed,
    'results', v_results
  );
END;
$function$
;

CREATE OR REPLACE FUNCTION public.submit_training_module_for_review(p_module_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_org uuid;
    v_title text;
BEGIN
    IF NOT public._can_edit_training_module(p_module_id) THEN
        RAISE EXCEPTION 'Not authorized to submit this module for review';
    END IF;

    UPDATE public.training_modules
       SET status = 'pending_review', updated_at = now(), updated_by = auth.uid()
     WHERE id = p_module_id
    RETURNING title, organization_id INTO v_title, v_org;

    IF v_title IS NULL THEN
        RAISE EXCEPTION 'Module not found';
    END IF;

    -- Notify the reviewers of this module's organization only.
    INSERT INTO public.notifications (user_id, organization_id, type, title, message, link, entity_type, entity_id)
    SELECT DISTINCT
        om.user_id, v_org,
        'training_review_requested',
        'Training module awaiting review',
        '"' || v_title || '" was submitted for review before publishing.',
        '/training/hub/' || p_module_id,
        'training_module',
        p_module_id
      FROM public.organization_memberships om
     WHERE om.organization_id = v_org
       AND om.is_active
       AND om.role IN ('organization_owner', 'organization_admin', 'training_manager')
       AND om.user_id <> auth.uid();
END;
$function$
;

CREATE OR REPLACE FUNCTION public.suggest_system_role(p_job_title text)
 RETURNS app_role
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE
  v_role app_role;
BEGIN
  SELECT system_role INTO v_role FROM job_title_role_mappings WHERE LOWER(job_title) = LOWER(p_job_title) LIMIT 1;
  IF v_role IS NOT NULL THEN RETURN v_role; END IF;
  IF p_job_title ILIKE '%manager%' OR p_job_title ILIKE '%chef%' OR p_job_title ILIKE '%supervisor%' THEN
    RETURN 'department_head'::app_role;
  ELSIF p_job_title ILIKE '%director%' OR p_job_title ILIKE '%vp%' OR p_job_title ILIKE '%vice president%' THEN
    RETURN 'regional_admin'::app_role;
  ELSIF p_job_title ILIKE '%hr%' AND (p_job_title ILIKE '%corporate%' OR p_job_title ILIKE '%regional%') THEN
    RETURN 'regional_hr'::app_role;
  ELSIF p_job_title ILIKE '%hr%' THEN
    RETURN 'property_hr'::app_role;
  ELSIF p_job_title ILIKE '%general manager%' OR p_job_title ILIKE '%gm%' THEN
    RETURN 'property_manager'::app_role;
  ELSE
    RETURN 'staff'::app_role;
  END IF;
END;
$function$
;

