CREATE OR REPLACE FUNCTION public.sync_sop_comment_upvotes()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_comment_id uuid;
begin
  v_comment_id := coalesce(new.comment_id, old.comment_id);

  update public.sop_comments c
  set upvotes = (
    select coalesce(sum(case v.vote_type when 'up' then 1 when 'down' then -1 else 0 end), 0)
    from public.sop_comment_votes v
    where v.comment_id = v_comment_id
  ),
  updated_at = now()
  where c.id = v_comment_id;

  return null;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.tg_audit_set_organization_id()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_actor uuid;
  v_org uuid;
BEGIN
  IF NEW.organization_id IS NOT NULL THEN
    RETURN NEW;
  END IF;

  IF TG_TABLE_NAME = 'system_events' THEN
    v_actor := NEW.actor_id;
  ELSE
    v_actor := NEW.user_id;
  END IF;

  -- 1. If this is analytics_events with a session_id, resolve org from user_sessions
  IF TG_TABLE_NAME = 'analytics_events' AND NEW.session_id IS NOT NULL THEN
    BEGIN
      SELECT us.organization_id INTO v_org
      FROM public.user_sessions us
      WHERE us.id = NEW.session_id::uuid;
    EXCEPTION WHEN OTHERS THEN
      v_org := NULL;
    END;
  END IF;

  -- 2. Try active tenant membership
  IF v_org IS NULL AND v_actor IS NOT NULL THEN
    SELECT om.organization_id INTO v_org
    FROM public.organization_memberships om
    WHERE om.user_id = v_actor AND om.is_active
    ORDER BY om.is_primary DESC, om.created_at ASC
    LIMIT 1;
  END IF;

  -- 3. Try profiles.organization_id
  IF v_org IS NULL AND v_actor IS NOT NULL THEN
    SELECT p.organization_id INTO v_org
    FROM public.profiles p
    WHERE p.id = v_actor AND p.organization_id IS NOT NULL;
  END IF;

  -- 4. Try any membership (including platform operators who may have inactive seeds)
  IF v_org IS NULL AND v_actor IS NOT NULL THEN
    SELECT om.organization_id INTO v_org
    FROM public.organization_memberships om
    WHERE om.user_id = v_actor
    ORDER BY om.is_primary DESC, om.created_at ASC
    LIMIT 1;
  END IF;

  -- 5. Try user_roles
  IF v_org IS NULL AND v_actor IS NOT NULL THEN
    SELECT ur.organization_id INTO v_org
    FROM public.user_roles ur
    WHERE ur.user_id = v_actor AND ur.organization_id IS NOT NULL
    LIMIT 1;
  END IF;

  -- 6. Safe fallback to the primary/first organization to satisfy NOT NULL constraint
  IF v_org IS NULL THEN
    SELECT o.id INTO v_org
    FROM public.organizations o
    ORDER BY o.created_at ASC
    LIMIT 1;
  END IF;

  NEW.organization_id := v_org;
  RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.tg_content_reviews_changelog()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_summary text;
  v_actor   uuid := COALESCE(auth.uid(), NEW.reviewed_by, NEW.submitted_by);
BEGIN
  IF TG_OP = 'INSERT' THEN
    v_summary := 'submitted for review';
  ELSIF NEW.status IS DISTINCT FROM OLD.status THEN
    v_summary := format('review status %s -> %s', OLD.status, NEW.status)
                 || COALESCE(': ' || NULLIF(btrim(NEW.review_notes), ''), '');
  ELSE
    v_summary := 'review record updated';
  END IF;

  PERFORM public.log_content_change(NEW.content_type, NEW.content_id, v_actor, v_summary);
  RETURN NEW;
END;
$function$
;

