      AND ma.is_active = true AND mb.is_active = true
  );
$function$
;

CREATE OR REPLACE FUNCTION public.validate_document_access(p_document_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_user_id UUID := auth.uid();
    v_doc RECORD;
    v_is_admin BOOLEAN;
BEGIN
    v_is_admin := EXISTS (
        SELECT 1 FROM user_roles 
        WHERE user_id = v_user_id 
        AND role IN ('regional_admin', 'regional_hr', 'corporate_admin')
    );

    SELECT * INTO v_doc
    FROM documents
    WHERE id = p_document_id AND is_deleted = FALSE;

    IF NOT FOUND THEN
        RETURN FALSE;
    END IF;

    IF v_is_admin THEN
        RETURN TRUE;
    END IF;

    IF v_doc.created_by = v_user_id OR v_doc.owner_id = v_user_id THEN
        RETURN TRUE;
    END IF;

    IF v_doc.status = 'PUBLISHED' THEN
        CASE v_doc.visibility
            WHEN 'all_properties' THEN
                RETURN TRUE;
            WHEN 'property' THEN
                RETURN public.has_property_access(v_user_id, v_doc.property_id);
            WHEN 'department' THEN
                RETURN EXISTS (
                    SELECT 1 FROM organization_memberships
                    WHERE user_id = v_user_id AND is_active = true AND department_id = v_doc.department_id
                );
            WHEN 'role' THEN
                RETURN EXISTS (
                    SELECT 1 FROM user_roles 
                    WHERE user_id = v_user_id AND role::TEXT = v_doc.role::TEXT
                );
            ELSE
                RETURN FALSE;
        END CASE;
    END IF;

    RETURN FALSE;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.validate_module_quiz_integrity(p_module_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_block record;
  v_quiz_id uuid;
  v_question_count integer;
BEGIN
  FOR v_block IN
    SELECT id, content_data, is_mandatory
      FROM public.training_content_blocks_v
     WHERE training_module_id = p_module_id AND is_deleted = false AND type = 'quiz'
  LOOP
    IF v_block.is_mandatory IS FALSE THEN
      CONTINUE;
    END IF;

    v_quiz_id := public._safe_uuid(v_block.content_data ->> 'quiz_id');
    IF v_quiz_id IS NULL THEN
      RAISE EXCEPTION 'Cannot publish: a required quiz block is not linked to a quiz';
    END IF;

    SELECT count(*) INTO v_question_count
      FROM public.unified_quiz_questions uq
      JOIN public.unified_questions q ON q.id = uq.question_id
     WHERE uq.quiz_id = v_quiz_id AND q.status = 'published';

    IF v_question_count = 0 THEN
      RAISE EXCEPTION 'Cannot publish: a required quiz has no published questions';
    END IF;
  END LOOP;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.validate_training_progress_training_id()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NEW.lp_content_type = 'module' THEN
    IF NOT EXISTS (SELECT 1 FROM public.training_modules WHERE id = NEW.training_id) THEN
      RAISE EXCEPTION 'training_progress.training_id % does not reference an existing training module', NEW.training_id;
    END IF;
  ELSIF NEW.lp_content_type = 'quiz' THEN
    IF NOT EXISTS (SELECT 1 FROM public.learning_quizzes WHERE id = NEW.training_id) THEN
      RAISE EXCEPTION 'training_progress.training_id % does not reference an existing quiz', NEW.training_id;
    END IF;
  END IF;
  -- Other content types (microlearning, onboarding_task, ...) predate this
  -- polymorphic check and are left unvalidated.
  RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.validate_uuid_array(p_input text[])
 RETURNS uuid[]
 LANGUAGE sql
 IMMUTABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
SELECT ARRAY_AGG(x::UUID)
FROM UNNEST(p_input) AS x
WHERE x ~ '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$';
$function$
;

CREATE OR REPLACE FUNCTION public.verify_certificate(verification_code_param character varying)
 RETURNS TABLE(is_valid boolean, certificate_number character varying, verification_code character varying, recipient_name character varying, title character varying, certificate_type character varying, completion_date timestamp with time zone, expiry_date timestamp with time zone, status character varying, issued_at timestamp with time zone, property_name text, department_name text, organization_name text, organization_logo_url text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  RETURN QUERY
  SELECT
    (c.status = 'active' AND (c.expiry_date IS NULL OR c.expiry_date > NOW())) as is_valid,
    c.certificate_number,
    c.verification_code,
    c.recipient_name,
    c.title,
    c.certificate_type,
    c.completion_date,
    c.expiry_date,
    c.status,
    c.created_at as issued_at,
    h.name as property_name,
    d.name as department_name,
    o.name as organization_name,
    o.logo_url as organization_logo_url
  FROM certificates c
  LEFT JOIN hotels h ON h.id = COALESCE(c.hotel_id, c.property_id)
  LEFT JOIN departments d ON d.id = c.department_id
  LEFT JOIN organizations o ON o.id = c.organization_id
  WHERE upper(c.verification_code) = upper(verification_code_param);
END;
$function$
;

CREATE OR REPLACE FUNCTION public.verify_mfa_code(p_user_id uuid, p_code text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_secret public.mfa_secrets%ROWTYPE;
  v_now bigint := extract(epoch from now())::bigint;
  v_expected text;
  v_step integer;
BEGIN
    IF auth.uid() IS DISTINCT FROM p_user_id THEN RETURN false; END IF;
    SELECT * INTO v_secret FROM public.mfa_secrets WHERE user_id = p_user_id AND enabled = true;
    IF NOT FOUND THEN RETURN false; END IF;

    IF p_code = ANY(v_secret.backup_codes) THEN
        UPDATE public.mfa_secrets SET backup_codes = array_remove(backup_codes, p_code), updated_at = now() WHERE user_id = p_user_id;
        INSERT INTO public.system_events (event_type, actor_id, entity_type, entity_id, metadata)
        VALUES ('security', p_user_id, 'mfa', p_user_id,
            jsonb_build_object('security_event_type', 'mfa.backup_code_used', 'severity', 'warning',
                'code_prefix', substring(p_code, 1, 4)));
        RETURN true;
    END IF;

    IF p_code IS NULL OR length(p_code) != 6 OR p_code !~ '^\d+$' THEN
        INSERT INTO public.system_events (event_type, actor_id, entity_type, entity_id, metadata)
        VALUES ('security', p_user_id, 'mfa', p_user_id,
            jsonb_build_object('security_event_type', 'mfa.verification_failed', 'severity', 'warning', 'reason', 'invalid_format'));
        RETURN false;
    END IF;

    FOR v_step IN -1..1 LOOP
      v_expected := public.generate_totp(v_secret.secret, v_now + (v_step * 30));
      IF p_code = v_expected THEN
        INSERT INTO public.system_events (event_type, actor_id, entity_type, entity_id, metadata)
        VALUES ('security', p_user_id, 'mfa', p_user_id,
            jsonb_build_object('security_event_type', 'mfa.verified', 'severity', 'info'));
        RETURN true;
      END IF;
    END LOOP;

    INSERT INTO public.system_events (event_type, actor_id, entity_type, entity_id, metadata)
    VALUES ('security', p_user_id, 'mfa', p_user_id,
        jsonb_build_object('security_event_type', 'mfa.verification_failed', 'severity', 'warning', 'reason', 'invalid_code'));
    RETURN false;
END; $function$
;

