    property_id,
    department_id,
    created_at
   FROM system_events
  WHERE (event_type = 'activity'::text);

CREATE VIEW public.ai_generation_analytics WITH (security_invoker=true) AS
 SELECT date_trunc('day'::text, created_at) AS day,
    provider,
    model_used,
    agent_role,
    cost_tier,
    count(*) AS requests,
    count(*) FILTER (WHERE success) AS successes,
    count(*) FILTER (WHERE (NOT success)) AS failures,
    round(avg(latency_ms)) AS avg_latency_ms,
    max(latency_ms) AS max_latency_ms,
    sum(total_tokens) AS total_tokens,
    sum(estimated_cost_usd) AS total_cost_usd,
    sum(retry_count) AS total_retries,
    sum(fallback_count) AS total_fallbacks
   FROM ai_usage_log
  GROUP BY (date_trunc('day'::text, created_at)), provider, model_used, agent_role, cost_tier;

