        CASE (status)::text
            WHEN 'not_started'::text THEN 'assigned'::learning_assignment_status
            WHEN 'in_progress'::text THEN 'in_progress'::learning_assignment_status
            WHEN 'completed'::text THEN 'completed'::learning_assignment_status
            WHEN 'expired'::text THEN 'overdue'::learning_assignment_status
            ELSE 'assigned'::learning_assignment_status
        END AS status,
    COALESCE(progress_percentage, 0) AS progress_percentage,
    score_percentage,
    passed,
    completed_at,
    COALESCE(last_accessed_at, now()) AS last_accessed_at,
    last_session_id,
    created_at,
    updated_at,
    training_id AS training_module_id,
    COALESCE(is_deleted, false) AS is_deleted,
    last_block_index,
    last_block_id,
    COALESCE(time_spent_seconds, 0) AS time_spent_seconds,
    COALESCE(last_activity_at, now()) AS last_activity_at,
    metadata,
    acknowledged_at
   FROM training_progress;

CREATE VIEW public.pii_access_logs_v WITH (security_invoker=true) AS
 SELECT id,
    actor_id,
    entity_id AS target_user_id,
    ARRAY( SELECT jsonb_array_elements_text((se.metadata -> 'fields_accessed'::text)) AS jsonb_array_elements_text) AS fields_accessed,
    (metadata ->> 'reason'::text) AS reason,
    created_at,
    entity_id AS user_id,
    (metadata ->> 'resource_type'::text) AS resource_type,
    (metadata ->> 'access_type'::text) AS access_type,
    (metadata ->> 'approved_by'::text) AS approved_by,
    (metadata ->> 'justification'::text) AS justification,
    (NULLIF((metadata ->> 'approved_at'::text), ''::text))::timestamp with time zone AS approved_at,
    ( SELECT jsonb_build_object('full_name', ap.full_name, 'email', ap.email) AS jsonb_build_object
           FROM profiles ap
          WHERE (ap.id = se.actor_id)) AS accessed_by_profile,
    ( SELECT jsonb_build_object('full_name', tp.full_name, 'email', tp.email) AS jsonb_build_object
           FROM profiles tp
          WHERE (tp.id = se.entity_id)) AS "user",
    ( SELECT jsonb_build_object('full_name', pp.full_name, 'email', pp.email) AS jsonb_build_object
           FROM profiles pp
          WHERE (pp.id = (NULLIF((se.metadata ->> 'approved_by'::text), ''::text))::uuid)) AS approved_by_profile
   FROM system_events se
  WHERE (event_type = 'pii_access'::text);

