    count(
        CASE
            WHEN ((m.sender_id = p.id) AND (m.status <> 'archived'::text)) THEN 1
            ELSE NULL::integer
        END) AS sent_messages,
    count(
        CASE
            WHEN ((m.recipient_id = p.id) AND (m.status <> 'archived'::text)) THEN 1
            ELSE NULL::integer
        END) AS received_messages,
    count(
        CASE
            WHEN ((m.recipient_id = p.id) AND (m.status = 'sent'::text)) THEN 1
            ELSE NULL::integer
        END) AS unread_messages,
    count(
        CASE
            WHEN ((m.priority = 'urgent'::text) AND (m.recipient_id = p.id) AND (m.status <> 'archived'::text)) THEN 1
            ELSE NULL::integer
        END) AS urgent_messages
   FROM (profiles p
     LEFT JOIN messages m ON (((p.id = m.sender_id) OR (p.id = m.recipient_id))))
  WHERE (p.is_active = true)
  GROUP BY p.id, p.full_name, p.email;

CREATE VIEW public.user_roles WITH (security_invoker=true) AS
 SELECT DISTINCT ON (om.user_id, om.organization_id, r.role) (md5((((om.user_id)::text || (om.organization_id)::text) || (r.role)::text)))::uuid AS id,
    om.user_id,
    r.role,
    om.organization_id
   FROM (organization_memberships om
     CROSS JOIN LATERAL unnest(membership_app_roles(om.role)) r(role))
  WHERE (om.is_active AND org_is_operational(om.organization_id))
  ORDER BY om.user_id, om.organization_id, r.role;

