-- ==========================================================================
-- Policies
-- ==========================================================================

CREATE POLICY account_action_notes_insert ON public.account_action_notes AS PERMISSIVE FOR INSERT TO authenticated
  WITH CHECK ((org_visible(organization_id) AND is_tenant_people_admin(organization_id)));

CREATE POLICY account_action_notes_select ON public.account_action_notes AS PERMISSIVE FOR SELECT TO authenticated
  USING (((org_visible(organization_id) AND is_tenant_people_admin(organization_id)) OR is_platform_super_admin()));

CREATE POLICY account_action_notes_service_role_all ON public.account_action_notes AS PERMISSIVE FOR ALL TO service_role
  USING (true)
  WITH CHECK (true);

CREATE POLICY achievement_definitions_manage_admin_delete ON public.achievement_definitions AS PERMISSIVE FOR DELETE TO authenticated
  USING (is_platform_super_admin());

CREATE POLICY achievement_definitions_manage_admin_insert ON public.achievement_definitions AS PERMISSIVE FOR INSERT TO authenticated
  WITH CHECK (is_platform_super_admin());

CREATE POLICY achievement_definitions_manage_admin_update ON public.achievement_definitions AS PERMISSIVE FOR UPDATE TO authenticated
  USING (is_platform_super_admin())
  WITH CHECK (is_platform_super_admin());

CREATE POLICY achievement_definitions_select ON public.achievement_definitions AS PERMISSIVE FOR SELECT TO authenticated
  USING (((is_active = true) OR is_platform_super_admin()));

CREATE POLICY ai_agent_policies_select ON public.ai_agent_policies AS PERMISSIVE FOR SELECT TO authenticated
  USING (true);

CREATE POLICY ai_agent_policies_write_delete ON public.ai_agent_policies AS PERMISSIVE FOR DELETE TO authenticated
  USING (is_platform_super_admin());

CREATE POLICY ai_agent_policies_write_insert ON public.ai_agent_policies AS PERMISSIVE FOR INSERT TO authenticated
  WITH CHECK (is_platform_super_admin());

CREATE POLICY ai_agent_policies_write_update ON public.ai_agent_policies AS PERMISSIVE FOR UPDATE TO authenticated
  USING (is_platform_super_admin())
  WITH CHECK (is_platform_super_admin());

CREATE POLICY ai_model_probes_select ON public.ai_model_probes AS PERMISSIVE FOR SELECT TO authenticated
  USING (true);

CREATE POLICY ai_model_probes_write_delete ON public.ai_model_probes AS PERMISSIVE FOR DELETE TO authenticated
  USING (( SELECT is_platform_super_admin() AS is_platform_super_admin));

CREATE POLICY ai_model_probes_write_insert ON public.ai_model_probes AS PERMISSIVE FOR INSERT TO authenticated
  WITH CHECK (( SELECT is_platform_super_admin() AS is_platform_super_admin));

CREATE POLICY ai_model_probes_write_update ON public.ai_model_probes AS PERMISSIVE FOR UPDATE TO authenticated
  USING (( SELECT is_platform_super_admin() AS is_platform_super_admin))
  WITH CHECK (( SELECT is_platform_super_admin() AS is_platform_super_admin));

CREATE POLICY ai_models_select ON public.ai_models AS PERMISSIVE FOR SELECT TO authenticated
  USING (true);

CREATE POLICY ai_models_write_delete ON public.ai_models AS PERMISSIVE FOR DELETE TO authenticated
  USING (is_platform_super_admin());

CREATE POLICY ai_models_write_insert ON public.ai_models AS PERMISSIVE FOR INSERT TO authenticated
  WITH CHECK (is_platform_super_admin());

CREATE POLICY ai_models_write_update ON public.ai_models AS PERMISSIVE FOR UPDATE TO authenticated
