  USING (((is_active = true) OR is_platform_operator()));

CREATE POLICY "Platform operators can manage wizard definitions_delete" ON public.wizard_definitions AS PERMISSIVE FOR DELETE TO authenticated
  USING (is_platform_operator());

CREATE POLICY "Platform operators can manage wizard definitions_insert" ON public.wizard_definitions AS PERMISSIVE FOR INSERT TO authenticated
  WITH CHECK (is_platform_operator());

