  USING (is_platform_operator())
  WITH CHECK (is_platform_operator());

CREATE POLICY "Admins can delete/reset wizard progress" ON public.wizard_user_progress AS PERMISSIVE FOR DELETE TO authenticated
  USING (((user_id = ( SELECT auth.uid() AS uid)) OR is_platform_operator() OR ((organization_id IS NOT NULL) AND (organization_id IN ( SELECT om.organization_id
   FROM organization_memberships om
  WHERE ((om.user_id = ( SELECT auth.uid() AS uid)) AND (om.role = ANY (ARRAY['organization_owner'::membership_role, 'organization_admin'::membership_role])) AND (om.is_active = true)))))));

CREATE POLICY "Users and admins can update wizard progress" ON public.wizard_user_progress AS PERMISSIVE FOR UPDATE TO authenticated
  USING (((user_id = ( SELECT auth.uid() AS uid)) OR is_platform_operator() OR ((organization_id IS NOT NULL) AND (organization_id IN ( SELECT om.organization_id
   FROM organization_memberships om
  WHERE ((om.user_id = ( SELECT auth.uid() AS uid)) AND (om.role = ANY (ARRAY['organization_owner'::membership_role, 'organization_admin'::membership_role])) AND (om.is_active = true)))))))
  WITH CHECK (((user_id = ( SELECT auth.uid() AS uid)) OR is_platform_operator() OR ((organization_id IS NOT NULL) AND (organization_id IN ( SELECT om.organization_id
   FROM organization_memberships om
  WHERE ((om.user_id = ( SELECT auth.uid() AS uid)) AND (om.role = ANY (ARRAY['organization_owner'::membership_role, 'organization_admin'::membership_role])) AND (om.is_active = true)))))));

