  USING (((user_id = ( SELECT auth.uid() AS uid)) OR is_platform_operator() OR ((organization_id IS NOT NULL) AND (organization_id IN ( SELECT om.organization_id
   FROM organization_memberships om
  WHERE ((om.user_id = ( SELECT auth.uid() AS uid)) AND (om.role = ANY (ARRAY['organization_owner'::membership_role, 'organization_admin'::membership_role])) AND (om.is_active = true)))))));

CREATE POLICY "Allow authenticated deletes to training folder" ON storage.objects AS PERMISSIVE FOR DELETE TO public
  USING (((bucket_id = 'documents'::text) AND ((storage.foldername(name))[1] = 'training'::text) AND has_any_role(( SELECT auth.uid() AS uid), ARRAY['corporate_admin'::app_role, 'regional_admin'::app_role, 'regional_hr'::app_role, 'property_manager'::app_role])));

CREATE POLICY "Allow authenticated to read documents bucket objects" ON storage.objects AS PERMISSIVE FOR SELECT TO public
  USING (((bucket_id = 'documents'::text) AND (EXISTS ( SELECT 1
   FROM documents d
  WHERE (((d.file_url = objects.name) OR (d.file_url ~~ ('%/'::text || objects.name))) AND can_view_document(d.id))))));

CREATE POLICY "Allow authenticated updates to training folder" ON storage.objects AS PERMISSIVE FOR UPDATE TO public
  USING (((bucket_id = 'documents'::text) AND ((storage.foldername(name))[1] = 'training'::text) AND has_any_role(( SELECT auth.uid() AS uid), ARRAY['corporate_admin'::app_role, 'regional_admin'::app_role, 'regional_hr'::app_role, 'property_manager'::app_role])))
  WITH CHECK (((bucket_id = 'documents'::text) AND ((storage.foldername(name))[1] = 'training'::text) AND has_any_role(( SELECT auth.uid() AS uid), ARRAY['corporate_admin'::app_role, 'regional_admin'::app_role, 'regional_hr'::app_role, 'property_manager'::app_role])));

CREATE POLICY "Allow authenticated uploads maintenance" ON storage.objects AS PERMISSIVE FOR INSERT TO authenticated
