CREATE POLICY "Allow authenticated uploads to training folder" ON storage.objects AS PERMISSIVE FOR INSERT TO public
  WITH CHECK (((bucket_id = 'documents'::text) AND ((storage.foldername(name))[1] = 'training'::text) AND has_any_role(( SELECT auth.uid() AS uid), ARRAY['corporate_admin'::app_role, 'regional_admin'::app_role, 'regional_hr'::app_role, 'property_manager'::app_role])));

