  WITH CHECK (((bucket_id = 'media'::text) AND (((storage.foldername(name))[1] = (auth.uid())::text) OR is_platform_operator() OR (((storage.foldername(name))[1] ~ '^[0-9a-f-]{36}$'::text) AND (((storage.foldername(name))[1])::uuid = ANY (current_user_organization_ids()))))));

