-- ==========================================================================
-- Scheduled jobs (pg_cron)
-- ==========================================================================

SELECT cron.schedule('ai-model-verifier-nightly', '30 3 * * *', '
    SELECT net.http_post(
      url := ''https://dhbfaclkfysqwfppuxxa.supabase.co/functions/v1/ai-model-verifier'',
      headers := jsonb_build_object(''Content-Type'',''application/json'',''Authorization'',''Bearer '' || (SELECT decrypted_secret FROM vault.decrypted_secrets WHERE name = ''service_role_key'' LIMIT 1)),
      body := ''{"mode":"all","onlyUnverified":true,"source":"cron"}''::jsonb,
      timeout_milliseconds := 120000
    );
    ');
SELECT cron.alter_job((SELECT jobid FROM cron.job WHERE jobname = 'ai-model-verifier-nightly'), active => false);

SELECT cron.schedule('check-escalations', '0 * * * *', 'SELECT public.check_and_escalate_approvals();');

SELECT cron.schedule('cleanup-transient-records', '45 2 * * *', 'SELECT public.cleanup_transient_records();');

SELECT cron.schedule('evaluate-org-quotas-daily', '0 7 * * *', 'SELECT public.evaluate_organization_quotas(id) FROM public.organizations WHERE is_deleted = false AND lifecycle_status NOT IN (''archived'',''suspended'');');

SELECT cron.schedule('process-certificate-expirations-job', '0 6 * * *', 'SELECT public.process_certificate_expirations();');

SELECT cron.schedule('purge-archived-organizations', '30 2 * * *', 'SELECT public.purge_archived_organizations();');

SELECT cron.schedule('reset-monthly-ai-credits', '5 0 1 * *', 'SELECT public.reset_monthly_ai_credits();');

SELECT cron.schedule('training-notifications-job', '0 8 * * *', '
select net.http_post(
  url:=''https://dhbfaclkfysqwfppuxxa.supabase.co/functions/v1/training-notifications'',
  headers:=jsonb_build_object(
    ''Content-Type'',''application/json'',
    ''Authorization'',''Bearer '' || (select decrypted_secret from vault.decrypted_secrets where name=''service_role_key'' limit 1)
  ),
  timeout_milliseconds:=30000
) as request_id;
');

SELECT cron.schedule('weekly-maintenance', '0 3 * * 0', 'VACUUM ANALYZE;');
